import type { OptionalFeatureId } from "../../../types/module/OptionalFeature";
import { MODULE_ID } from "../../constants";
import { BOSS_BAR_FEATURES, BOSS_BAR_SETTINGS } from "../integrations/bossbar/constants";
import { isOptionalFeatureAvailable, OPTIONAL_FEATURES } from "./optional-features";

export function isOptionalFeatureEnabled(featureId: OptionalFeatureId): boolean {
  if (!isOptionalFeatureAvailable(featureId)) return false;
  if (featureId === "bossBar")
    return (
      game?.system.id === "wfrp4e" &&
      BOSS_BAR_FEATURES.some(
        (key) => game?.settings.get(MODULE_ID, BOSS_BAR_SETTINGS[key]) === true,
      )
    );
  const settingKey = OPTIONAL_FEATURES[featureId].settingKey;
  return settingKey !== null && game?.settings.get(MODULE_ID, settingKey) !== false;
}
