import type {
  CalendarContentOptions,
  ContentDocument,
  ContentDraft,
  ContentImportResult,
} from "../../../../types/integrations/calendars/Content";
import { MODULE_ID } from "../../../constants";
import {
  addCalendarDates,
  calendarContentDrafts,
  SC_NOTES,
  ST_EVENTS,
} from "../../../functions/calendars/content";
import {
  IMPERIAL_MONTHS,
  IMPERIAL_WEEKDAYS,
  imperialDate,
  imperialTimestamp,
} from "../../../functions/calendars/imperial";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { usesImperialCalendar } from "../simple-timekeeping/register-integration";

export function contentTargets(options: CalendarContentOptions) {
  if (!game?.ready || !game.user?.isGM || game.system.id !== "wfrp4e")
    throw new Error("A ready WFRP GM session is required to import calendar content.");
  const simpleCalendar = isOptionalFeatureEnabled("simpleCalendar");
  const timekeeping = isOptionalFeatureEnabled("simpleTimekeeping");
  if (!simpleCalendar && !timekeeping)
    throw new Error("Enable a supported calendar compatibility feature first.");
  if (options.holidays === false && options.history === false) return { timekeeping: false };
  let calendarId: string | undefined;
  if (simpleCalendar) {
    calendarId = String(game.settings.get(SC_NOTES, "active-calendar"));
    const calendars = game.settings.get(SC_NOTES, "calendar-configuration") as {
      id: string;
      months: ((typeof IMPERIAL_MONTHS)[number] & {
        intercalaryInclude: boolean;
        startingWeekday: number | null;
      })[];
      weekdays: typeof IMPERIAL_WEEKDAYS;
      year: { yearZero: number; firstWeekday: number };
      leapYear: { rule: string };
      time: { hoursInDay: number; minutesInHour: number; secondsInMinute: number };
    }[];
    const calendar = calendars?.find((c) => c.id === calendarId);
    if (
      !calendar ||
      calendar.year?.yearZero !== 1 ||
      calendar.year.firstWeekday !== 0 ||
      calendar.leapYear?.rule !== "none" ||
      calendar.time?.hoursInDay !== 24 ||
      calendar.time.minutesInHour !== 60 ||
      calendar.time.secondsInMinute !== 60 ||
      calendar.months?.length !== IMPERIAL_MONTHS.length ||
      calendar.weekdays?.length !== IMPERIAL_WEEKDAYS.length ||
      !IMPERIAL_MONTHS.every(
        (m, i) =>
          calendar.months[i]?.name === m.name &&
          calendar.months[i]?.numberOfDays === m.numberOfDays &&
          calendar.months[i]?.intercalary === m.intercalary &&
          calendar.months[i]?.intercalaryInclude === false &&
          calendar.months[i]?.startingWeekday === null,
      ) ||
      !IMPERIAL_WEEKDAYS.every((d, i) => calendar.weekdays[i]?.name === d.name)
    )
      throw new Error(
        "Apply the Simple Calendar WFRP Imperial preset before importing dated content.",
      );
  }
  if (
    timekeeping &&
    (!usesImperialCalendar() ||
      game.time.calendar.componentsToTime({ year: 1, day: 0, hour: 0, minute: 0, second: 0 }) !==
        400 * 86400)
  )
    throw new Error(
      "Apply the ST&C WFRP Imperial preset and reload before importing dated content.",
    );
  return { ...(calendarId ? { calendarId } : {}), timekeeping };
}
function managedId(doc: { flags: Record<string, Record<string, unknown>> }): unknown {
  return (doc.flags[MODULE_ID]?.["calendarContent"] as { id?: string } | undefined)?.id;
}
function existingDocument(draft: ContentDraft): ContentDocument | undefined {
  return [...game!.journal].find((doc) => managedId(doc) === managedId(draft));
}
function duplicateDocument(draft: ContentDraft): ContentDocument | undefined {
  return [...game!.journal].find(
    (doc) =>
      doc.id === draft._id || doc.name.toLocaleLowerCase() === draft.name.toLocaleLowerCase(),
  );
}

export function inspectCalendarContent(options: CalendarContentOptions = {}) {
  const targets = contentTargets(options);
  const drafts = calendarContentDrafts(
    MODULE_ID,
    options,
    targets,
    imperialDate(game!.time.worldTime).year,
  );
  return {
    targets,
    drafts,
    entries: drafts.map((d) => ({
      name: d.name,
      status: existingDocument(d)
        ? "Keep existing content; connect missing calendar support"
        : duplicateDocument(d)
          ? "Skip: matching name or document ID already exists"
          : "Create",
    })),
  };
}

let importing = false;
/** Only explicit calls import content. Existing prose, dates, ownership and reminders are never replaced. */
export async function importCalendarContent(
  options: CalendarContentOptions = {},
  expectedTargets?: { calendarId?: string; timekeeping: boolean },
): Promise<ContentImportResult> {
  if (importing) throw new Error("A calendar content import is already running.");
  const plan = inspectCalendarContent(options);
  if (
    expectedTargets &&
    (expectedTargets.calendarId !== plan.targets.calendarId ||
      expectedTargets.timekeeping !== plan.targets.timekeeping)
  )
    throw new Error("Calendar availability changed after review. Review the content again.");
  importing = true;
  const result: ContentImportResult = { created: [], connected: [], skipped: [] };
  try {
    let folderId: string | undefined;
    const destination = async () => {
      if (folderId) return folderId;
      const root = plan.targets.calendarId
        ? [...game!.folders].find(
            (f) => f.type === "JournalEntry" && (f.flags?.[SC_NOTES] as { root?: boolean })?.root,
          )
        : undefined;
      if (plan.targets.calendarId && !root)
        throw new Error("Simple Calendar's notes folder is not ready. Reload and try again.");
      const existing = [...game!.folders].find(
        (f) =>
          f.type === "JournalEntry" &&
          (f.flags?.[MODULE_ID] as { calendarContentFolder?: boolean })?.calendarContentFolder &&
          (f.folder?.id ?? null) === (root?.id ?? null),
      );
      const folder =
        existing ??
        (await CONFIG.Folder.documentClass.create({
          name: "WFRP Calendar",
          type: "JournalEntry",
          folder: root?.id ?? null,
          flags: { [MODULE_ID]: { calendarContentFolder: true } },
        }));
      if (!folder) throw new Error("Could not create the WFRP Calendar folder.");
      folderId = folder.id;
      return folderId;
    };
    for (const draft of plan.drafts) {
      // Permissions, modules and target calendar can change during awaited document writes.
      const latest = contentTargets(options);
      if (
        latest.calendarId !== plan.targets.calendarId ||
        latest.timekeeping !== plan.targets.timekeeping
      )
        throw new Error(
          "Calendar availability changed during import. Review the remaining content again.",
        );
      const existing = existingDocument(draft);
      if (existing) {
        const changes: Record<string, unknown> = {};
        const page = existing.pages.contents.find((p) => p.id === draft.pages[0]!._id);
        const scData = existing.flags[SC_NOTES]?.["noteData"] as
          | {
              calendarId?: string;
              startDate: {
                year: number;
                month: number;
                day: number;
                hour: number;
                minute: number;
                seconds: number;
              };
              endDate: {
                year: number;
                month: number;
                day: number;
                hour: number;
                minute: number;
                seconds: number;
              };
              repeats: number;
              allDay?: boolean;
            }
          | undefined;
        const stData = page?.flags[ST_EVENTS];
        if (scData && scData.calendarId !== plan.targets.calendarId && plan.targets.calendarId) {
          result.skipped.push(`${draft.name}: already connected to another Simple Calendar`);
          continue;
        }
        // A companion added later must inherit the existing event's date, including GM edits
        // and its original anchor year. Never regenerate it using this year's catalog dates.
        try {
          if (scData && plan.targets.timekeeping && stData?.["eventTime"] === undefined) {
            if (![0, 3].includes(scData.repeats)) throw new Error("unsupported repetition");
            const timestamp = (d: typeof scData.startDate, end = false) =>
              imperialTimestamp({
                year: d.year,
                month: d.month,
                day: d.day,
                hour: scData.allDay ? (end ? 23 : 0) : d.hour,
                minute: scData.allDay ? (end ? 59 : 0) : d.minute,
                second: scData.allDay ? (end ? 59 : 0) : d.seconds,
              });
            addCalendarDates(
              draft,
              timestamp(scData.startDate),
              timestamp(scData.endDate, true),
              scData.repeats === 3,
              undefined,
              true,
            );
          } else if (!scData && draft.flags[SC_NOTES] && stData?.["eventTime"] !== undefined) {
            if (!["", "year"].includes(String(stData["repeat"] ?? "")))
              throw new Error("unsupported repetition");
            const start = Number(stData["eventTime"]);
            const end = Number(stData["eventEnd"] ?? start);
            addCalendarDates(
              draft,
              start,
              end,
              stData["repeat"] === "year",
              plan.targets.calendarId,
              false,
            );
          }
        } catch {
          result.skipped.push(
            `${draft.name}: existing date or repetition cannot be connected safely`,
          );
          continue;
        }
        const sc = draft.flags[SC_NOTES];
        const st = draft.pages[0]!.flags[ST_EVENTS];
        if (sc && !scData) {
          changes[`flags.${SC_NOTES}.noteData`] = sc["noteData"];
          changes[`flags.core.sheetClass`] = `${SC_NOTES}.NoteSheet`;
          changes["folder"] = await destination();
        }
        if (Object.keys(changes).length) await existing.update(changes);
        // Only connect the original content page, never an arbitrary user-added page.
        const addSt = !!st && !!page && page.flags[ST_EVENTS]?.["eventTime"] === undefined;
        if (addSt)
          await existing.updateEmbeddedDocuments("JournalEntryPage", [
            { _id: page!.id, [`flags.${ST_EVENTS}`]: st },
          ]);
        if (Object.keys(changes).length || addSt) result.connected.push(draft.name);
        else result.skipped.push(`${draft.name}: existing content preserved`);
        continue;
      }
      if (duplicateDocument(draft)) {
        result.skipped.push(`${draft.name}: matching name or document ID exists`);
        continue;
      }
      draft.folder = await destination();
      const created = await CONFIG.JournalEntry.documentClass.create(draft, {
        keepId: true,
        keepEmbeddedIds: true,
      });
      if (!created)
        throw new Error(
          `Could not create ${draft.name}. Earlier successful imports are retained; retry safely.`,
        );
      result.created.push(draft.name);
    }
    return result;
  } finally {
    importing = false;
  }
}
