import { MODULE_ID } from "../../../../constants";
import type {
  MigrationRecovery,
  MigrationRecoveryReference,
  MigrationPlan,
} from "../../../../../types/integrations/calendars/Migration";

export const MIGRATION_SETTING = "calendarMigrationRecovery";
export function calendarMigrationReference(): MigrationRecoveryReference | null {
  // The guard also supports older worlds/tests before this hidden setting is registered.
  if (!game?.settings.settings?.has(`${MODULE_ID}.${MIGRATION_SETTING}`)) return null;
  return game.settings.get(MODULE_ID, MIGRATION_SETTING) as MigrationRecoveryReference | null;
}
export function calendarMigrationRecovery(): MigrationRecovery | null {
  const reference = calendarMigrationReference();
  if (!reference) return null;
  const journal = [...game!.journal].find((j) => j.id === reference.journal);
  const plan = journal?.flags[MODULE_ID]?.["calendarMigrationPlan"] as MigrationPlan | undefined;
  if (!plan)
    throw new Error(
      "The GM recovery journal is unavailable. Restore access to that journal before continuing.",
    );
  return { status: reference.status, created: reference.created, plan };
}
export function calendarMigrationPending(): boolean {
  const status = calendarMigrationReference()?.status;
  return status === "applying" || status === "failed";
}
