import definition from "./imperial.json";
import type { CalendarDate } from "../../../types/integrations/calendars/Calendar";

export const IMPERIAL_CALENDAR_ID = "wfrp4e-compatibility-box-imperial";
export const IMPERIAL_MONTHS = definition.months;
export const IMPERIAL_WEEKDAYS = definition.weekdays;
export const SECONDS_PER_DAY = 86400;
export const DAYS_PER_YEAR = 400;
const mod = (value: number, divisor: number) => ((value % divisor) + divisor) % divisor;

/** Timestamp zero is the first day of IC year 1, matching native ST&C labels. */
export function imperialDate(timestamp: number): CalendarDate {
  if (!Number.isFinite(timestamp) || Math.abs(timestamp) > Number.MAX_SAFE_INTEGER)
    throw new Error("Calendar timestamp is outside the supported range.");
  timestamp = Math.floor(timestamp);
  const days = Math.floor(timestamp / SECONDS_PER_DAY);
  const elapsedYears = Math.floor(days / DAYS_PER_YEAR);
  const year = elapsedYears + 1;
  let day = mod(days, DAYS_PER_YEAR);
  let month = 0;
  let weekdays = elapsedYears * 394;
  while (day >= IMPERIAL_MONTHS[month]!.numberOfDays) {
    const current = IMPERIAL_MONTHS[month++]!;
    day -= current.numberOfDays;
    if (!current.intercalary) weekdays += current.numberOfDays;
  }
  const seconds = mod(timestamp, SECONDS_PER_DAY);
  return {
    year,
    month,
    day,
    hour: Math.floor(seconds / 3600),
    minute: Math.floor(seconds / 60) % 60,
    second: seconds % 60,
    weekday: mod(weekdays + day, 8),
  };
}

export function imperialTimestamp(date: Omit<CalendarDate, "weekday">): number {
  const month = IMPERIAL_MONTHS[date.month];
  if (
    !Object.values(date).every(Number.isSafeInteger) ||
    !month ||
    date.day < 0 ||
    date.day >= month.numberOfDays ||
    date.hour < 0 ||
    date.hour >= 24 ||
    date.minute < 0 ||
    date.minute >= 60 ||
    date.second < 0 ||
    date.second >= 60
  )
    throw new Error("Choose a valid Imperial calendar date and time.");
  const days =
    (date.year - 1) * DAYS_PER_YEAR +
    IMPERIAL_MONTHS.slice(0, date.month).reduce((sum, m) => sum + m.numberOfDays, 0) +
    date.day;
  const timestamp = days * SECONDS_PER_DAY + date.hour * 3600 + date.minute * 60 + date.second;
  if (!Number.isSafeInteger(timestamp))
    throw new Error("Calendar date is outside the supported range.");
  return timestamp;
}

export function imperialDateText(timestamp: number, includeTime = false): string {
  const date = imperialDate(timestamp);
  const month = IMPERIAL_MONTHS[date.month]!;
  const pad = (n: number) => String(n).padStart(2, "0");
  if (includeTime)
    return `${date.year} ${month.name} ${pad(date.day + 1)} ${pad(date.hour)}:${pad(date.minute)}:${pad(date.second)}`;
  return `${month.intercalary ? "" : `${IMPERIAL_WEEKDAYS[date.weekday]!.name}, `}${month.name} ${pad(date.day + 1)}, ${date.year}`;
}

export function timekeepingCalendar() {
  return {
    id: IMPERIAL_CALENDAR_ID,
    name: "WFRP Imperial Calendar",
    description:
      "Compatibility Box: 400 days, eight weekdays, six festivals outside the week; timestamp zero displays IC year 1.",
    years: { yearZero: 0, firstWeekday: 0 },
    months: {
      values: IMPERIAL_MONTHS.map((m) => ({
        name: m.name,
        abbreviation: m.abbreviation,
        ordinal: Math.max(1, m.numericRepresentation),
        days: m.numberOfDays,
        intercalary: m.intercalary,
        startingWeekday: null,
      })),
    },
    days: {
      values: IMPERIAL_WEEKDAYS.map((d, i) => ({ ...d, ordinal: i + 1 })),
      daysPerYear: 400,
      hoursPerDay: 24,
      minutesPerHour: 60,
      secondsPerMinute: 60,
    },
    seasons: {
      values: [
        { name: "Spring", dayStart: 17, dayEnd: 116 },
        { name: "Summer", dayStart: 117, dayEnd: 216 },
        { name: "Fall", dayStart: 217, dayEnd: 316 },
        { name: "Winter", dayStart: 317, dayEnd: 16 },
      ],
    },
  };
}
