import type { SyncDocument } from "../../../../types/integrations/calendars/EventSync";
import { SC_NOTES } from "../../../functions/calendars/content";

let refreshPending = false;
/** SCR indexes native document creates/deletes but does not redraw those changes itself. */
export function refreshCalendar(doc: SyncDocument): void {
  if (!doc.flags[SC_NOTES]?.["noteData"] || refreshPending) return;
  refreshPending = true;
  queueMicrotask(() => {
    refreshPending = false;
    const windows = (
      ui as unknown as { windows?: Record<string, { id: string; render(force: boolean): unknown }> }
    )?.windows;
    for (const app of Object.values(windows ?? {})) if (app.id === "fsc-if") app.render(false);
  });
}
