import { applySimpleQuestTemplate } from "./apply-template";
import type { TemplateRuntime, TemplateSheet } from "./types";

// SQ 5.3.0/5.4.5's template chooser metadata. Its bundled insertion function is private.
const ICONS: Record<string, string> = {
  "banner": "fad fa-scroll-old",
  "character": "fad fa-user",
  "dynamic-columns": "fad fa-columns",
  "image-text-left": "fad fa-image",
  "image-text-right": "fad fa-image",
  "location": "fad fa-place-of-worship",
  "boxed-text": "fad fa-paragraph",
  "description-text": "fad fa-text",
  "character-grid-1x2": "fad fa-user",
  "character-grid-1x3": "fad fa-user",
  "wiki": "fad fa-book",
  "event": "fad fa-calendar",
};

export async function openTemplateDialog(
  app: TemplateSheet,
  runtime: TemplateRuntime,
): Promise<void> {
  const picker = runtime.applications.apps.FilePicker.implementation;
  const templates = (await picker.browse("data", "modules/simple-quest/templates/JournalTemplates"))
    .files;
  let customTemplates: string[] = [];
  try {
    customTemplates = (
      await picker.browse("user", "modules/simple-quest/storage", { extensions: [".html"] })
    ).files;
  } catch (error) {
    console.error(error);
  }
  const buttons = templates.concat(customTemplates).map((path) => {
    const slug = path.split("/").pop()!.split(".").slice(0, -1).join(".");
    return {
      action: slug,
      label: slug
        .split("-")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" "),
      icon: ICONS[slug] ?? "fad fa-file-invoice",
      callback: () => applySimpleQuestTemplate(path, app, runtime),
    };
  });
  const dialog = await new runtime.applications.api.DialogV2({
    window: { title: game!.i18n.localize("simple-quest.page-template.label") },
    content: game!.i18n.localize("simple-quest.page-template.description"),
    position: { width: 600 },
    buttons,
  }).render({ force: true });
  dialog.classList.add("simple-quest-dialog", "page-template-dialog");
}
