import type { TimekeepingCalendar } from "../../../../types/integrations/calendars/Calendar";
import { imperialDate } from "../../../functions/calendars/imperial";

/** Patch the ST&C calendar prototype so native rebuilds also cache corrected components. */
export function installImperialTimekeeping(
  time: { calendar: TimekeepingCalendar; initializeCalendar(): void },
  enabled: () => boolean,
): void {
  const prototype = Object.getPrototypeOf(time.calendar) as TimekeepingCalendar;
  const original = prototype.timeToComponents;
  prototype.timeToComponents = function (timestamp = 0) {
    const result = original.call(this, timestamp);
    return enabled() ? { ...result, dayOfWeek: imperialDate(timestamp).weekday } : result;
  };
  // Foundry caches current components during initialization, before ST&C emits its ready hook.
  time.initializeCalendar();
}
