import { HEALTH_ESTIMATE_PRESET_EXTENSION } from "./preset";

interface HealthToken {
  actor?: { type: string; statuses: ReadonlySet<string> };
}
interface HealthEstimateRuntime {
  isDead: (token: HealthToken, stage: number) => boolean;
}
const patched = new WeakSet<HealthEstimateRuntime>();

/** Health Estimate 36.1: do not infer WFRP death from Wounds, defeated markers or module flags. */
export function registerHealthEstimateIntegration(): void {
  if (!HEALTH_ESTIMATE_PRESET_EXTENSION.enabled?.()) return;
  const runtime =
    game && (Reflect.get(game, "healthEstimate") as HealthEstimateRuntime | undefined);
  if (!runtime || typeof runtime.isDead !== "function" || patched.has(runtime)) return;
  const original = runtime.isDead;
  runtime.isDead = function (token, stage) {
    if (token.actor && ["character", "npc", "creature"].includes(token.actor.type)) {
      return token.actor.statuses.has("dead");
    }
    return original.call(this, token, stage);
  };
  patched.add(runtime);
}
