import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";

interface ArgonCoreHudConstructor {
  prototype: {
    performModuleCheck: (...args: unknown[]) => unknown;
  };
}

interface ArgonConfig {
  CORE?: {
    CoreHud?: ArgonCoreHudConstructor;
  };
}

/**
 * Argon 5.0.1 still checks for the retired `enhancedcombathud-wfrp4e` package ID
 * before it emits `argonInit`. The Compatibility Box replaces that package, so
 * suppress only that obsolete check while this integration is enabled.
 */
export function patchArgonLegacyModuleCheck(): void {
  const argon = (CONFIG as typeof CONFIG & { ARGON?: ArgonConfig }).ARGON;
  const CoreHud = argon?.CORE?.CoreHud;

  if (!CoreHud || typeof CoreHud.prototype.performModuleCheck !== "function") {
    throw new Error("Argon CoreHud.performModuleCheck is unavailable.");
  }

  const performModuleCheck = CoreHud.prototype.performModuleCheck;

  CoreHud.prototype.performModuleCheck = function (...args: unknown[]): unknown {
    if (isOptionalFeatureEnabled("argonCombatHud")) {
      return undefined;
    }

    return performModuleCheck.apply(this, args);
  };
}
