import type {
  CleanupCompendium,
  EmptyFolderDocument,
  EmptyFolderGroup,
  EmptyFolderResult,
  EmptyFolderScan,
  EmptyFolderScope,
} from "../../../types/folders/EmptyFolders";
import { planEmptyFolders } from "../../functions/folders/empty";
import { queueFolderTidy } from "./queue";

function requireGM(): NonNullable<typeof game> {
  if (!game?.ready || !game.user?.isGM)
    throw new Error("Only a GM in a loaded world can purge folders.");
  return game;
}

export async function scanEmptyFolders(scope: EmptyFolderScope): Promise<EmptyFolderScan> {
  const currentGame = requireGM();
  if (!["world", "compendiums", "both"].includes(scope)) throw new Error("Invalid folder scope.");
  const groups: EmptyFolderGroup[] = [];
  const packs = () =>
    [...currentGame.packs.entries()].map(([, pack]) => pack as unknown as CleanupCompendium);
  let skippedPacks = 0;
  if (scope !== "compendiums") {
    for (const [type, collection] of currentGame.collections.entries()) {
      if (type === "Folder" || !collection.documentClass.schema.has("folder")) continue;
      groups.push({
        label: `World: ${type}`,
        folders: () => [...currentGame.folders].filter((folder) => folder.type === type),
        occupied: () =>
          new Set([...collection].flatMap((doc) => (doc.folder ? [doc.folder.id] : []))),
        editable: () => true,
      });
    }
  }
  if (scope !== "world") {
    groups.push({
      label: "Compendium sidebar",
      folders: () => [...currentGame.folders].filter((folder) => folder.type === "Compendium"),
      occupied: () => new Set(packs().flatMap((pack) => (pack.folder ? [pack.folder.id] : []))),
      editable: () => true,
    });
    for (const pack of packs()) {
      if (pack.locked) {
        skippedPacks++;
        continue;
      }
      await pack.getIndex({ fields: ["folder"] });
      groups.push({
        label: `Compendium: ${pack.title}`,
        folders: () => [...pack.folders],
        occupied: () =>
          new Set([...pack.index].flatMap((entry) => (entry.folder ? [entry.folder] : []))),
        editable: () => !pack.locked && packs().includes(pack),
      });
    }
  }
  return {
    skippedPacks,
    candidates: groups.flatMap((group) =>
      planEmptyFolders(
        group.folders().map((folder) => ({
          id: folder.id,
          name: folder.name,
          parent: folder.folder?.id ?? null,
        })),
        group.occupied(),
      ).map((folder) => ({ group, id: folder.id, name: folder.name })),
    ),
  };
}

export async function removeEmptyFolders(scan: EmptyFolderScan): Promise<EmptyFolderResult> {
  const currentGame = requireGM();
  const result = { deleted: 0, skipped: 0 };
  // Serialize with the organizer; confirmation is deliberately outside the lock.
  await queueFolderTidy(currentGame, async () => {
    for (const candidate of scan.candidates) {
      requireGM();
      const { group, id } = candidate;
      const folders = group.folders();
      const folder: EmptyFolderDocument | undefined = folders.find((entry) => entry.id === id);
      if (
        !folder ||
        !group.editable() ||
        group.occupied().has(id) ||
        folders.some((entry) => entry.folder?.id === id)
      ) {
        result.skipped++;
        continue;
      }
      const deleted = await folder.delete({ deleteSubfolders: false, deleteContents: false });
      if (!deleted || group.folders().some((entry) => entry.id === id)) {
        throw new Error(
          `Could not remove empty folder "${folder.name}". ${result.deleted} folders removed before stopping.`,
        );
      }
      result.deleted++;
    }
  });
  return result;
}
