import type { PresetExtension } from "../../../../types/settings-presets/SettingsPreset";
import { configureSimpleCalendar } from "../../../functions/calendars/configuration";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";

export const SIMPLE_CALENDAR_MODULE_ID = "foundryvtt-simple-calendar-reborn";
function currentCalendars(): unknown {
  const saved = game?.settings.get(SIMPLE_CALENDAR_MODULE_ID, "calendar-configuration");
  if (!Array.isArray(saved) || saved.length) return saved;
  // A fresh installation can have an in-memory default before its first settings save.
  const api = (
    globalThis as typeof globalThis & { SimpleCalendar?: { api?: { getAllCalendars(): unknown } } }
  ).SimpleCalendar?.api;
  // Native unsaved defaults contain optional undefined fields (for example general.id).
  // Match the JSON representation SCR persists to its setting.
  return JSON.parse(JSON.stringify(api?.getAllCalendars() ?? saved));
}

export const SIMPLE_CALENDAR_PRESET: PresetExtension = {
  title: "Simple Calendar Reborn — WFRP Imperial Calendar",
  enabled: () => game?.system.id === "wfrp4e" && isOptionalFeatureEnabled("simpleCalendar"),
  additionalSettings: () => [
    {
      namespace: SIMPLE_CALENDAR_MODULE_ID,
      key: "calendar-configuration",
      value: configureSimpleCalendar(
        currentCalendars(),
        game?.settings.get(SIMPLE_CALENDAR_MODULE_ID, "active-calendar"),
        game!.time.worldTime,
        isOptionalFeatureEnabled("simpleTimekeeping"),
      ),
    },
  ],
};
