import type { FoundryGame } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { WFRP_TIDY_SETTINGS } from "./settings";

// These settings originated in this world module. Read saved preferences even
// when the predecessor is disabled, without registering or deleting its settings.
const PREDECESSOR_ID = "whence-they-hang";

export async function migrateWfrpTidySettings(currentGame: FoundryGame): Promise<void> {
  if (!currentGame.ready || !currentGame.user?.isGM) return;
  const storage = currentGame.settings.storage.get("world");
  if (!storage) throw new Error("World settings storage is unavailable during WFRP migration.");
  for (const key of WFRP_TIDY_SETTINGS) {
    if (storage.getSetting(`${MODULE_ID}.${key}`)) continue;
    const legacy = storage.getSetting(`${PREDECESSOR_ID}.${key}`)?.value;
    if (typeof legacy === "boolean") await currentGame.settings.set(MODULE_ID, key, legacy);
  }
}
