import { registerGroupedAction } from "../../../settings/groups/registry";
import type { MigrationChoices } from "../../../../../types/integrations/calendars/Migration";
import { MODULE_ID } from "../../../../constants";
import { IMPERIAL_MONTHS, imperialDateText } from "../../../../functions/calendars/imperial";
import { namedDateText, planCalendarMigration } from "../../../../functions/calendars/migration";
import { escapePresetHtml as escape } from "../../../settings/preset-runtime/presentation";
import { notifyError } from "../../../notifications/notify-user";
import { captureCalendarMigration } from "./snapshot";
import { applyCalendarMigration, restoreCalendarMigration } from "./apply";
import { calendarMigrationPending, calendarMigrationRecovery, MIGRATION_SETTING } from "./state";

export async function reviewCalendarMigration(): Promise<void> {
  if (!game?.user?.isGM) throw new Error("GM permission is required to migrate calendars.");
  const recovery = calendarMigrationRecovery();
  if (recovery && recovery.status !== "restored") {
    const action = await foundry.applications.api.DialogV2.wait({
      window: { title: "Previous Calendar Migration" },
      content: `<p>Last migration: ${escape(recovery.created)} (${escape(recovery.status)}).</p><p>Restore replaces the affected calendar settings, event dates and world time with the saved values. Later edits to those values will be overwritten. Other journal content is retained.</p>`,
      buttons: [
        { action: "restore", label: "Restore Previous Calendar" },
        { action: "download", label: "Download Recovery Snapshot" },
        ...(!calendarMigrationPending() ? [{ action: "next", label: "New Migration" }] : []),
        { action: "close", label: "Close" },
      ],
      rejectClose: false,
    });
    if (action === "download") {
      foundry.utils.saveDataToFile(
        JSON.stringify(recovery, null, 2),
        "application/json",
        "calendar-migration-recovery.json",
      );
      return;
    }
    if (action === "restore") {
      await restoreCalendarMigration();
      ui?.notifications?.info("Previous calendar restored. Reload to refresh both calendars.");
      return;
    }
    if (action !== "next") return;
  }
  const snapshot = captureCalendarMigration();
  const sources = snapshot.sources
    .map((s) => {
      const matching =
        s.months.length === IMPERIAL_MONTHS.length &&
        s.months.every(
          (m, i) =>
            m.name === IMPERIAL_MONTHS[i]?.name && m.days === IMPERIAL_MONTHS[i]?.numberOfDays,
        );
      return `<li><strong>${escape(s.name)}</strong>: ${escape(namedDateText(s.current))}; stored year zero ${escape(String(s.epoch))}. ${matching ? "Month names and lengths match." : "Month names, order or lengths differ."} ${s.id === "st" ? "ST&C displays internal year + 1." : "Target SCR year zero: 1."}</li>`;
    })
    .join("");
  const answer = await foundry.applications.api.DialogV2.input({
    window: { title: "Migrate Existing WFRP Calendars" },
    position: { width: 760 },
    content: `<p>Move the active calendars to Compatibility Box’s Imperial calendar: 400 days, eight weekdays and six festival days outside the week. Timestamp zero displays IC year 1.</p><ul>${sources}</ul>
    <div class="form-group"><label>Current world date</label><select name="clock"><option value="elapsed">Keep elapsed world time (dates may change)</option>${snapshot.sources.map((s) => `<option value="${s.id}">Keep ${escape(s.name)}’s displayed date</option>`).join("")}</select></div>
    <div class="form-group"><label>Existing events</label><select name="events"><option value="dates">Keep named dates (year, month name, day and time)</option><option value="elapsed">Keep elapsed timestamps (dates may change)</option></select></div>
    <div class="form-group"><label>Linked events use dates from</label><select name="authority"><option value="st">Simple Timekeeping &amp; Calendar</option><option value="scr">Simple Calendar Reborn</option></select></div>
    <p>Only explicitly linked events and dual-format journals share a source. Separate events remain separate, including duplicates. Unmatched month names and impossible dates appear as errors in the preview. Inactive SCR calendars are left alone.</p><p>Moon settings are retained; moon phase alignment is not migrated in this version. Moving world time can affect other time-based modules.</p>`,
    ok: { label: "Preview Migration" },
    rejectClose: false,
  });
  if (!answer) return;
  const choices = {
    clock: answer["clock"],
    events: answer["events"],
    authority: answer["authority"],
  } as MigrationChoices;
  const plan = planCalendarMigration(snapshot, choices);
  const result = await foundry.applications.api.DialogV2.wait({
    window: { title: "Review Calendar Migration" },
    position: { width: 850 },
    content: `<p><strong>New world date:</strong> ${escape(imperialDateText(plan.time, true))}. World time changes by ${escape(String(plan.time - snapshot.time))} seconds.</p><p>${plan.settings.length} calendar settings and ${plan.writes.length} event records reviewed. Recurrence and event permissions remain intact; linked dates and recurrence follow the selected source.</p>${plan.errors.length ? `<h3>Resolve before applying</h3><ul>${plan.errors.map((e) => `<li>${escape(e)}</li>`).join("")}</ul>` : ""}<div class="scrollable" style="max-height:45vh"><table><thead><tr><th>Event</th><th>Before</th><th>After</th></tr></thead><tbody>${plan.changes.map((c) => `<tr><td>${escape(c.name)}</td><td>${escape(c.before)}</td><td>${escape(c.after)}</td></tr>`).join("")}</tbody></table></div><p>A recovery snapshot is saved before changes. Reload afterward. If time or event data changes during review, the migration must be previewed again.</p>`,
    buttons: [
      ...(!plan.errors.length ? [{ action: "apply", label: "Apply Migration" }] : []),
      { action: "close", label: "Close" },
    ],
    rejectClose: false,
  });
  if (result !== "apply") return;
  await applyCalendarMigration(plan);
  ui?.notifications?.info(
    "Calendar migration complete. Reload to refresh both calendars and reconcile events.",
  );
}

export function registerCalendarMigration(): void {
  game?.settings.register(MODULE_ID, MIGRATION_SETTING, {
    name: "Calendar migration recovery",
    hint: "Status and GM journal reference for the most recent calendar migration.",
    scope: "world",
    config: false,
    type: Object,
    default: null,
  });
  Hooks.once("setup", () =>
    registerGroupedAction("calendars", "calendarMigration", {
      name: "Existing world calendars",
      label: "Migrate Existing WFRP Calendars",
      hint: "Preview calendar differences and choose how world time and events move to the shared Imperial calendar.",
      icon: "fa-solid fa-calendar-check",
      restricted: true,
      type: class extends foundry.applications.api.ApplicationV2 {
        override async render(): Promise<this> {
          try {
            await reviewCalendarMigration();
          } catch (error) {
            notifyError(error instanceof Error ? error.message : String(error), error);
          }
          return this;
        }
      },
    }),
  );
}
