import type { FoundryDirectoryEntry } from "../../../types/folders";

export function isPackageCompendiumSource(source: unknown, packageId: string): boolean {
  return typeof source === "string" && source.startsWith(`Compendium.${packageId}.`);
}

export function isImportedContent(document: FoundryDirectoryEntry, packageId: string): boolean {
  const source = document._stats?.compendiumSource;
  if (source?.startsWith("Compendium.")) return isPackageCompendiumSource(source, packageId);
  const core = document.flags?.["core"] as { sourceId?: unknown } | undefined;
  return isPackageCompendiumSource(core?.sourceId, packageId);
}
