import type { FoundryGame } from "../../../../types/foundry";
import type {
  JournalEnrichmentOptions,
  JournalLinkDocument,
  JournalTextEditor,
} from "../../../../types/patches/wfrp4e/JournalLinks";
import { compendiumsByDocumentId } from "./official-compendiums";

// Only absolute world IDs. Leave relative and compendium UUIDs and legacy name links to Foundry.
const WORLD_UUID =
  /^(Actor|Item|JournalEntry|RollTable|Scene|Macro|Playlist|Cards)\.([a-z\d]{16})((?:\.[a-z]+\.[a-z\d]{16})*)$/i;
const patched = new WeakSet<JournalTextEditor>();

async function findCompendiumTarget(
  currentGame: FoundryGame,
  options: JournalEnrichmentOptions,
  uuid: string,
): Promise<JournalLinkDocument | null> {
  const source = options.relativeTo;
  const journal = source?.documentName === "JournalEntryPage" ? source.parent : source;
  if (journal?.documentName !== "JournalEntry") return null;
  const [, type, id, embedded = ""] = WORLD_UUID.exec(uuid) ?? [];
  if (!type || !id) return null;

  for (const { pack } of compendiumsByDocumentId(currentGame, type, id, journal)) {
    // Foundry verifies the entire embedded path, not just the indexed parent ID.
    const target = await foundry.utils.fromUuid(pack.getUuid(id) + embedded);
    if (target && pack.visible) return target;
  }
  return null;
}

export function installJournalCompendiumLinks(): boolean {
  const editor = CONFIG.ux?.TextEditor;
  if (
    !editor ||
    typeof editor._createContentLink !== "function" ||
    typeof editor._embedContent !== "function" ||
    typeof editor._parseEmbedConfig !== "function" ||
    typeof foundry.utils.fromUuid !== "function" ||
    patched.has(editor)
  )
    return false;

  const createLink = editor._createContentLink;
  const embed = editor._embedContent;
  editor._createContentLink = async function (match, options = {}) {
    const original = await createLink.call(this, match, options);
    if (!game || !original.matches("a.content-link.broken")) return original;
    const [, type, id, hash, name] = match;
    if (!id) return original;
    const target = await findCompendiumTarget(
      game,
      options,
      type === "UUID" ? id : `${type}.${id}`,
    );
    return target?.toAnchor({ name, dataset: { hash } }) ?? original;
  };

  editor._embedContent = async function (match, options = {}) {
    const original = await embed.call(this, match, options);
    const raw = match.groups?.["config"];
    if (!game || !raw || !original?.matches("p.broken.content-embed")) return original;
    const config = this._parseEmbedConfig(raw, { relative: options.relativeTo });
    if (!config.uuid) return original;
    const target = await findCompendiumTarget(game, options, config.uuid);
    if (!target) return original;
    return (
      (await target.toEmbed(
        { label: match.groups?.["label"], ...config, uuid: target.uuid },
        options,
      )) ?? original
    );
  };

  patched.add(editor);
  return true;
}
