import type { ScenePackerApi } from "../../../../types/integrations/scene-packer/ScenePacker";
import { MODULE_ID } from "../../../constants";

const patchedApis = new WeakSet<ScenePackerApi>();

export function repairMadPrefabExclusions(api: ScenePackerApi): boolean {
  if (patchedApis.has(api)) return false;
  const original = api.Initialise;
  const reported = new Set<string>();

  api.Initialise = function (options, ...args) {
    const moduleName = options?.moduleName;
    const module = moduleName ? game?.modules.get(moduleName) : undefined;
    const ignored = options?.ignoredCompendiumPacks;
    if (!moduleName?.startsWith("mad-") || !module?.active || !module.packs) {
      return original.call(this, options, ...args);
    }

    const prefab = `${moduleName}-prefabs`;
    if (!Array.isArray(ignored) || !ignored.includes(prefab)) {
      return original.call(this, options, ...args);
    }
    if (Array.from(module.packs).some((pack) => pack.name === prefab)) {
      return original.call(this, options, ...args);
    }

    if (!reported.has(moduleName)) {
      reported.add(moduleName);
      console.warn(
        `${MODULE_ID} | ${moduleName}: skipped unavailable Scene Packer exclusion ${prefab}.`,
      );
    }
    return original.call(
      this,
      { ...options, ignoredCompendiumPacks: ignored.filter((pack) => pack !== prefab) },
      ...args,
    );
  };
  patchedApis.add(api);
  return true;
}
