import type { TimekeepingCalendar } from "../../../../types/integrations/calendars/Calendar";
import { timekeepingCalendar } from "../../../functions/calendars/imperial";
import { sameSettingValue } from "../../../functions/settings-presets/values";
import { isModuleActive } from "../is-module-active";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { installImperialTimekeeping } from "./calendar";
import { TIMEKEEPING_MODULE_ID } from "./preset";

export function usesImperialCalendar(): boolean {
  if (game?.system.id !== "wfrp4e" || !isOptionalFeatureEnabled("simpleTimekeeping")) return false;
  const config = game.settings.get(TIMEKEEPING_MODULE_ID, "configuration") as { calendar?: string };
  const calendars = game.settings.get(TIMEKEEPING_MODULE_ID, "customCalendars") as Record<
    string,
    ReturnType<typeof timekeepingCalendar>
  >;
  const expected = timekeepingCalendar();
  const calendar = calendars?.[config.calendar ?? ""];
  if (!calendar || config.calendar !== expected.id) return false;
  return (
    sameSettingValue(calendar.years, expected.years) &&
    sameSettingValue(calendar.days, expected.days) &&
    calendar.months.values.length === expected.months.values.length &&
    expected.months.values.every((month, i) =>
      Object.entries(month).every(([key, value]) =>
        sameSettingValue(calendar.months.values[i]?.[key as keyof typeof month], value),
      ),
    )
  );
}

export function registerTimekeepingIntegration(): void {
  if (
    !isModuleActive(TIMEKEEPING_MODULE_ID) ||
    !isOptionalFeatureEnabled("simpleTimekeeping") ||
    game?.system.id !== "wfrp4e"
  )
    return;
  Hooks.once("initSimpleTimekeeping", () => {
    installImperialTimekeeping(
      game!.time as unknown as { calendar: TimekeepingCalendar; initializeCalendar(): void },
      usesImperialCalendar,
    );
  });
}
