import type { NoteStub, RecurrenceContext } from "../../../types/integrations/calendars/Recurrence";
import { imperialTimestamp } from "./imperial";
export const dayStart = (year: number, month: number, day: number) =>
  imperialTimestamp({ year, month, day, hour: 0, minute: 0, second: 0 });
/** Delegate every linked recurrence to the same occurrence engine as ST&C's calendar view. */
export function installNoteOccurrences(
  prototype: NoteStub,
  context: (id: string, calendar?: string) => RecurrenceContext | undefined,
  selectedDay: () => number,
  format: (time: number, allDay: boolean) => string,
): void {
  const visible = prototype.isVisible,
    display = prototype.getDisplayDate;
  prototype.isVisible = function (calendar, year, month, day) {
    const linked = context(this.entryId, calendar);
    if (!linked) return visible.call(this, calendar, year, month, day);
    if (!this.canUserView()) return false;
    const start = dayStart(year, month, day);
    return linked.occurrences(start, start + 86400).length > 0;
  };
  prototype.getDisplayDate = function (full) {
    const linked = context(this.entryId);
    if (!linked || !this.canUserView()) return display.call(this, full);
    const start = selectedDay();
    const occurrence = linked.occurrences(start, start + 86400)[0];
    if (!occurrence) return display.call(this, full);
    const end = linked.allDay ? occurrence.end - 1 : occurrence.end;
    const first = format(occurrence.start, linked.allDay),
      last = format(end, linked.allDay);
    return first === last ? first : `${first} – ${last}`;
  };
}
