function logError(message: string, cause?: unknown): void {
  if (cause === undefined) {
    console.error(message);
  } else {
    console.error(message, cause);
  }
}

function logWarning(message: string, cause?: unknown): void {
  if (cause === undefined) {
    console.warn(message);
  } else {
    console.warn(message, cause);
  }
}

/** Show an error alert and retain the same message in the browser console. */
export function notifyError(message: string, cause?: unknown): void {
  logError(message, cause);
  ui?.notifications?.error(message);
}

/** Show a warning alert and retain the same message in the browser console. */
export function notifyWarning(message: string, cause?: unknown): void {
  logWarning(message, cause);
  ui?.notifications?.warn(message);
}
