import { MODULE_ID } from "../../constants";

export const KEEP_IMPORTED_CONTENT_TIDY_SETTING = "keepImportedContentTidy";

/** Shown in the grouped World Tools window beside the WFRP folder options. */
export function registerImportedContentSetting(onChange: () => void): void {
  game?.settings.register(MODULE_ID, KEEP_IMPORTED_CONTENT_TIDY_SETTING, {
    name: `${MODULE_ID}.Settings.ImportedContent.${KEEP_IMPORTED_CONTENT_TIDY_SETTING}.Name`,
    hint: `${MODULE_ID}.Settings.ImportedContent.${KEEP_IMPORTED_CONTENT_TIDY_SETTING}.Hint`,
    config: false,
    default: false,
    onChange,
    scope: "world",
    type: Boolean,
  });
}
