import type {
  SettingsPresetCoordinator,
  PreferencePlan,
} from "../../../../types/settings-presets/Protocol";
import type { SettingPreference } from "../../../../types/settings-presets/SettingsPreset";

function coordinator(): SettingsPresetCoordinator | undefined {
  const coordinators = [...(game?.modules.values() ?? [])]
    .filter((entry) => entry.active)
    .map(
      (entry) =>
        (entry.api as { settingsPresetCoordinator?: SettingsPresetCoordinator } | undefined)
          ?.settingsPresetCoordinator,
    )
    .filter((entry): entry is SettingsPresetCoordinator => entry?.version === 1);
  if (coordinators.length > 1)
    throw new Error(
      "Multiple settings coordinators are active; disable the duplicate before applying presets.",
    );
  return coordinators[0];
}
export function coordinatePreferences(owner: string, entries: SettingPreference[]): PreferencePlan {
  return coordinator()?.plan(owner, entries) ?? { entries, excluded: [], conflicts: [] };
}
export async function resolvePreferences(
  owner: string,
  entries: SettingPreference[],
): Promise<boolean> {
  if (!game?.ready || !game.user?.isGM) throw new Error("A ready GM session is required.");
  return (await coordinator()?.resolve(owner, entries)) ?? true;
}
