interface JournalSheet {
  pageId?: string;
  isMultiple: boolean;
  document: { pages: ReadonlyMap<string, { type: string }> };
}

export function registerJournalThemeOptOut(): void {
  const observers = new WeakMap<JournalSheet, MutationObserver>();
  const disconnect = (sheet: JournalSheet) => {
    observers.get(sheet)?.disconnect();
    observers.delete(sheet);
  };

  // WFRP applies the normal theme in its script-load hook, before this init-time hook.
  Hooks.on("renderJournalEntrySheet", (app, html) => {
    const sheet = app as JournalSheet;
    const element = html as HTMLElement;
    disconnect(sheet);

    let optedOut = false;
    const syncTheme = () => {
      const page = sheet.pageId ? sheet.document.pages.get(sheet.pageId) : undefined;
      if (page?.type.startsWith("simple-quest.")) {
        optedOut = true;
        if (!element.classList.contains("no-theme")) element.classList.add("no-theme");
        if (element.classList.contains("classic-font")) element.classList.remove("classic-font");
      } else if (optedOut) {
        // In continuous view, leaving an SQ page does not rerender the window.
        optedOut = false;
        const theme = game?.settings.get("wfrp4e", "theme") as
          { journal: { enabled: boolean; font: string } } | undefined;
        element.classList.toggle("no-theme", theme?.journal.enabled === false);
        element.classList.toggle(
          "classic-font",
          theme?.journal.enabled === true && theme.journal.font === "classic",
        );
      }
    };
    syncTheme();

    // Foundry updates pageId and the active TOC rows together in continuous view.
    const toc = sheet.isMultiple ? element.querySelector(".toc") : null;
    if (!optedOut && !toc) return;
    const observer = new MutationObserver(syncTheme);
    const options = { attributeFilter: ["class"] };
    if (toc) observer.observe(toc, { ...options, subtree: true });
    // The WFRP theme preview can also change the window's classes without a render.
    observer.observe(element, options);
    observers.set(sheet, observer);
  });
  Hooks.on("closeJournalEntrySheet", (app) => disconnect(app as JournalSheet));
}
