import type { BossCandidate } from "../../../../types/integrations/bossbar/BossBar";

export function selectBosses(candidates: readonly BossCandidate[]): BossCandidate[] {
  const enemies = candidates.filter((candidate) => candidate.enemy);
  const hasTrait = (candidate: BossCandidate, name: string) =>
    candidate.traits.some((trait) => trait.trim().toLowerCase() === name);
  const explicit = enemies.filter((candidate) => hasTrait(candidate, "boss"));

  if (explicit.length) return explicit;

  const ranked = enemies
    .filter(
      (candidate) =>
        candidate.maxWounds >= 30 &&
        hasTrait(candidate, "grim") &&
        (hasTrait(candidate, "leader") || hasTrait(candidate, "champion")),
    )
    .sort(
      (left, right) =>
        right.maxWounds - left.maxWounds ||
        right.weaponSkill - left.weaponSkill ||
        right.strength - left.strength,
    );
  const best = ranked[0];
  if (!best) return [];

  const tied = ranked.filter(
    (candidate) =>
      candidate.maxWounds === best.maxWounds &&
      candidate.weaponSkill === best.weaponSkill &&
      candidate.strength === best.strength,
  );
  return tied.length <= 2 ? tied : [];
}
