import type { FoundryDirectoryEntry, FoundryFolder } from "../../../types/folders";
import type { FoundryGame } from "../../../types/foundry";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../constants";
import { planImportedContentFolders } from "../../functions/imported-content/folders";
import { isImportedContent } from "../../functions/imported-content/source";
import { queueFolderTidy } from "../folders/queue";
import { KEEP_IMPORTED_CONTENT_TIDY_SETTING } from "./settings";

const ROOT_FLAG = "importedContentRoot";

/** The world's typing is WFRP-specific; this tidy needs Foundry's generic directory fields. */
interface ImportedContentWorld {
  collections: Map<string, { contents?: FoundryDirectoryEntry[] }>;
  folders: Iterable<FoundryFolder>;
}

function world(currentGame: FoundryGame): ImportedContentWorld {
  return currentGame as unknown as ImportedContentWorld;
}

export function canTidyImportedContent(currentGame: FoundryGame | undefined): boolean {
  return (
    currentGame?.ready === true &&
    currentGame.user?.isGM === true &&
    currentGame.user.isActiveGM === true &&
    currentGame.settings.get(PACKAGE_ID, KEEP_IMPORTED_CONTENT_TIDY_SETTING) === true
  );
}

function isManagedRoot(folder: FoundryFolder): boolean {
  const flags = folder.flags?.[PACKAGE_ID] as Record<string, unknown> | undefined;
  return flags?.[ROOT_FLAG] === true;
}

async function move(entry: FoundryDirectoryEntry, folder: FoundryFolder | null): Promise<void> {
  const target = folder?.id ?? null;
  if ((entry.folder?.id ?? null) === target) return;
  await entry.update({ folder: target });
  if ((entry.folder?.id ?? null) !== target) throw new Error(`Could not move ${entry.name}.`);
}

async function tidyDirectory(currentGame: FoundryGame, type: string): Promise<void> {
  const entries = (world(currentGame).collections.get(type)?.contents ?? []).filter(
    (entry) => !entry.pack && !entry.parent,
  );
  const indexed = new Map(entries.map((entry) => [entry.id, entry]));
  const sources = entries.map((entry) => ({
    id: entry.id,
    folderId: entry.folder?.id ?? null,
    imported: isImportedContent(entry, PACKAGE_ID),
  }));
  if (!sources.some((entry) => entry.imported)) return;

  const folders = [...world(currentGame).folders].filter((folder) => folder.type === type);
  const roots = folders.filter(isManagedRoot);
  const root = roots.find((folder) => !folder.folder) ?? roots[0];
  if (root?.folder) await move(root, null);
  const maxDepth = CONST.FOLDER_MAX_DEPTH;
  const plan = planImportedContentFolders(folders, sources, root?.id, maxDepth);
  if (!plan.branches.size && !plan.documents.length) return;

  async function createFolder(data: Record<string, unknown>): Promise<FoundryFolder> {
    const folder = (await CONFIG.Folder.documentClass.create({
      type,
      ...data,
    })) as unknown as FoundryFolder | null;
    if (!folder) throw new Error(`Could not create ${type} folder ${String(data["name"])}.`);
    folders.push(folder);
    return folder;
  }

  const destination =
    root ??
    (await createFolder({
      name: PACKAGE_TITLE,
      sorting: "a",
      flags: { [PACKAGE_ID]: { [ROOT_FLAG]: true } },
    }));

  async function resolvePath(path: FoundryFolder[]): Promise<FoundryFolder> {
    let parent = destination;
    const depth = Math.min(path.length, maxDepth - 1);
    for (let index = 0; index < depth; index++) {
      const source = path[index]!;
      const name =
        index === maxDepth - 2
          ? path
              .slice(index)
              .map((folder) => folder.name)
              .join("/")
          : source.name;
      parent =
        folders.find((folder) => folder.folder?.id === parent.id && folder.name === name) ??
        (await createFolder({
          name,
          folder: parent.id,
          sorting: source.sorting,
          color: source.color?.toString() ?? null,
        }));
    }
    return parent;
  }

  for (const [folder, path] of plan.branches) await move(folder, await resolvePath(path));
  for (const { id, path } of plan.documents) await move(indexed.get(id)!, await resolvePath(path));
}

export async function tidyImportedContentIfEnabled(): Promise<void> {
  const currentGame = game;
  if (!currentGame || !canTidyImportedContent(currentGame)) return;
  await queueFolderTidy(currentGame, async () => {
    if (!canTidyImportedContent(currentGame)) return;
    for (const type of CONST.FOLDER_DOCUMENT_TYPES) {
      if (type !== "Compendium") await tidyDirectory(currentGame, type);
    }
  });
}
