import type {
  MigrationChoices,
  MigrationEvent,
  MigrationPlan,
  MigrationSnapshot,
  NamedDate,
} from "../../../types/integrations/calendars/Migration";
import { calendarObject, configureSimpleCalendar, configureTimekeeping } from "./configuration";
import { SC_NOTES, ST_EVENTS } from "./content";
import { eventToNote } from "./event-sync";
import {
  IMPERIAL_CALENDAR_ID,
  IMPERIAL_MONTHS,
  imperialDateText,
  imperialTimestamp,
} from "./imperial";

export function namedDateText(d: NamedDate): string {
  return `${d.day + 1} ${d.monthName} ${d.year}, ${String(d.hour).padStart(2, "0")}:${String(d.minute).padStart(2, "0")}:${String(d.seconds).padStart(2, "0")}`;
}
export function migrateNamedDate(d: NamedDate): number {
  const month = IMPERIAL_MONTHS.findIndex(
    (m) => m.name.toLocaleLowerCase() === d.monthName.trim().toLocaleLowerCase(),
  );
  if (month < 0)
    throw new Error(
      `No Imperial month matches “${d.monthName}”. Choose elapsed time or adjust the source calendar.`,
    );
  return imperialTimestamp({
    year: d.year,
    month,
    day: d.day,
    hour: d.hour,
    minute: d.minute,
    second: d.seconds,
  });
}
const eventKey = (e: MigrationEvent) => `${e.journal}/${e.page ?? ""}`;

/** Build the complete review without changing settings, time or documents. */
export function planCalendarMigration(
  snapshot: MigrationSnapshot,
  choices: MigrationChoices,
): MigrationPlan {
  const plan: MigrationPlan = {
    snapshot,
    choices,
    time: snapshot.time,
    settings: [],
    writes: [],
    changes: [],
    errors: [],
  };
  if (
    !["elapsed", "scr", "st"].includes(choices.clock) ||
    !["dates", "elapsed"].includes(choices.events) ||
    !["scr", "st"].includes(choices.authority)
  )
    throw new Error("Invalid calendar migration choice.");
  const setting = (namespace: string, key: string) =>
    snapshot.settings.find((s) => s.namespace === namespace && s.key === key)?.value;
  try {
    if (choices.clock !== "elapsed") {
      const source = snapshot.sources.find((s) => s.id === choices.clock);
      if (!source) throw new Error("The chosen calendar is unavailable.");
      plan.time = migrateNamedDate(source.current);
    }
    if (snapshot.sources.some((s) => s.id === "st")) {
      const config = calendarObject(setting(ST_EVENTS, "configuration"));
      const registry = calendarObject(setting(ST_EVENTS, "customCalendars"));
      // Carry editor-managed moons/biome from the selected custom calendar into the target.
      const selected = registry[String(config["calendar"])];
      if (selected) registry[IMPERIAL_CALENDAR_ID] = selected;
      const next = configureTimekeeping(config, registry);
      plan.settings.push(
        { namespace: ST_EVENTS, key: "customCalendars", value: next.customCalendars },
        { namespace: ST_EVENTS, key: "configuration", value: next.configuration },
      );
    }
    if (snapshot.activeId) {
      const calendars = configureSimpleCalendar(
        setting(SC_NOTES, "calendar-configuration"),
        snapshot.activeId,
        plan.time,
        snapshot.sources.some((s) => s.id === "st"),
      );
      // A date choice must apply even when the definition is already canonical.
      const date = eventToNote({ eventTime: plan.time }, snapshot.activeId).startDate;
      for (const c of calendars)
        if (c && typeof c === "object" && !Array.isArray(c) && c["id"] === snapshot.activeId)
          c["currentDate"] = {
            year: date.year,
            month: date.month,
            day: date.day,
            seconds: date.hour * 3600 + date.minute * 60 + date.seconds,
          };
      plan.settings.push({ namespace: SC_NOTES, key: "calendar-configuration", value: calendars });
    }
  } catch (error) {
    plan.errors.push(String(error instanceof Error ? error.message : error));
  }
  const migrated = new Map<string, { start: number; end: number; source: MigrationEvent }>();
  for (const entry of snapshot.events) {
    try {
      if (entry.note && ![0, 1, 2, 3, 4].includes(entry.note.repeats))
        throw new Error("Unsupported Simple Calendar recurrence.");
      const times = choices.events === "elapsed" ? entry.times : entry.dates.map(migrateNamedDate);
      const [start, end] = times as [number, number];
      if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || end < start)
        throw new Error("Invalid event date range.");
      migrated.set(eventKey(entry), { start, end, source: entry });
    } catch (error) {
      plan.errors.push(`${entry.name}: ${error instanceof Error ? error.message : error}`);
    }
  }
  for (const entry of snapshot.events) {
    const own = migrated.get(eventKey(entry));
    const linked = entry.linked ? migrated.get(entry.linked) : undefined;
    const next =
      linked &&
      ((choices.authority === "st" && linked.source.event) ||
        (choices.authority === "scr" && linked.source.note))
        ? linked
        : own;
    if (!next) continue;
    const recurrence =
      next.source.event ??
      (next.source.note
        ? {
            repeat: ["", "week", "month", "year", "day"][next.source.note.repeats],
            allDay: next.source.note.allDay,
          }
        : {});
    try {
      const event = {
        eventTime: next.start,
        eventEnd: next.end,
        repeat: recurrence.repeat ?? "",
        allDay: !!recurrence.allDay,
      };
      const after = entry.note
        ? { ...entry.note, ...eventToNote(event, entry.note.calendarId) }
        : { ...entry.event!, ...event };
      plan.writes.push({
        journal: entry.journal,
        ...(entry.page ? { page: entry.page } : {}),
        key: entry.note ? `flags.${SC_NOTES}.noteData` : `flags.${ST_EVENTS}`,
        before: entry.note ?? entry.event!,
        after,
      });
      plan.changes.push({
        name: entry.name,
        before: `${namedDateText(entry.dates[0])} → ${namedDateText(entry.dates[1])}`,
        after: `${imperialDateText(next.start, true)} → ${imperialDateText(next.end, true)}`,
      });
    } catch (error) {
      plan.errors.push(`${entry.name}: ${error instanceof Error ? error.message : error}`);
    }
  }
  return plan;
}
