import type { SettingsPresetProvider } from "../../../../types/settings-presets/Protocol";
import type { PresetProposal } from "../../../../types/settings-presets/Conflicts";
import type { SettingPreference } from "../../../../types/settings-presets/SettingsPreset";
import { cloneSettingValue } from "../../../functions/settings-presets/values";
import { findPresetConflicts } from "../../../functions/settings-presets/conflicts";

export function collectConflicts(owner: string, requested: SettingPreference[]) {
  const proposals: PresetProposal[] = [];
  // Foundry Collection iterates module values, unlike a native Map.
  for (const [id, entry] of game?.modules.entries() ?? []) {
    if (!entry.active) continue;
    const provider = (entry.api as { settingsPresets?: SettingsPresetProvider } | undefined)
      ?.settingsPresets;
    if (provider?.version !== 1) continue;
    // Provider failures are visible; never silently omit an unreadable competing proposal.
    for (const preset of provider.getPresets())
      proposals.push({
        source: `${id}:${preset.namespace}`,
        title: `${entry.title ?? id} — ${preset.title}`,
        entries: preset.entries.map((preference) => ({
          ...preference,
          value: cloneSettingValue(preference.value),
        })),
      });
  }
  // Direct callers may inspect a subset without registering a public provider.
  for (const entry of requested) {
    if (
      !proposals.some(
        (proposal) =>
          proposal.source.startsWith(`${owner}:`) &&
          proposal.entries.some(
            (value) => value.namespace === entry.namespace && value.key === entry.key,
          ),
      )
    )
      proposals.push({
        source: `${owner}:${entry.namespace}`,
        title: game?.modules.get(owner)?.title ?? owner,
        entries: [entry],
      });
  }
  const ids = new Set(requested.map((entry) => `${entry.namespace}.${entry.key}`));
  return findPresetConflicts(proposals).filter((conflict) => ids.has(conflict.id));
}
