import { sameSettingValue } from "../../../functions/settings-presets/values";
import type { SettingPreference } from "../../../../types/settings-presets/SettingsPreset";
import type { SettingsResult } from "../../../../types/settings-presets/Protocol";
import { resolvePreferences } from "./coordination";
import { inspectPreferences, applyPreferences } from "./engine";
import { escapePresetHtml, inspectionMarkup, reportSettingsResult } from "./presentation";

export interface PresetReview {
  owner: string;
  title: string;
  entries: () => SettingPreference[];
  description?: string;
  ignoreKey?: string;
  startup?: boolean;
}
let queue: Promise<unknown> = Promise.resolve();
const pending = new Map<string, Promise<SettingsResult | null>>();
export function reviewPreferences(options: PresetReview): Promise<SettingsResult | null> {
  const key = `${options.owner}:${options.ignoreKey ?? options.title}`;
  if (options.startup && pending.has(key)) return pending.get(key)!;
  const result = queue
    .then(() => review(options))
    .finally(() => {
      if (options.startup) pending.delete(key);
    });
  if (options.startup) pending.set(key, result);
  queue = result.catch(() => {});
  return result;
}
async function review(options: PresetReview): Promise<SettingsResult | null> {
  if (!game?.ready || !game.user?.isGM) return null;
  if (options.startup && game.users?.activeGM && game.users.activeGM.id !== game.user.id)
    return null;
  if (
    options.startup &&
    options.ignoreKey &&
    game.settings.get(options.owner, options.ignoreKey) === true
  )
    return null;
  if (!(await resolvePreferences(options.owner, options.entries()))) return null;
  const inspection = inspectPreferences(options.owner, options.entries());
  if (
    options.startup &&
    !inspection.changes.length &&
    !inspection.skipped.length &&
    !inspection.failed.length &&
    !inspection.conflicts.length &&
    !inspection.missingTables.length
  )
    return null;
  const blocked = !!(
    inspection.skipped.length ||
    inspection.failed.length ||
    inspection.conflicts.length ||
    inspection.missingTables.length
  );
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: options.title },
    position: { width: 650 },
    content: `${options.description ? `<p>${escapePresetHtml(options.description)}</p>` : ""}${inspectionMarkup(inspection)}`,
    buttons: [
      ...(!blocked && inspection.changes.length
        ? [{ action: "configure", label: "Apply Preset", default: true }]
        : []),
      ...(options.startup && options.ignoreKey
        ? [{ action: "keep", label: "Keep My Settings and Ignore" }]
        : []),
      { action: "later", label: options.startup ? "Ask Next Time" : "Close" },
    ],
    rejectClose: false,
  });
  if (!game.user?.isGM) throw new Error("GM permission changed.");
  if (choice === "keep" && options.ignoreKey)
    await game.settings.set(options.owner, options.ignoreKey, true);
  if (choice !== "configure" || blocked) return null;
  const latest = inspectPreferences(options.owner, options.entries());
  if (!sameSettingValue(latest, inspection))
    throw new Error(
      "Settings or preset choices changed during review; reopen the action before applying.",
    );
  const result = await applyPreferences(options.owner, options.entries());
  await reportSettingsResult(options.title, result);
  return result;
}
