import type { GroupedAction, SettingsGroup } from "../../../../types/settings/Groups";

export const SETTINGS_GROUPS = {
  integrations: {
    title: "Integrations",
    hint: "Choose optional compatibility features and configure their behavior.",
    icon: "fa-solid fa-puzzle-piece",
  },
  calendars: {
    title: "Calendars",
    hint: "Set up the Imperial calendar, migrate existing dates, and import WFRP events.",
    icon: "fa-solid fa-calendar-days",
  },
  presets: {
    title: "Presets",
    hint: "Review recommended module settings, manage setup prompts, and export presets.",
    icon: "fa-solid fa-sliders",
  },
  world: {
    title: "World Tools",
    hint: "Organize WFRP content and inspect compatibility fixes.",
    icon: "fa-solid fa-toolbox",
  },
} as const;
const actions = new Map<string, { group: SettingsGroup; action: GroupedAction }>();
export function clearGroupedActions(group: SettingsGroup): void {
  for (const [key, entry] of actions) if (entry.group === group) actions.delete(key);
}
/** Keep action launchers out of Foundry's flat menu while retaining their existing workflows. */
export function registerGroupedAction(
  group: SettingsGroup,
  key: string,
  action: GroupedAction,
): void {
  actions.set(key, { group, action });
}
export function groupedActions(group: SettingsGroup): [string, GroupedAction][] {
  return [...actions]
    .filter(([, value]) => value.group === group)
    .map(([key, value]) => [key, value.action]);
}
