import type { TemplateRuntime, TemplateSheet } from "./types";

const IMAGE_PLACEHOLDER = "https://source.unsplash.com/random";

// Keep mark selectors (color, font-family, font-size) off the block wrapper.
// Even background-color and border-color match Foundry 14's color mark.
const BOXED_TEXT = `<div style="background:#9ca7a5;border-top:2px solid #252525;border-bottom:2px solid #252525;padding:0 0.5em">
<p><span style="color:#252525;text-transform:uppercase"><strong>Lorem Ipsum</strong></span></p>
<p><span style="color:#252525">Lorem ipsum dolor sit, amet consectetur adipisicing elit. Magni asperiores dicta vitae veritatis. Aut atque nobis voluptatem at alias, quam similique corrupti mollitia nihil laboriosam, consequuntur quibusdam ut, quos nesciunt.</span></p>
</div>`;

function getImage(runtime: TemplateRuntime): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const picker = new runtime.applications.apps.FilePicker.implementation({
      type: "image",
      callback: resolve,
    });
    const close = picker.close;
    picker.close = async function (...args) {
      resolve(null);
      return close.apply(this, args);
    };
    // A picker dismissed without selection keeps the original placeholder, as in SQ.
    Promise.resolve(picker.browse()).catch(reject);
  });
}

export async function applySimpleQuestTemplate(
  path: string,
  app: TemplateSheet,
  runtime: TemplateRuntime,
): Promise<void> {
  await app.close({ force: true });
  try {
    const textContent = app.document.text?.content ?? "";
    // Match the bundled template only; a custom template with this name is untouched.
    const pathname = new URL(path, document.baseURI).pathname;
    let template = pathname.endsWith(
      "/modules/simple-quest/templates/JournalTemplates/boxed-text.html",
    )
      ? BOXED_TEXT
      : await fetch(path).then((response) => {
          if (!response.ok)
            throw new Error(`Simple Quest template request failed: ${response.status}`);
          return response.text();
        });
    const images = template.match(/https:\/\/source\.unsplash\.com\/random/g) ?? [];
    // Collect first so cancelling one picker cannot change which placeholder is replaced next.
    const paths: (string | null)[] = [];
    for (const _image of images) paths.push(await getImage(runtime));
    let index = 0;
    template = template.replaceAll(IMAGE_PLACEHOLDER, () => paths[index++] || IMAGE_PLACEHOLDER);
    await app.document.update({ "text.content": textContent + "\n" + template });
  } finally {
    app.render(true);
  }
}
