import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { isModuleActive } from "../is-module-active";
import { createArgonButtons } from "./buttons";
import { ARGON_MODULE_ID } from "./constants";
import { patchArgonLegacyModuleCheck } from "./legacy-module-check";
import { createArgonPanels } from "./panels";
import { createArgonWeaponSets } from "./weapon-sets";
import { installStartupFix, recordStartupFix } from "../../diagnostics/startup-report";

export function registerArgonCombatHudIntegration(): void {
  if (!isModuleActive(ARGON_MODULE_ID)) {
    recordStartupFix("argonLegacy", "inactive", "Argon Combat HUD is not active.");
    return;
  }

  if (!isOptionalFeatureEnabled("argonCombatHud")) {
    recordStartupFix("argonLegacy", "inactive", "Argon compatibility is disabled.");
    return;
  }

  installStartupFix(
    "argonLegacy",
    () => {
      patchArgonLegacyModuleCheck();
      return true;
    },
    "Legacy enhancedcombathud-wfrp4e package check bypass installed.",
    {
      status: "unavailable",
      detail: "Argon's legacy module-check API is unavailable.",
    },
  );

  Hooks.on("argonInit", (CoreHUD) => {
    const { WFRPActionPanel } = createArgonButtons(CoreHUD);
    const { WFRPDrawerPanel, WFRPMovementHud, WFRPPortraitPanel } = createArgonPanels(CoreHUD);
    const WFRPWeaponSets = createArgonWeaponSets(CoreHUD);

    CoreHUD.definePortraitPanel(WFRPPortraitPanel);
    CoreHUD.defineDrawerPanel(WFRPDrawerPanel);
    CoreHUD.defineMainPanels([WFRPActionPanel, CoreHUD.ARGON.PREFAB.PassTurnPanel]);
    CoreHUD.defineMovementHud(WFRPMovementHud);
    CoreHUD.defineWeaponSets(WFRPWeaponSets);
    CoreHUD.defineSupportedActorTypes(["character", "npc", "creature"]);
  });
}
