import type { ForgeIntegrationService } from "../../../../types/integrations/fa-nexus/ForgeIntegration";
import { MODULE_ID } from "../../../constants";
import { repairForgeOwnerDetection } from "./repair-forge-owner-detection";
import { isModuleActive } from "../is-module-active";
import { recordStartupFix } from "../../diagnostics/startup-report";

export async function registerFaNexusIntegration(): Promise<void> {
  if (!isModuleActive("fa-nexus")) {
    recordStartupFix("forgeOwner", "inactive", "FA Nexus is not active.");
    return;
  }
  if (game?.system.id !== "wfrp4e" || typeof ForgeAPI === "undefined") {
    recordStartupFix("forgeOwner", "inactive", "Requires WFRP4e with Forge's API present.");
    return;
  }

  // Reuse the exact module URL Foundry loaded, including Forge's Bazaar rewrite.
  // A guessed local URL can create a second module instance with duplicate hooks.
  const script = Array.from(
    document.querySelectorAll<HTMLScriptElement>('script[type="module"][src]'),
  ).find((entry) => {
    const path = new URL(entry.src).pathname;
    return /\/modules\/fa-nexus\/(?:[^/]+\/)?scripts\/core\/forge-integration\.js$/.test(path);
  });
  if (!script) {
    recordStartupFix(
      "forgeOwner",
      "unavailable",
      "The loaded FA Nexus Forge integration script could not be located.",
    );
    console.warn(`${MODULE_ID} | FA Nexus Forge integration script was not found; patch skipped.`);
    return;
  }

  try {
    const url = script.src;
    const exports: { forgeIntegration?: ForgeIntegrationService } = await import(
      /* @vite-ignore */ url
    );
    const service = exports.forgeIntegration;
    if (
      typeof service?._detectForgeAccountId !== "function" ||
      typeof service.isRunningOnForge !== "function"
    ) {
      throw new Error("FA Nexus Forge integration API is unavailable.");
    }
    repairForgeOwnerDetection(service, () => ForgeAPI.lastStatus?.ownerUserId);
    recordStartupFix(
      "forgeOwner",
      "applied",
      "Forge owner-metadata fallback installed on the loaded Nexus service.",
    );
  } catch (error) {
    recordStartupFix(
      "forgeOwner",
      "failed",
      error instanceof Error ? error.message : String(error),
    );
    console.error(`${MODULE_ID} | Could not install FA Nexus Forge compatibility.`, error);
  }
}
