import type { SettingsCapture as CampaignSettingsExportResult } from "../../../../types/settings-presets/Protocol";
import type { SettingRegistration } from "../../../../types/settings-presets/SettingsPreset";
interface FoundrySettingRegistration extends SettingRegistration {
  namespace: string;
  key: string;
  config?: boolean;
}
import { isSettingsNamespaceActive } from "./engine";
import { settingValueToSource } from "./values";

/** Capture only explicitly selected keys, with the same namespace JSON shape used by imports. */
export function captureSettings(
  namespace: string,
  keys: string[],
  includeHidden = false,
): CampaignSettingsExportResult {
  if (!game?.user?.isGM) throw new Error("Only a GM can export settings.");
  if (!isSettingsNamespaceActive(namespace))
    throw new Error("The selected system or module is not active.");
  if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]*$/.test(namespace))
    throw new Error("Invalid settings namespace.");
  if (!keys.length) throw new Error("Select at least one setting to export.");
  const values = Object.fromEntries(
    [...new Set(keys)].map((key) => {
      const setting = game?.settings.settings?.get(`${namespace}.${key}`) as
        FoundrySettingRegistration | undefined;
      if (!setting || setting.scope !== "world" || (!setting.config && !includeHidden))
        throw new Error(`${namespace}.${key} is not an available selected world setting.`);
      try {
        return [key, settingValueToSource(setting, game?.settings.get(namespace, key))];
      } catch (error) {
        throw new Error(
          `${namespace}.${key}: ${error instanceof Error ? error.message : String(error)}`,
          { cause: error },
        );
      }
    }),
  );
  return { namespace, filename: `${namespace}.json`, values };
}

function settingChoices(namespace: string, includeHidden: boolean): FoundrySettingRegistration[] {
  return ([...(game?.settings.settings?.values() ?? [])] as FoundrySettingRegistration[])
    .filter(
      (setting) =>
        setting.namespace === namespace &&
        setting.scope === "world" &&
        (setting.config || includeHidden),
    )
    .sort((a, b) => a.key.localeCompare(b.key));
}

function settingMarkup(setting: FoundrySettingRegistration, index: number): string {
  const escape = foundry.utils.escapeHTML;
  const name = game?.i18n.localize(setting.name || setting.key) ?? setting.key;
  let preview: string;
  let disabled = false;
  try {
    const value = settingValueToSource(setting, game?.settings.get(setting.namespace, setting.key));
    const text = JSON.stringify(value);
    preview = text.length > 160 ? `${text.slice(0, 160)}…` : text;
  } catch (error) {
    disabled = true;
    preview = `Cannot export: ${error instanceof Error ? error.message : String(error)}`;
  }
  return `<div class="form-group"><label>
    <input type="checkbox" name="setting-${index}" ${disabled ? "disabled" : ""}>
    ${escape(name)}${setting.config ? "" : " (hidden)"}
    </label><p class="hint"><code>${escape(`${setting.namespace}.${setting.key}`)}</code><br>${escape(preview)}</p></div>`;
}

/** A short native dialog flow downloads one selected namespace without changing world settings. */
export async function exportSettings(
  sourceDirectory = "src/settings/",
): Promise<CampaignSettingsExportResult | null> {
  if (!game?.user?.isGM) throw new Error("Only a GM can export settings.");
  const namespaces = [
    ...new Set(
      ([...(game.settings.settings?.values() ?? [])] as FoundrySettingRegistration[])
        .filter(
          (setting) => setting.scope === "world" && isSettingsNamespaceActive(setting.namespace),
        )
        .map((setting) => setting.namespace),
    ),
  ].sort();
  if (!namespaces.length) {
    ui?.notifications?.info("There are no registered world settings to export.");
    return null;
  }
  const escape = foundry.utils.escapeHTML;
  const choice = await foundry.applications.api.DialogV2.input({
    window: { title: "Export Settings Preset" },
    content: `<p>Select the system or module whose world preferences you want to save.</p>
      <div class="form-group"><label>System or module</label><select name="namespace">
      ${namespaces.map((namespace) => `<option value="${escape(namespace)}">${escape(namespace)}</option>`).join("")}</select></div>
      <div class="form-group"><label><input type="checkbox" name="includeHidden"> Include hidden world settings</label>
      <p class="hint">Hidden settings may contain migration data or world state. Select only the preferences you want to reuse.</p></div>`,
    ok: { label: "Choose Settings" },
    rejectClose: false,
  });
  if (!choice) return null;
  const namespace = String(choice["namespace"]);
  if (!namespaces.includes(namespace)) throw new Error("Select an available settings namespace.");
  const includeHidden = choice["includeHidden"] === true;
  const settings = settingChoices(namespace, includeHidden);
  if (!settings.length) {
    ui?.notifications?.info("This namespace has no settings matching that selection.");
    return null;
  }
  const selected = await foundry.applications.api.DialogV2.input({
    window: { title: `Export ${namespace} Settings` },
    content: `<p>Select the preferences to include in <strong>${escape(namespace)}.json</strong>.</p>
      <div class="scrollable" style="max-height: 50vh">${settings.map(settingMarkup).join("")}</div>
      <p class="hint">Save the downloaded file in <code>${escape(sourceDirectory)}</code>, then rebuild the module to add its import button.</p>`,
    ok: { label: "Download JSON" },
    rejectClose: false,
  });
  if (!selected) return null;
  const keys = settings
    .filter((_setting, index) => selected[`setting-${index}`] === true)
    .map(({ key }) => key);
  if (!keys.length) {
    ui?.notifications?.info("No settings selected; nothing was exported.");
    return null;
  }
  const result = captureSettings(namespace, keys, includeHidden);
  foundry.utils.saveDataToFile(
    `${JSON.stringify(result.values, null, 2)}\n`,
    "application/json",
    result.filename,
  );
  ui?.notifications?.info(`Exported ${keys.length} settings to ${escape(result.filename)}.`);
  return result;
}
