import { SIMPLE_CALENDAR_PRESET } from "../../integrations/foundryvtt-simple-calendar-reborn/preset";
import { TIMEKEEPING_PRESET } from "../../integrations/simple-timekeeping/preset";
import type {
  PresetExtension,
  SettingsPreset,
} from "../../../../types/settings-presets/SettingsPreset";
import { BOSS_BAR_PRESET_EXTENSION } from "../../integrations/bossbar/preset";
import { SPLATTER_PRESET_EXTENSION } from "../../integrations/splatter/preset";
import { HEALTH_ESTIMATE_PRESET_EXTENSION } from "../../integrations/health-estimate/preset";
import { SETTINGS_PRESETS, PRESET_METADATA } from "./sources";

// Only presets needing computed values or optional-integration gates need an extension.
const extensions: Record<string, PresetExtension> = {
  "foundryvtt-simple-calendar-reborn": SIMPLE_CALENDAR_PRESET,
  "simple-timekeeping": TIMEKEEPING_PRESET,
  "bossbar": BOSS_BAR_PRESET_EXTENSION,
  "healthEstimate": HEALTH_ESTIMATE_PRESET_EXTENSION,
  "splatter": SPLATTER_PRESET_EXTENSION,
};
export function getSettingsPreset(namespace: string): SettingsPreset {
  if (!Object.hasOwn(SETTINGS_PRESETS, namespace))
    throw new Error(`No settings preset exists for ${namespace}.`);
  return {
    namespace,
    values: SETTINGS_PRESETS[namespace]!,
    ...extensions[namespace],
    ...PRESET_METADATA[namespace],
  };
}
export function getSettingsPresets(): SettingsPreset[] {
  return Object.keys(SETTINGS_PRESETS).sort().map(getSettingsPreset);
}
