import { MODULE_ID } from "../../../constants";
import { isModuleActive } from "../is-module-active";
import { registerJournalThemeOptOut } from "./journal-theme";
import { openTemplateDialog } from "./template-dialog";
import type { TemplateControl, TemplateRuntime, TemplateSheet } from "./types";
import { recordStartupFix } from "../../diagnostics/startup-report";

const FIX_IDS = ["simpleQuestBox", "simpleQuestContent"] as const;

export function registerSimpleQuestIntegration(): void {
  if (!isModuleActive("simple-quest")) {
    for (const id of FIX_IDS) recordStartupFix(id, "inactive", "Simple Quest is not active.");
    return;
  }
  if (game?.system.id !== "wfrp4e") {
    for (const id of FIX_IDS) recordStartupFix(id, "inactive", "Requires a WFRP4e world.");
    return;
  }
  registerJournalThemeOptOut();

  // The chooser and editor contracts are private. Reinspect before extending these versions.
  if (
    !["5.3.0", "5.4.5"].includes(game.modules.get("simple-quest")?.version ?? "") ||
    !["14.368", "14.369"].includes(game.version)
  ) {
    for (const id of FIX_IDS)
      recordStartupFix(
        id,
        "unsupported",
        "Requires SQ 5.3.0 or 5.4.5 on Foundry 14.368 or 14.369.",
      );
    console.warn(
      `${MODULE_ID} | Simple Quest page-template fixes skipped for unverified versions.`,
    );
    return;
  }

  // SQ attaches its listener at script load, before this init-time listener. Replace only
  // its control's action; leave native header controls and all other journal writes alone.
  Hooks.on("getHeaderControlsJournalEntryPageHandlebarsSheet", (sheet, controls) => {
    const app = sheet as TemplateSheet | undefined;
    if (!app?.document || !Array.isArray(controls)) return;
    const control = (controls as TemplateControl[]).find(
      (entry) => entry.class === "simple-quest-page-template",
    );
    if (!control || typeof control.onClick !== "function") return;
    control.onClick = () => openTemplateDialog(app, foundry as unknown as TemplateRuntime);
  });
  for (const id of FIX_IDS)
    recordStartupFix(
      id,
      "applied",
      "Replacement Page Template action registered for the supported versions.",
    );
}
