import type { GroupedControl, SettingsGroup } from "../../../../types/settings/Groups";
import { MODULE_ID } from "../../../constants";
import { escapePresetHtml as escape } from "../preset-runtime/presentation";
import { notifyError } from "../../notifications/notify-user";
import { groupedControls, requireSettingsGM, saveGroupedControls } from "./controls";
import { groupedActions, SETTINGS_GROUPS } from "./registry";

function controlMarkup(control: GroupedControl): string {
  const id = `wfrp-group-${control.key}`;
  const input =
    control.type === Boolean
      ? `<input id="${escape(id)}" name="${escape(control.key)}" type="checkbox" ${control.value ? "checked" : ""}>`
      : control.choices
        ? `<select id="${escape(id)}" name="${escape(control.key)}">${Object.entries(
            control.choices,
          )
            .map(
              ([value, label]) =>
                `<option value="${escape(value)}" ${value === control.value ? "selected" : ""}>${escape(label)}</option>`,
            )
            .join("")}</select>`
        : `<input id="${escape(id)}" name="${escape(control.key)}" type="text" value="${escape(String(control.value))}">`;
  return `<div class="form-group"><label for="${escape(id)}">${escape(control.name)}</label><div class="form-fields">${input}</div><p class="hint">${escape(control.hint)}${control.requiresReload && !/reload/i.test(control.hint) ? " Requires a reload." : ""}</p></div>`;
}
function createGroupWindow(group: SettingsGroup) {
  const info = SETTINGS_GROUPS[group];
  return class extends foundry.applications.api.ApplicationV2 {
    static override DEFAULT_OPTIONS = {
      id: `wfrp-settings-${group}`,
      window: { title: `Compatibility Box — ${info.title}`, icon: info.icon, resizable: true },
      position: { width: 740, height: 650 },
    };
    private reloadRequired = false;
    protected override async _renderHTML(): Promise<HTMLElement> {
      requireSettingsGM();
      const controls = groupedControls(group);
      const actions = groupedActions(group);
      const attached = new Set(actions.map(([, action]) => action.settingKey));
      const root = document.createElement("form");
      root.style.cssText = "display:flex;flex-direction:column;gap:12px;height:100%;min-height:0";
      root.innerHTML = `<p>${escape(info.hint)}</p><section class="scrollable" style="overflow:auto;flex:1;min-height:0">${controls
        .filter((c) => !attached.has(c.key))
        .map(controlMarkup)
        .join("")}${actions
        .map(
          ([key, action]) =>
            `<fieldset style="margin:12px 0"><legend>${escape(action.name)}</legend><p class="hint">${escape(action.hint)}</p><button type="button" data-group-action="${escape(key)}"><i class="${escape(action.icon)}" aria-hidden="true"></i> ${escape(action.label)}</button>${controls
              .filter((c) => c.key === action.settingKey)
              .map(controlMarkup)
              .join("")}</fieldset>`,
        )
        .join(
          "",
        )}${!controls.length && !actions.length ? "<p>No supported modules are currently available for this group.</p>" : ""}</section><p role="status" data-status>${this.reloadRequired ? "Saved. Reload connected clients to activate feature changes." : "Changes take effect when you save. Setup actions open their own review."}</p>${controls.length ? '<button type="submit">Save Settings</button>' : ""}`;
      const status = root.querySelector<HTMLElement>("[data-status]")!;
      if (this.reloadRequired) {
        const reload = document.createElement("button");
        reload.type = "button";
        reload.textContent = "Reload Foundry";
        reload.addEventListener("click", async () => {
          requireSettingsGM();
          await foundry.applications.settings.SettingsConfig.reloadConfirm({ world: true });
        });
        root.append(reload);
      }
      const actionButtons = [...root.querySelectorAll<HTMLButtonElement>("[data-group-action]")];
      let unsaved = false;
      const dirty = () => {
        unsaved = true;
        status.textContent =
          "Unsaved changes. Save before running a setup action, or close to discard.";
        for (const button of actionButtons) button.disabled = true;
      };
      root.addEventListener("input", dirty);
      root.addEventListener("change", dirty);
      root.addEventListener("submit", async (event) => {
        event.preventDefault();
        const fields = [
          ...root.querySelectorAll<HTMLInputElement | HTMLSelectElement>("input,select"),
        ];
        const values = Object.fromEntries(
          fields.map((field) => [
            field.name,
            field instanceof HTMLInputElement && field.type === "checkbox"
              ? field.checked
              : field.value,
          ]),
        );
        const buttons = [...root.querySelectorAll<HTMLButtonElement>("button")];
        for (const button of buttons) button.disabled = true;
        try {
          this.reloadRequired =
            (await saveGroupedControls(group, controls, values)) || this.reloadRequired;
          ui?.notifications?.info(
            this.reloadRequired
              ? "Settings saved. Reload connected clients to activate feature changes."
              : "Compatibility Box settings saved.",
          );
          await this.render(true);
        } catch (error) {
          notifyError(error instanceof Error ? error.message : String(error), error);
          // Re-read after any partial save or stale edit; do not replay an old form snapshot.
          await this.render(true);
        }
      });
      for (const button of actionButtons)
        button.addEventListener("click", async () => {
          button.disabled = true;
          try {
            requireSettingsGM();
            const action = actions.find(([key]) => key === button.dataset["groupAction"])?.[1];
            if (action) await new action.type().render(true);
          } catch (error) {
            notifyError(error instanceof Error ? error.message : String(error), error);
          } finally {
            button.disabled = unsaved;
          }
        });
      return root;
    }
    protected override _replaceHTML(result: HTMLElement, content: HTMLElement): void {
      content.replaceChildren(result);
    }
  };
}
export function registerGroupedSettings(): void {
  Hooks.once("setup", () => {
    for (const group of Object.keys(SETTINGS_GROUPS) as SettingsGroup[]) {
      const info = SETTINGS_GROUPS[group];
      game?.settings.registerMenu(MODULE_ID, `settings-${group}`, {
        name: info.title,
        label: `Configure ${info.title}`,
        hint: info.hint,
        icon: info.icon,
        restricted: true,
        type: createGroupWindow(group),
      });
    }
  });
}
