import type {
  PresetExtension,
  SettingValue,
} from "../../../../types/settings-presets/SettingsPreset";
import { MODULE_ID } from "../../../constants";
import { BOSS_BAR_MODULE_ID, BOSS_BAR_SETTINGS } from "./constants";
import { legacyBossBarSetting, previouslyDisabledBossBar } from "./legacy-preferences";

export function usesUpInArms(): boolean {
  return game?.settings.get("wfrp4e", "uiaCrits") === true;
}

export const BOSS_BAR_PRESET_EXTENSION: PresetExtension = {
  title: "Boss Bar",
  watchSettings: ["wfrp4e.uiaCrits"],
  ignoreSetting: BOSS_BAR_SETTINGS.ignorePrompt,
  defaultIgnorePrompt: () =>
    previouslyDisabledBossBar() || legacyBossBarSetting("bossBarIgnoreSetupPrompt") === true,
  enabled: () => game?.system.id === "wfrp4e",
  additionalSettings: () => {
    if (!usesUpInArms() || game?.settings.get(MODULE_ID, BOSS_BAR_SETTINGS.stacked) !== true)
      return [];
    const styles = game?.settings.get(BOSS_BAR_MODULE_ID, "barStyles") as ({ id: string } & Record<
      string,
      SettingValue
    >)[];
    const segmented = styles.find((style) => style.id === "segmented");
    // Theme IDs and custom data stay intact; only the default order changes.
    return segmented && styles[0] !== segmented
      ? [
          {
            namespace: BOSS_BAR_MODULE_ID,
            key: "barStyles",
            value: [segmented, ...styles.filter((style) => style !== segmented)],
          },
        ]
      : [];
  },
};
