// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- The migrated integration extends third-party classes with no published contracts.
// @ts-nocheck -- Argon supplies its weapon-set base class and WFRP4e supplies dynamic actor/item documents at runtime.

import { MODULE_ID } from "../../../constants";
import { deriveArgonWeaponEquipUpdates } from "../../../functions/integrations/enhancedcombathud/argon-logic";
import { getArgonActorFlag } from "./actor-flags";
import { isEquippableWeapon, isWeaponSetItem } from "./argon-helpers";

export function createArgonWeaponSets(CoreHUD) {
  const ARGON = CoreHUD.ARGON;

  class WFRPWeaponSets extends ARGON.WeaponSets {
    async getDefaultSets() {
      const equipped = this.actor.itemTypes.weapon.filter((item) => item.isEquipped);

      return {
        1: {
          primary: equipped[0]?.uuid ?? null,
          secondary: equipped[1]?.uuid ?? null,
        },
        2: { primary: null, secondary: null },
        3: { primary: null, secondary: null },
      };
    }

    async _onDrop(event) {
      event.preventDefault();
      event.stopPropagation();

      const data = JSON.parse(event.dataTransfer.getData("text/plain"));
      if (data.type !== "Item") return;

      const item = await fromUuid(data.uuid);
      if (!isWeaponSetItem(item) || item.actor !== this.actor) {
        throw new Error(
          `${MODULE_ID} | Weapon sets only accept weapons or weapon-like traits owned by the active actor.`,
        );
      }

      const set = event.currentTarget.dataset.set;
      const slot = event.currentTarget.dataset.slot;

      if (!set || !slot) {
        throw new Error(
          `${MODULE_ID} | Argon weapon-set drop target has no set or slot identifier.`,
        );
      }

      const sets = foundry.utils.deepClone(
        this.actor.getFlag("enhancedcombathud", "weaponSets") ?? {},
      );
      sets[set] ??= {};
      sets[set][slot] = item.uuid;

      await this.actor.setFlag("enhancedcombathud", "weaponSets", sets);
      await this.render();
    }

    async _onSetChange({ sets, active }) {
      if (!getArgonActorFlag(this.actor, "switchEquip")) return;

      const weaponSets = Object.entries(sets).map(([setId, slots]) => ({
        id: setId,
        items: Object.values(slots)
          .filter(Boolean)
          .filter(isEquippableWeapon)
          .map((item) => ({
            equipped: Boolean(item.isEquipped),
            id: item.id,
          })),
      }));
      const updates = deriveArgonWeaponEquipUpdates(weaponSets, String(active));

      if (updates.length) await this.actor.updateEmbeddedDocuments("Item", updates);
    }
  }

  return WFRPWeaponSets;
}
