import type {
  ConflictDecisions,
  CompatibilitySettingsCoordinator,
} from "../../../../types/settings-presets/Conflicts";
import type { SettingPreference } from "../../../../types/settings-presets/SettingsPreset";
import { MODULE_ID } from "../../../constants";
import { planResolvedPreferences } from "../../../functions/settings-presets/conflicts";
import { escapePresetHtml } from "../preset-runtime/presentation";
import { collectConflicts } from "./sources";

export const CONFLICT_SETTING = "settingsPresetConflictChoices";
function decisions(): ConflictDecisions {
  return (game?.settings.get(MODULE_ID, CONFLICT_SETTING) ?? {}) as ConflictDecisions;
}
let queue: Promise<unknown> = Promise.resolve();
export const settingsPresetCoordinator: CompatibilitySettingsCoordinator = {
  version: 1,
  inspect: collectConflicts,
  decide: saveDecisions,
  async reset() {
    if (!game?.ready || !game.user?.isGM) throw new Error("A ready GM session is required.");
    await game.settings.set(MODULE_ID, CONFLICT_SETTING, {});
  },
  plan(owner, entries) {
    return planResolvedPreferences(entries, collectConflicts(owner, entries), decisions());
  },
  resolve(owner, entries) {
    const pending = queue.then(() => resolve(owner, entries));
    queue = pending.catch(() => {});
    return pending;
  },
};
async function resolve(owner: string, entries: SettingPreference[]): Promise<boolean> {
  if (!game?.ready || !game.user?.isGM)
    throw new Error("A ready GM session is required to resolve preset conflicts.");
  const conflicts = collectConflicts(owner, entries);
  const unresolved = new Set(
    settingsPresetCoordinator.plan(owner, entries).conflicts.map((issue) => issue.id),
  );
  const selected: ConflictDecisions = {};
  for (const conflict of conflicts.filter((conflict) => unresolved.has(conflict.id))) {
    const escape = escapePresetHtml;
    const result = await foundry.applications.api.DialogV2.input({
      window: { title: "Resolve Settings Preset Conflict" },
      content: `<p>Multiple packages recommend different values for <strong>${escape(conflict.id)}</strong>. Choose which recommendation all cooperating presets should follow.</p><p>Current: <code>${escape(JSON.stringify(game.settings.get(conflict.namespace, conflict.key)))}</code></p><div class="form-group"><label>Preferred settings source</label><select name="source"><option value="">Leave this setting under my control</option>${conflict.candidates.map((candidate, index) => `<option value="${index}">${escape(candidate.title)}</option>`).join("")}</select></div><div class="scrollable" style="max-height:40vh"><ul>${conflict.candidates.map((candidate) => `<li><strong>${escape(candidate.title)}</strong>: <code>${escape(JSON.stringify(candidate.value))}</code></li>`).join("")}</ul></div><p>This saves your preference without applying settings. You will review changes next. Updated competing values will ask again.</p>`,
      ok: { label: "Use This Choice" },
      rejectClose: false,
    });
    if (!result) return false;
    const source = String(result["source"] ?? "");
    const candidate = conflict.candidates.find((_entry, index) => String(index) === source);
    if (source !== "" && !candidate) throw new Error("Choose a listed settings source.");
    selected[conflict.id] = { signature: conflict.signature, source: candidate?.source ?? null };
  }
  await saveDecisions(owner, entries, selected);
  return true;
}
async function saveDecisions(
  owner: string,
  entries: SettingPreference[],
  selected: ConflictDecisions,
): Promise<void> {
  if (!game?.ready || !game.user?.isGM) throw new Error("GM permission changed.");
  if (!Object.keys(selected).length) return;
  const current = collectConflicts(owner, entries);
  for (const [id, decision] of Object.entries(selected)) {
    const conflict = current.find((conflict) => conflict.id === id);
    if (!conflict || conflict.signature !== decision.signature)
      throw new Error("Competing presets changed during review; reopen the action.");
    if (
      decision.source !== null &&
      !conflict.candidates.some((candidate) => candidate.source === decision.source)
    )
      throw new Error("Choose a listed settings source.");
  }
  await game.settings.set(MODULE_ID, CONFLICT_SETTING, { ...decisions(), ...selected });
}
