import { repairMadPrefabExclusions } from "./repair-mad-prefab-exclusions";
import { isModuleActive } from "../is-module-active";
import { installStartupFix, recordStartupFix } from "../../diagnostics/startup-report";

export function registerScenePackerIntegration(): void {
  if (!isModuleActive("scene-packer")) {
    recordStartupFix("scenePacker", "inactive", "Scene Packer is not active.");
    return;
  }
  if (game?.system.id !== "wfrp4e") {
    recordStartupFix("scenePacker", "inactive", "Requires a WFRP4e world.");
    return;
  }

  // Scene Packer publishes this API at script load. Patch at init, before its
  // ready hook calls the content modules' scenePackerReady callbacks.
  if (typeof ScenePacker === "undefined" || typeof ScenePacker.Initialise !== "function") {
    recordStartupFix(
      "scenePacker",
      "unavailable",
      "Scene Packer is active but its initialization API is unavailable at init.",
    );
    return;
  }
  installStartupFix(
    "scenePacker",
    () => repairMadPrefabExclusions(ScenePacker),
    "Guard installed for unavailable MAD prefab exclusions.",
    {
      status: "not-needed",
      detail: "The exclusion guard was already installed.",
    },
  );
}
