import type {
  CalendarEvent,
  CalendarNote,
  EventDate,
} from "../../../types/integrations/calendars/EventSync";
import { imperialDate, imperialTimestamp } from "./imperial";

const repeats = ["", "week", "month", "year", "day"];
const timestamp = (date: EventDate) => imperialTimestamp({ ...date, second: date.seconds });
const date = (time: number): EventDate => {
  const { year, month, day, hour, minute, second } = imperialDate(time);
  return { year, month, day, hour, minute, seconds: second };
};
export function noteToEvent(note: CalendarNote): CalendarEvent {
  const repeat = repeats[note.repeats];
  if (repeat === undefined) throw new Error("Unsupported Simple Calendar recurrence");
  let start = timestamp(note.startDate),
    end = timestamp(note.endDate);
  if (note.allDay) {
    start = Math.floor(start / 86400) * 86400;
    end = Math.floor(end / 86400) * 86400 + 86399;
  }
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start)
    throw new Error("Invalid calendar event dates");
  return { eventTime: start, eventEnd: end, allDay: note.allDay, repeat };
}
export function eventToNote(event: CalendarEvent, calendarId: string): CalendarNote {
  const repeat = repeats.indexOf(event.repeat ?? "");
  if (repeat < 0) throw new Error(`Simple Calendar cannot represent ${event.repeat} recurrence`);
  let start = event.eventTime,
    end = event.eventEnd || start;
  if (event.allDay) {
    start = Math.floor(start / 86400) * 86400;
    end = Math.floor(Math.max(end, start) / 86400) * 86400 + 86399;
  }
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start)
    throw new Error("Invalid calendar event dates");
  return {
    calendarId,
    startDate: date(start),
    endDate: date(end),
    allDay: !!event.allDay,
    repeats: repeat,
  };
}
/** Page permissions inherit independently for each user, not just the default entry. */
export function eventOwnership(
  parent: Record<string, number>,
  page: Record<string, number>,
): Record<string, number> {
  return Object.fromEntries(
    [...new Set(["default", ...Object.keys(parent), ...Object.keys(page)])].map((key) => {
      const level = page[key] ?? page["default"] ?? -1;
      return [key, level < 0 ? (parent[key] ?? parent["default"] ?? 0) : level];
    }),
  );
}
