import type {
  JournalLinkDocument,
  WfrpCompendium,
} from "../../../../types/patches/wfrp4e/JournalLinks";
import type { MapNoteDocument } from "../../../../types/patches/wfrp4e/MapPins";
import { MODULE_ID } from "../../../constants";
import { compendiumsByDocumentId } from "./official-compendiums";

const patched = new WeakSet<MapNoteDocument>();

export function installMapPinCompendiumLinks(): boolean {
  const note = CONFIG.Note?.documentClass?.prototype;
  const placeable = CONFIG.Note?.objectClass?.prototype;
  if (!note || !placeable || patched.has(note) || typeof foundry.utils.fromUuid !== "function")
    return false;

  const nativeEntry = Object.getOwnPropertyDescriptor(note, "entry");
  const draw = placeable._draw;
  if (!nativeEntry?.get || typeof draw !== "function") return false;
  const getWorldEntry = nativeEntry.get as (this: MapNoteDocument) => MapNoteDocument["entry"];
  const targets = new WeakMap<
    MapNoteDocument,
    { entryId: string; pageId: string | null; journal: JournalLinkDocument; pack: WfrpCompendium }
  >();
  const pending = new Map<string, Promise<JournalLinkDocument | null>>();

  function loadJournal(uuid: string) {
    let request = pending.get(uuid);
    if (!request) {
      request = foundry.utils.fromUuid(uuid).finally(() => pending.delete(uuid));
      pending.set(uuid, request);
    }
    return request;
  }

  async function preparePin(document: MapNoteDocument): Promise<void> {
    targets.delete(document);
    const { entryId, pageId } = document;
    if (!game || !entryId || getWorldEntry.call(document)) return;
    for (const { pack } of compendiumsByDocumentId(
      game,
      "JournalEntry",
      entryId,
      document.parent,
    )) {
      const journal = await loadJournal(pack.getUuid(entryId));
      if (document.entryId !== entryId || document.pageId !== pageId) return;
      if (!journal?.pages || !pack.visible || (pageId && !journal.pages.get(pageId))) continue;
      targets.set(document, { entryId, pageId, journal, pack });
      return;
    }
  }

  Object.defineProperty(note, "entry", {
    ...nativeEntry,
    get(this: MapNoteDocument) {
      const worldEntry = getWorldEntry.call(this);
      if (worldEntry) return worldEntry;
      const fallback = targets.get(this);
      if (
        fallback?.pack.visible &&
        fallback.entryId === this.entryId &&
        fallback.pageId === this.pageId
      )
        return fallback.journal;
      return worldEntry;
    },
  });
  placeable._draw = async function (options) {
    try {
      await preparePin(this.document);
    } catch (error) {
      // A failed compendium request must not prevent Foundry from drawing the scene.
      console.warn(`${MODULE_ID} | Could not resolve map pin ${this.document.entryId}.`, error);
    }
    return draw.call(this, options);
  };
  Hooks.on("updateNote", (document, changes) => {
    if (!changes || typeof changes !== "object") return;
    if (!("entryId" in changes || "pageId" in changes)) return;
    void (document as MapNoteDocument).object?.draw().catch((error: unknown) => {
      console.error(`${MODULE_ID} | Could not redraw the updated map pin.`, error);
    });
  });
  patched.add(note);
  return true;
}
