import type { SettingValue } from "../../../types/settings-presets/SettingsPreset";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Compare JSON values independently of object key order. */
export function sameSettingValue(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b))
    return a.length === b.length && a.every((value, index) => sameSettingValue(value, b[index]));
  if (isRecord(a) && isRecord(b)) {
    const keys = Object.keys(a);
    return (
      keys.length === Object.keys(b).length &&
      keys.every((key) => Object.hasOwn(b, key) && sameSettingValue(a[key], b[key]))
    );
  }
  return a === b;
}

/** Reject values JSON would silently discard or coerce. Strings are never parsed as JSON. */
export function cloneSettingValue(value: unknown, ancestors = new Set<object>()): SettingValue {
  if (value === null || typeof value === "boolean" || typeof value === "string") return value;
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value !== "object" || value === null)
    throw new Error("Value cannot be represented completely in JSON");
  if (ancestors.has(value)) throw new Error("Value contains a circular reference");
  const next = new Set(ancestors).add(value);
  if (Array.isArray(value)) return Array.from(value, (entry) => cloneSettingValue(entry, next));
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    throw new Error("Value is not a plain JSON object");
  if (Object.getOwnPropertySymbols(value).length)
    throw new Error("Value contains properties JSON cannot preserve");
  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [key, cloneSettingValue(entry, next)]),
  );
}
