import type { StartupFixStatus, StartupReport } from "../../../types/diagnostics/StartupReport";
import { MODULE_ID } from "../../constants";

const FIXES = {
  rollModes: ["Roll-mode configuration", "wfrp4e"],
  migrationReturns: ["Actor/Item migration returns", "wfrp4e"],
  effectSchema: ["Active Effect changes schema", "wfrp4e"],
  orphanedChat: ["Orphaned chat-card fallback", "wfrp4e"],
  journalCompendiumLinks: ["Journal compendium links", "wfrp4e"],
  mapPinCompendiumLinks: ["Map pin compendium links", "wfrp4e"],
  rollTableCompendiumLookup: ["Compendium lookup for chat table rolls", "wfrp4e"],
  actorlessRuler: ["Actorless-token ruler guard", "wfrp4e"],
  dualWielder: ["Dual Wielder turn-start cleanup", "wfrp4e"],
  scenePacker: ["MAD prefab exclusions", "scene-packer"],
  forgeOwner: ["Forge world-owner detection", "fa-nexus"],
  simpleQuestBox: ["Boxed Text editor preservation", "simple-quest"],
  simpleQuestContent: ["Empty-page template insertion", "simple-quest"],
  argonLegacy: ["Argon legacy module check", "enhancedcombathud"],
  imageContext: ["Token HUD condition image-menu exclusion", "image-context"],
} as const;

export type StartupFixId = keyof typeof FIXES;
const outcomes = new Map<StartupFixId, { status: StartupFixStatus; detail: string }>();
const tasks: Promise<unknown>[] = [];

export function resetStartupReport(): void {
  outcomes.clear();
  tasks.length = 0;
}

export function recordStartupFix(id: StartupFixId, status: StartupFixStatus, detail: string): void {
  outcomes.set(id, { status, detail });
}

/** Capture the actual installation result. A failed patch must not prevent the remaining fixes. */
export function installStartupFix(
  id: StartupFixId,
  install: () => boolean | number,
  appliedDetail: string,
  unchanged: { status: StartupFixStatus; detail: string },
): void {
  try {
    if (install()) recordStartupFix(id, "applied", appliedDetail);
    else if (outcomes.get(id)?.status !== "applied") {
      recordStartupFix(id, unchanged.status, unchanged.detail);
    }
  } catch (error) {
    recordStartupFix(id, "failed", error instanceof Error ? error.message : String(error));
    console.error(`${MODULE_ID} | ${FIXES[id][0]} could not initialize.`, error);
  }
}

/** Include asynchronous installation (currently the Forge import) before publishing the report. */
export function trackStartupTask(id: StartupFixId, task: Promise<unknown>): void {
  tasks.push(
    task.catch((error: unknown) => {
      recordStartupFix(id, "failed", error instanceof Error ? error.message : String(error));
      console.error(`${MODULE_ID} | ${FIXES[id][0]} startup task failed.`, error);
    }),
  );
}

export function getStartupReport(): StartupReport {
  return {
    foundryVersion: game?.version ?? "unknown",
    systemId: game?.system.id ?? "unknown",
    systemVersion: game?.system.version ?? "unknown",
    fixes: Object.entries(FIXES).map(([id, [label, packageId]]) => ({
      id,
      label,
      packageId,
      version:
        (packageId === game?.system.id
          ? game.system.version
          : game?.modules.get(packageId)?.version) ?? "not installed",
      ...(outcomes.get(id as StartupFixId) ?? {
        status: "pending" as const,
        detail: "Installation has not reported a result yet.",
      }),
    })),
  };
}

export async function publishStartupReport(): Promise<void> {
  await Promise.allSettled(tasks);
  for (const id of Object.keys(FIXES) as StartupFixId[]) {
    if (!outcomes.has(id)) {
      recordStartupFix(id, "unavailable", "The startup registration did not report a result.");
    }
  }
  const report = getStartupReport();
  console.groupCollapsed(
    `${MODULE_ID} | Startup fixes | Foundry ${report.foundryVersion}, ${report.systemId} ${report.systemVersion}`,
  );
  console.table(
    report.fixes.map(({ label, version, status, detail }) => ({
      fix: label,
      version,
      status,
      detail,
    })),
  );
  console.groupEnd();
  const problems = report.fixes.filter((fix) =>
    ["unsupported", "unavailable", "failed"].includes(fix.status),
  );
  if (problems.length && game?.user?.isGM) {
    ui?.notifications?.warn(
      `Compatibility Box: ${problems.length} startup fix${problems.length === 1 ? " needs" : "es need"} attention. Open Game Settings → Compatibility Box → Startup Fix Report for details.`,
    );
  }
}
