import { PACKAGE_ID, PACKAGE_TITLE } from "../constants";
import type { FoundryDirectoryEntry, FoundryFolder } from "../../types/folders";
import {
  canTidyImportedContent,
  tidyImportedContentIfEnabled,
} from "../foundry/imported-content/tidy";
import { registerImportedContentSetting } from "../foundry/imported-content/settings";
import { isImportedContent, isPackageCompendiumSource } from "../functions/imported-content/source";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

type AdventureSources = Record<string, Record<string, unknown>[]>;

let timer: ReturnType<typeof setTimeout> | undefined;
let running = false;
let pending = false;

function scheduleImportedContentTidy(): void {
  if (!canTidyImportedContent(game)) return;
  if (running) {
    pending = true;
    return;
  }
  clearTimeout(timer);
  // Importing a pack can fire a burst of hooks across several document batches.
  timer = setTimeout(() => void runImportedContentTidy(), 1000);
}

async function runImportedContentTidy(): Promise<void> {
  running = true;
  pending = false;
  try {
    await tidyImportedContentIfEnabled();
  } catch (error) {
    console.error(`${PACKAGE_TITLE}: Imported content cleanup failed.`, error);
    ui?.notifications?.error(
      `${PACKAGE_TITLE}: Imported content cleanup failed. See the console for details.`,
      {
        permanent: true,
        console: false,
      },
    );
  } finally {
    running = false;
    if (pending) scheduleImportedContentTidy();
  }
}

function onImportedDocument(changed: unknown): void {
  const document = changed as FoundryDirectoryEntry;
  if (!document.pack && !document.parent && isImportedContent(document, PACKAGE_ID))
    scheduleImportedContentTidy();
}

export function registerImportedContentHooks(): void {
  Hooks.once("setup", () => registerImportedContentSetting(scheduleImportedContentTidy));
  Hooks.once("ready", scheduleImportedContentTidy);
  Hooks.on("userConnected", scheduleImportedContentTidy);
  Hooks.on("updateUser", scheduleImportedContentTidy);

  for (const type of CONST.FOLDER_DOCUMENT_TYPES) {
    if (type === "Compendium") continue;
    Hooks.on(`create${type}`, onImportedDocument);
    Hooks.on(`update${type}`, (document, changes) => {
      if (Object.hasOwn(changes as object, "folder")) onImportedDocument(document);
    });
  }
  Hooks.on("updateFolder", (changed, changes) => {
    const folder = changed as FoundryFolder;
    if (folder.type !== "Compendium" && !folder.pack && Object.hasOwn(changes as object, "folder"))
      scheduleImportedContentTidy();
  });
  Hooks.on("deleteFolder", (changed) => {
    const folder = changed as FoundryFolder;
    if (folder.type !== "Compendium" && !folder.pack) scheduleImportedContentTidy();
  });

  // Adventure imports create world documents from raw sources, without native provenance.
  Hooks.on("preImportAdventure", (imported, _options, created, updated) => {
    const adventure = imported as { uuid: string };
    const toCreate = created as AdventureSources;
    const toUpdate = updated as AdventureSources;
    if (!isPackageCompendiumSource(adventure.uuid, PACKAGE_ID)) return;
    for (const type of CONST.FOLDER_DOCUMENT_TYPES) {
      for (const source of [...(toCreate[type] ?? []), ...(toUpdate[type] ?? [])]) {
        const stats = source["_stats"];
        source["_stats"] = {
          ...(isRecord(stats) ? stats : {}),
          compendiumSource: adventure.uuid,
        };
      }
    }
  });
  Hooks.on("importAdventure", scheduleImportedContentTidy);
}
