import type { GroupedControl, SettingsGroup } from "../../../../types/settings/Groups";
import { MODULE_ID } from "../../../constants";
import { OPTIONAL_FEATURES } from "../optional-features";
import { BOSS_BAR_SETTINGS } from "../../integrations/bossbar/constants";
import { groupedActions } from "./registry";

export function settingGroup(key: string): SettingsGroup | undefined {
  for (const group of ["presets", "calendars", "world", "integrations"] as const)
    if (groupedActions(group).some(([, action]) => action.settingKey === key)) return group;
  if (
    ["simpleCalendarEnabled", "simpleTimekeepingEnabled"].includes(key) ||
    /^ignoreSettingsPreset-(foundryvtt-simple-calendar-reborn|simple-timekeeping)$/.test(key)
  )
    return "calendars";
  if (key.startsWith("ignoreSettingsPreset-")) return "presets";
  if (
    ["keepWfrpImportedContentTidy", "keepWfrpCompendiumsTidy", "keepImportedContentTidy"].includes(
      key,
    )
  )
    return "world";
  if (
    [
      ...Object.values(OPTIONAL_FEATURES).map((f) => f.settingKey),
      ...Object.values(BOSS_BAR_SETTINGS),
      "argonCombatItemPatterns",
    ].includes(key)
  )
    return "integrations";
  return undefined;
}
export function groupedControls(group: SettingsGroup): GroupedControl[] {
  return [...(game?.settings.settings ?? [])].flatMap(([id, raw]) => {
    if (!id.startsWith(`${MODULE_ID}.`)) return [];
    const key = id.slice(MODULE_ID.length + 1);
    if (settingGroup(key) !== group) return [];
    const definition = raw as {
      name: string;
      hint: string;
      type: BooleanConstructor | StringConstructor;
      choices?: Record<string, string> | (() => Record<string, string>);
      requiresReload?: boolean;
    };
    if (![Boolean, String].includes(definition.type)) return [];
    const choices =
      typeof definition.choices === "function" ? definition.choices() : definition.choices;
    return [
      {
        key,
        name: game!.i18n.localize(definition.name),
        hint: game!.i18n.localize(definition.hint),
        type: definition.type,
        value: game!.settings.get(MODULE_ID, key) as boolean | string,
        requiresReload: !!definition.requiresReload,
        ...(choices ? { choices } : {}),
      },
    ];
  });
}
export function requireSettingsGM(): void {
  if (!game?.ready || !game.user?.isGM)
    throw new Error("A GM in a loaded world is required to configure Compatibility Box.");
}
export async function saveGroupedControls(
  group: SettingsGroup,
  previous: GroupedControl[],
  values: Record<string, unknown>,
): Promise<boolean> {
  requireSettingsGM();
  const current = groupedControls(group);
  const changes = previous.filter((control) => values[control.key] !== control.value);
  for (const control of changes) {
    const latest = current.find((c) => c.key === control.key);
    if (!latest || latest.value !== control.value)
      throw new Error(
        "These settings changed in another window. Reopen this window before saving.",
      );
    const value = values[control.key];
    if (
      (control.type === Boolean && typeof value !== "boolean") ||
      (control.type === String && typeof value !== "string") ||
      (latest.choices && !Object.hasOwn(latest.choices, String(value)))
    )
      throw new Error(`Choose a valid value for ${control.name}.`);
  }
  for (const control of changes) {
    requireSettingsGM();
    await game!.settings.set(MODULE_ID, control.key, values[control.key]);
  }
  return changes.some((c) => c.requiresReload);
}
