import { CALENDAR_CATALOG } from "./content-catalog";
export { CALENDAR_CATALOG } from "./content-catalog";
import type {
  CalendarContentOptions,
  ContentDraft,
  ImperialHoliday,
  ImperialHistory,
} from "../../../types/integrations/calendars/Content";
import { IMPERIAL_MONTHS, imperialDate, imperialTimestamp } from "./imperial";

export const SC_NOTES = "foundryvtt-simple-calendar-reborn";
export const ST_EVENTS = "simple-timekeeping";
const escape = (value: string) =>
  value.replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
  );

/** Stable document IDs allow retries and cooperating GM clients to converge on the same entries. */
export function documentId(value: string): string {
  let a = 2166136261,
    b = 5381;
  for (const char of value) {
    a = Math.imul(a ^ char.charCodeAt(0), 16777619);
    b = Math.imul(b, 33) ^ char.charCodeAt(0);
  }
  return (a >>> 0).toString(16).padStart(8, "0") + (b >>> 0).toString(16).padStart(8, "0");
}
export function contentSources(ids: string[]): string {
  return `<p><strong>Sources:</strong> ${ids
    .map((id) => {
      const source = CALENDAR_CATALOG.sources[id];
      if (!source) throw new Error(`Unknown calendar source: ${id}`);
      return source.uuid
        ? `@UUID[${source.uuid}]{${source.title}}`
        : source.url
          ? `<a href="${escape(source.url)}">${escape(source.title)}</a>`
          : escape(source.title);
    })
    .join("; ")}</p>`;
}
export function holidayDateLabel(h: ImperialHoliday): string {
  const start = IMPERIAL_MONTHS[h.month]!;
  const label = `${start.intercalary ? "" : `${h.day} `}${start.name}`;
  if (h.month === h.endMonth && h.day === h.endDay) return label;
  return `${label} – ${h.endDay} ${IMPERIAL_MONTHS[h.endMonth]!.name}`;
}
export function historyDateLabel(h: ImperialHistory): string {
  const day = h.date ? `${h.date.day} ${IMPERIAL_MONTHS[h.date.month]!.name} ` : "";
  return `${h.approximate ? "c. " : ""}${day}${h.year}${h.endYear === h.year ? "" : `–${h.endYear}`} IC (${h.precision})`;
}
function makeJournal(
  owner: string,
  slug: string,
  name: string,
  content: string,
  visibility: number,
): ContentDraft {
  return {
    _id: documentId(`${owner}:${slug}`),
    name,
    folder: null,
    ownership: { default: visibility },
    flags: { [owner]: { calendarContent: { id: slug, version: 1 } } },
    pages: [
      {
        _id: documentId(`${owner}:${slug}:details`),
        name,
        type: "text",
        text: { format: 1, content },
        ownership: { default: -1 },
        flags: {},
      },
    ],
  };
}
export function addCalendarDates(
  draft: ContentDraft,
  startTime: number,
  endTime: number,
  yearly: boolean,
  calendarId: string | undefined,
  timekeeping: boolean,
): void {
  if (calendarId) {
    const date = (t: number) => {
      const { year, month, day, hour, minute, second } = imperialDate(t);
      return { year, month, day, hour, minute, seconds: second };
    };
    draft.flags[SC_NOTES] = {
      noteData: {
        calendarId,
        startDate: date(startTime),
        endDate: date(endTime),
        allDay: startTime % 86400 === 0 && (endTime + 1) % 86400 === 0,
        repeats: yearly ? 3 : 0,
        order: 0,
        categories: [],
        remindUsers: [],
        macro: "none",
        fromPredefined: false,
      },
    };
    draft.flags["core"] = { sheetClass: `${SC_NOTES}.NoteSheet` };
  }
  if (timekeeping)
    draft.pages[0]!.flags[ST_EVENTS] = {
      allDay: startTime % 86400 === 0 && (endTime + 1) % 86400 === 0,
      notify: "none",
      eventTime: startTime,
      eventEnd: endTime,
      repeat: yearly ? "year" : "",
    };
}

export function calendarContentDrafts(
  owner: string,
  options: CalendarContentOptions,
  targets: { calendarId?: string; timekeeping: boolean },
  year: number,
): ContentDraft[] {
  const result: ContentDraft[] = [];
  if (options.holidays !== false)
    for (const h of CALENDAR_CATALOG.holidays) {
      const start = imperialTimestamp({
        year,
        month: h.month,
        day: h.day - 1,
        hour: 0,
        minute: 0,
        second: 0,
      });
      const end = imperialTimestamp({
        year,
        month: h.endMonth,
        day: h.endDay - 1,
        hour: 23,
        minute: 59,
        second: 59,
      });
      const draft = makeJournal(
        owner,
        h.id,
        h.name,
        `<p><strong>${escape(holidayDateLabel(h))}</strong> · ${escape(h.region)} · Annual observance</p><p>${escape(h.summary)}</p>${contentSources(h.sources)}`,
        2,
      );
      addCalendarDates(draft, start, end, true, targets.calendarId, targets.timekeeping);
      result.push(draft);
    }
  if (options.history !== false) {
    const rows = CALENDAR_CATALOG.history
      .map(
        (h) =>
          `<tr><td>${escape(historyDateLabel(h))}</td><td><strong>${escape(h.title)}</strong><p>${escape(h.summary)}</p>${h.date ? `<p><strong>Date basis:</strong> ${escape(h.date.basis)}</p>` : ""}${contentSources(h.sources)}</td></tr>`,
      )
      .join("");
    const notes = CALENDAR_CATALOG.researchNotes
      .map((n) => `<h3>${escape(n.title)}</h3><p>${escape(n.text)}</p>${contentSources(n.sources)}`)
      .join("");
    const draft = makeJournal(
      owner,
      "ubersreik-history",
      "Ubersreik — Historical Almanac",
      `<p>GM reference. Published years and ranges are retained. Exact-date entries identify their date basis: published scenario dates use an assumed campaign year, and the deposition uses the explicitly approved provisional date of 5 Nachexen 2512 IC.</p><table><thead><tr><th>Date and precision</th><th>Event</th></tr></thead><tbody>${rows}</tbody></table><h2>Dating notes and movable festivals</h2>${notes}`,
      0,
    );
    result.push(draft);
    for (const h of CALENDAR_CATALOG.history) {
      if (!h.date) continue;
      const start = imperialTimestamp({
        year: h.year,
        month: h.date.month,
        day: h.date.day - 1,
        hour: 0,
        minute: 0,
        second: 0,
      });
      const event = makeJournal(
        owner,
        `history-${h.id}`,
        h.title,
        `<p><strong>${escape(historyDateLabel(h))}</strong></p><p>${escape(h.summary)}</p><p><strong>Date basis:</strong> ${escape(h.date.basis)}</p>${contentSources(h.sources)}`,
        0,
      );
      addCalendarDates(
        event,
        start,
        start + 86400 - 1,
        false,
        targets.calendarId,
        targets.timekeeping,
      );
      result.push(event);
    }
  }
  return result;
}
