import type {
  SettingRegistration,
  SettingValue,
} from "../../../../types/settings-presets/SettingsPreset";
import { cloneSettingValue, sameSettingValue } from "../../../functions/settings-presets/values";

export function settingValueToSource(setting: SettingRegistration, value: unknown): SettingValue {
  if (value instanceof foundry.abstract.DataModel) value = value.toObject();
  else if (setting.type instanceof foundry.data.fields.DataField)
    value = setting.type.toObject(value);
  return cloneSettingValue(value);
}

/** Use the native schema, rejecting coercion or dropped properties before any writes. */
export function validateSettingSource(setting: SettingRegistration, value: SettingValue): void {
  const type = setting.type;
  let candidate = cloneSettingValue(value);
  if (type instanceof foundry.data.fields.DataField) {
    candidate = cloneSettingValue(type.clean(candidate));
    type.validate(candidate, { fallback: false, strict: true });
  } else if (typeof type === "function" && type.prototype instanceof foundry.abstract.DataModel) {
    candidate = cloneSettingValue(
      (type as typeof foundry.abstract.DataModel)
        .fromSource(candidate, { strict: true })
        .toObject(),
    );
  } else if (
    (type === String && typeof candidate !== "string") ||
    (type === Number && typeof candidate !== "number") ||
    (type === Boolean && typeof candidate !== "boolean") ||
    (type === Array && !Array.isArray(candidate)) ||
    (type === Object &&
      (candidate === null || typeof candidate !== "object" || Array.isArray(candidate)))
  )
    throw new Error("Preset value does not match this world's setting type.");
  if (!sameSettingValue(value, candidate))
    throw new Error("Preset value does not match this world's setting schema.");
}
