import type {
  CalendarEvent,
  CalendarNote,
  EventDate,
  SyncDocument,
  SyncLink,
} from "../../../../../types/integrations/calendars/EventSync";
import type {
  MigrationSnapshot,
  NamedDate,
} from "../../../../../types/integrations/calendars/Migration";
import { MODULE_ID } from "../../../../constants";
import { SC_NOTES, ST_EVENTS } from "../../../../functions/calendars/content";
import { isOptionalFeatureEnabled } from "../../../settings/is-optional-feature-enabled";

export const migrationJournals = () => [...game!.journal] as unknown as SyncDocument[];
export function requireMigrationGM(): void {
  if (!game?.ready || !game.user?.isGM || game.system.id !== "wfrp4e")
    throw new Error("A ready WFRP GM session is required.");
}
export function captureCalendarMigration(): MigrationSnapshot {
  requireMigrationGM();
  const snapshot: MigrationSnapshot = {
    time: game!.time.worldTime,
    journalIds: migrationJournals().map((j) => j.id),
    settings: [],
    sources: [],
    events: [],
  };
  const save = (namespace: string, key: string) => {
    const value = JSON.parse(JSON.stringify(game!.settings.get(namespace, key)));
    snapshot.settings.push({ namespace, key, value });
    return value;
  };
  const journals = migrationJournals();
  if (isOptionalFeatureEnabled("simpleCalendar")) {
    const api = (
      globalThis as typeof globalThis & {
        SimpleCalendar?: {
          api: {
            getAllCalendars(): unknown;
            currentDateTime(id: string): EventDate;
            dateToTimestamp(date: EventDate, id: string): number;
          };
        };
      }
    ).SimpleCalendar?.api;
    if (!api) throw new Error("Simple Calendar is not ready. Reload before migrating.");
    const saved = save(SC_NOTES, "calendar-configuration");
    const calendars = saved.length ? saved : JSON.parse(JSON.stringify(api.getAllCalendars()));
    snapshot.settings[0]!.value = calendars;
    const id = String(save(SC_NOTES, "active-calendar"));
    const calendar = calendars.find((c: { id: string }) => c.id === id);
    if (!calendar) throw new Error("Select a Simple Calendar before migrating.");
    snapshot.activeId = id;
    const named = (date: EventDate): NamedDate => ({
      ...date,
      monthName: calendar.months[date.month]?.name ?? "Unknown month",
    });
    snapshot.sources.push({
      id: "scr",
      name: calendar.name,
      epoch: calendar.year.yearZero,
      months: calendar.months.map((m: { name: string; numberOfDays: number }) => ({
        name: m.name,
        days: m.numberOfDays,
      })),
      current: named(api.currentDateTime(id)),
    });
    for (const journal of journals) {
      const note = journal.flags[SC_NOTES]?.["noteData"] as CalendarNote | undefined;
      if (!note || note.calendarId !== id) continue;
      const link = journal.flags[MODULE_ID]?.["calendarSync"] as SyncLink | undefined;
      const start = {
        ...note.startDate,
        ...(note.allDay ? { hour: 0, minute: 0, seconds: 0 } : {}),
      };
      const end = {
        ...note.endDate,
        ...(note.allDay ? { hour: 23, minute: 59, seconds: 59 } : {}),
      };
      snapshot.events.push({
        journal: journal.id,
        name: `${journal.name} (SCR)`,
        note: structuredClone(note),
        dates: [named(start), named(end)],
        times: [api.dateToTimestamp(start, id), api.dateToTimestamp(end, id)],
        ...(link ? { linked: `${link.journal}/${link.page}` } : {}),
      });
    }
  }
  if (isOptionalFeatureEnabled("simpleTimekeeping")) {
    save(ST_EVENTS, "configuration");
    save(ST_EVENTS, "customCalendars");
    const calendar = game!.time.calendar as unknown as {
      years: { yearZero: number };
      months: { values: { name: string; days: number }[] };
      timeToComponents(time: number): {
        year: number;
        month: number;
        dayOfMonth: number;
        hour: number;
        minute: number;
        second: number;
      };
    };
    const named = (time: number): NamedDate => {
      const d = calendar.timeToComponents(time);
      return {
        year: d.year + 1,
        month: d.month,
        monthName: calendar.months.values[d.month]?.name ?? "Unknown month",
        day: d.dayOfMonth,
        hour: d.hour,
        minute: d.minute,
        seconds: d.second,
      };
    };
    snapshot.sources.push({
      id: "st",
      name: "Simple Timekeeping & Calendar",
      epoch: calendar.years.yearZero,
      months: calendar.months.values.map((m) => ({ name: m.name, days: m.days })),
      current: named(snapshot.time),
    });
    for (const journal of journals)
      for (const page of journal.pages?.contents ?? []) {
        const event = page.flags[ST_EVENTS] as CalendarEvent | undefined;
        if (event?.eventTime === undefined) continue;
        const partner = snapshot.events.find((e) => e.linked === `${journal.id}/${page.id}`);
        // Recognize our pre-bridge dual-format imports by document identity, never names/dates.
        const shared =
          !partner &&
          journal.pages?.contents.filter((p) => p.flags[ST_EVENTS]?.["eventTime"] !== undefined)
            .length === 1
            ? snapshot.events.find((e) => e.journal === journal.id && !e.linked)
            : undefined;
        const linked = partner ?? shared;
        if (linked) linked.linked = `${journal.id}/${page.id}`;
        const end = event.eventEnd ?? event.eventTime;
        snapshot.events.push({
          journal: journal.id,
          page: page.id,
          name: `${page.name} (ST&C)`,
          event: structuredClone(event),
          dates: [named(event.eventTime), named(end)],
          times: [event.eventTime, end],
          ...(linked ? { linked: `${linked.journal}/` } : {}),
        });
      }
  }
  if (!snapshot.sources.length)
    throw new Error("Enable a supported calendar compatibility feature first.");
  return snapshot;
}
