import type { PresetExtension } from "../../../../types/settings-presets/SettingsPreset";
import { configureTimekeeping } from "../../../functions/calendars/configuration";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";

export const TIMEKEEPING_MODULE_ID = "simple-timekeeping";
export const TIMEKEEPING_PRESET: PresetExtension = {
  title: "Simple Timekeeping & Calendar — WFRP Imperial Calendar",
  enabled: () => game?.system.id === "wfrp4e" && isOptionalFeatureEnabled("simpleTimekeeping"),
  additionalSettings: () => {
    const next = configureTimekeeping(
      game?.settings.get(TIMEKEEPING_MODULE_ID, "configuration"),
      game?.settings.get(TIMEKEEPING_MODULE_ID, "customCalendars"),
    );
    return [
      { namespace: TIMEKEEPING_MODULE_ID, key: "customCalendars", value: next.customCalendars },
      { namespace: TIMEKEEPING_MODULE_ID, key: "configuration", value: next.configuration },
    ];
  },
};
