import { isRecord } from "../paper-doll/wfrp-runtime-types";

interface TurnScript {
  script: string;
  context?: { effect?: { statuses: ReadonlySet<string> } };
}

interface ScriptCollector {
  getScripts(trigger: string, ...args: unknown[]): TurnScript[];
}

const repaired = new WeakSet<ScriptCollector>();
export const DUAL_WIELDER_VERSIONS: readonly string[] = ["10.0.3", "10.1.2"];

/** WFRP's unique-GM turn helper already removes Dual Wielder; avoid a player-owner race. */
export function repairDualWielderCleanup(): boolean {
  // These inspected releases contain both cleanup paths. Do not change unknown future behavior.
  if (!game || !DUAL_WIELDER_VERSIONS.includes(game.system.version)) return false;
  const documentClass = CONFIG.Actor["documentClass"];
  if (typeof documentClass !== "function") return false;
  const prototype: unknown = documentClass.prototype;
  if (!isRecord(prototype) || typeof prototype["getScripts"] !== "function") return false;
  const collector = prototype as unknown as ScriptCollector;
  if (repaired.has(collector)) return false;
  const original = collector.getScripts;
  collector.getScripts = function (trigger, ...args) {
    const scripts = original.call(this, trigger, ...args);
    if (trigger !== "startTurn") return scripts;
    return scripts.filter(
      (script) =>
        !(
          script.context?.effect?.statuses.has("dualwielder") &&
          /^this\.effect\.delete\(\);?$/.test(script.script.trim())
        ),
    );
  };
  repaired.add(collector);
  return true;
}
