import type { MigrationPlan } from "../../../../../types/integrations/calendars/Migration";
import type { SyncLink } from "../../../../../types/integrations/calendars/EventSync";
import { MODULE_ID } from "../../../../constants";
import { ST_EVENTS } from "../../../../functions/calendars/content";
import { migrationJournals } from "./snapshot";

/** Undo bridge counterparts added after migration, retaining source journals and prose. */
export async function restoreMigrationLinks(plan: MigrationPlan): Promise<void> {
  const notes = new Set(plan.snapshot.events.filter((e) => e.note).map((e) => e.journal));
  const events = new Set(
    plan.snapshot.events.filter((e) => e.event).map((e) => `${e.journal}/${e.page}`),
  );
  for (const journal of migrationJournals()) {
    const link = journal.flags[MODULE_ID]?.["calendarSync"] as SyncLink | undefined;
    if (!link) continue;
    const source = `${link.journal}/${link.page}`;
    if (link.mirror && !plan.snapshot.journalIds.includes(journal.id) && events.has(source)) {
      await journal.delete({ calendarSync: true });
    } else if (
      !link.mirror &&
      notes.has(journal.id) &&
      !events.has(source) &&
      link.journal === journal.id
    ) {
      const page = journal.pages?.contents.find((p) => p.id === link.page);
      if (page) await page.update({ [`flags.-=${ST_EVENTS}`]: null }, { calendarSync: true });
      await journal.update({ [`flags.${MODULE_ID}.-=calendarSync`]: null }, { calendarSync: true });
    }
  }
}
