// Keep hook, settings, and public API calls from planning against the same stale folders.
const pending = new WeakMap<object, Promise<unknown>>();

export async function queueFolderTidy<Result>(
  owner: object,
  operation: () => Promise<Result>,
): Promise<Result> {
  const previous = pending.get(owner) ?? Promise.resolve();
  const next = previous
    .catch(() => undefined)
    .then(async () => {
      // Web Locks also serialize cooperating modules and GM tabs on the same browser origin.
      const locks = globalThis.navigator?.locks;
      if (locks) return await locks.request("foundry:folder-tidy", operation);
      return operation();
    });
  pending.set(owner, next);
  try {
    return await next;
  } finally {
    if (pending.get(owner) === next) pending.delete(owner);
  }
}
