import type { FoundryGame } from "../../../../types/foundry";
import type { WfrpCompendium } from "../../../../types/patches/wfrp4e/JournalLinks";
import type {
  TableColumn,
  WfrpRollTable,
  WfrpTableApi,
  WfrpTableLookup,
} from "../../../../types/patches/wfrp4e/RollTables";
import { officialCompendiums } from "./official-compendiums";

const BUILTIN_KEYS = new Set(["menu", "scatter", "hitloc"]);
const TABLE_FIELDS = ["flags.wfrp4e.key", "flags.wfrp4e.column"];
const patched = new WeakSet<WfrpTableApi>();
type TableIndex = Awaited<ReturnType<WfrpCompendium["getIndex"]>>;
const indexing = new WeakMap<WfrpCompendium, Promise<TableIndex>>();

function getTableIndex(pack: WfrpCompendium): Promise<TableIndex> {
  let request = indexing.get(pack);
  if (!request) {
    request = pack.getIndex({ fields: TABLE_FIELDS }).finally(() => indexing.delete(pack));
    indexing.set(pack, request);
  }
  return request;
}

function configuredIds(currentGame: FoundryGame, key: string, column: TableColumn): string[] {
  const settings = currentGame.settings.get("wfrp4e", "tableSettings") as Record<string, string>;
  return settings?.[column ? `${key}-${column}` : key]?.split(",").filter(Boolean) ?? [];
}

function tableColumn(table: WfrpRollTable) {
  return table.getFlag("wfrp4e", "column");
}

function chooseColumns<T>(
  items: T[],
  column: TableColumn,
  getColumn: (item: T) => string | undefined,
): T[] {
  const exact = items.find((item) => (getColumn(item) || null) === (column || null));
  if (exact) return [exact];
  if (column) return [];
  // Pick one table per column. Order is inherited from the selected pack or configured list.
  const columns = new Map<string, T>();
  for (const item of items) {
    const name = getColumn(item);
    if (name && !columns.has(name)) columns.set(name, item);
  }
  return [...columns.values()];
}

function tableLookup(tables: WfrpRollTable[]): WfrpTableLookup | undefined {
  const first = tables[0];
  if (first && tables.length > 1)
    return { name: first.name.split("-")[0]!.trim(), columns: tables };
  return first;
}

function nativeLookup(
  currentGame: FoundryGame,
  tables: WfrpTableApi,
  key: string,
  column: TableColumn,
) {
  const ids = configuredIds(currentGame, key, column);
  const entries = ids.length > 1 ? ids.map((id) => currentGame.tables.get(id)) : [];
  const stale = entries.includes(undefined);
  if (!stale) return { stale, table: tables.findTable(key, column) };
  // Native findTable dereferences missing entries in configured lists. Keep surviving world
  // choices available before looking in compendiums, without altering the saved setting.
  const surviving = entries.filter((table) => table !== undefined);
  const candidates = surviving.length
    ? surviving
    : [...currentGame.tables].filter((table) => table.getFlag("wfrp4e", "key") === key);
  return { stale, table: tableLookup(chooseColumns(candidates, column, tableColumn)) };
}

async function packedTables(currentGame: FoundryGame, key: string, column: TableColumn) {
  const packs = officialCompendiums(currentGame, "RollTable").sort(
    (a, b) => Number(b.packageId === "wfrp4e-core") - Number(a.packageId === "wfrp4e-core"),
  );
  const indexes = await Promise.all(
    packs.map(async ({ pack }) => ({ pack, index: await getTableIndex(pack) })),
  );
  const groups = indexes
    .filter(({ pack }) => pack.visible)
    .map(({ pack, index }) =>
      [...index].map((row) => ({
        pack,
        id: row._id,
        name: row.name,
        key: row.flags?.wfrp4e?.key,
        column: row.flags?.wfrp4e?.column,
      })),
    );

  const explicit = configuredIds(currentGame, key, column);
  const preferred = explicit.length
    ? explicit
    : column
      ? configuredIds(currentGame, key, null)
      : [];
  if (preferred.length) {
    const indexed = groups.flat();
    const configured = preferred.flatMap((id) => {
      const entry = indexed.find(
        (row) => row.id === id && (!column || explicit.length > 0 || row.column === column),
      );
      return entry ? [entry] : [];
    });
    const selected =
      column && configured.length > 1
        ? chooseColumns(configured, column, (row) => row.column)
        : configured;
    if (selected.length) return selected;
  }
  for (const group of groups) {
    const matches = chooseColumns(
      group.filter((row) => row.key === key),
      column,
      (row) => row.column,
    );
    if (matches.length) return matches;
  }
  return [];
}

export function installRollTableCompendiumLookup(): boolean {
  const tables = game?.wfrp4e?.tables;
  if (
    !tables ||
    patched.has(tables) ||
    typeof tables.formatChatRoll !== "function" ||
    typeof tables.findTable !== "function" ||
    typeof tables.generalizeTable !== "function" ||
    typeof foundry.utils.fromUuid !== "function"
  )
    return false;

  const format = tables.formatChatRoll;
  tables.formatChatRoll = async function (input, options, column) {
    if (!game) return format.call(this, input, options, column);
    const key = this.generalizeTable(input);
    if (BUILTIN_KEYS.has(key)) return format.call(this, input, options, column);
    const currentGame = game;
    const native = nativeLookup(currentGame, this, key, column);
    if (native.table && !native.stale) return format.call(this, input, options, column);

    const candidates = native.table ? [] : await packedTables(currentGame, key, column);
    const documents = await Promise.all(
      candidates.map(async ({ pack, id }) => {
        if (!pack.visible) return null;
        const table = await foundry.utils.fromUuid<WfrpRollTable>(pack.getUuid(id));
        return pack.visible ? table : null;
      }),
    );
    const fallback = tableLookup(documents.filter((table) => table !== null));
    if (!fallback && !native.stale) return format.call(this, input, options, column);

    // WFRP uses this.findTable throughout formatting, rolling and column prompts. Give this
    // one roll a lookup without replacing global findTable or changing another concurrent roll.
    const selected = nativeLookup(currentGame, this, key, column).table ?? fallback;
    const receiver = Object.create(this) as WfrpTableApi;
    receiver.findTable = (requestedKey, requestedColumn) => {
      if (requestedKey === key && (requestedColumn ?? null) === (column ?? null)) {
        return selected;
      }
      return this.findTable(requestedKey, requestedColumn);
    };
    return format.call(receiver, input, options, column);
  };

  const tableLink = CONFIG.TextEditor?.enrichers.find(({ pattern }) =>
    pattern.source.startsWith("@Table\\["),
  );
  if (tableLink) {
    const enrich = tableLink.enricher;
    tableLink.enricher = async function (match, options) {
      const [input, modifier] = match[1]?.split(",") ?? [];
      if (!game || !input || match[2]) return enrich.call(this, match, options);
      const key = tables.generalizeTable(input);
      const native = nativeLookup(game, tables, key, null).table;
      const packed = native || BUILTIN_KEYS.has(key) ? [] : await packedTables(game, key, null);
      const name =
        native?.name ??
        (packed.length > 1 ? packed[0]?.name.split("-")[0]?.trim() : packed[0]?.name) ??
        input;
      const anchor = document.createElement("a");
      anchor.className = "action-link";
      Object.assign(anchor.dataset, {
        action: "clickTable",
        table: input,
        modifier: modifier || "0",
      });
      const icon = document.createElement("i");
      icon.className = "fas fa-list";
      anchor.append(icon, name);
      return anchor;
    };
  }

  patched.add(tables);
  return true;
}
