import { refreshCalendar } from "./event-refresh";
import { MODULE_ID } from "../../../constants";
import { SC_NOTES, ST_EVENTS } from "../../../functions/calendars/content";
import { dayStart, installNoteOccurrences } from "../../../functions/calendars/recurrence";
import type {
  CalendarNote,
  SyncDocument,
  SyncLink,
} from "../../../../types/integrations/calendars/EventSync";
import type {
  CalendarApp,
  NoteStub,
  Occurrence,
  RecurrenceContext,
  RecurrenceSheet,
} from "../../../../types/integrations/calendars/Recurrence";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { usesImperialCalendar } from "../simple-timekeeping/register-integration";

const patchedNotes = new WeakSet<object>(),
  patchedSheets = new WeakSet<object>();
let app: CalendarApp | undefined;
let notesInstalled = false;
const documents = () => [...game!.journal] as unknown as SyncDocument[];
function enabled(): boolean {
  if (!game?.ready || !isOptionalFeatureEnabled("simpleCalendar") || !usesImperialCalendar())
    return false;
  const active = game.settings.get(SC_NOTES, "active-calendar");
  const calendars = game.settings.get(SC_NOTES, "calendar-configuration") as {
    id: string;
    year: { yearZero: number };
  }[];
  return calendars?.find((c) => c.id === active)?.year.yearZero === 1;
}
function context(id: string, calendar?: string): RecurrenceContext | undefined {
  if (!enabled()) return;
  const journal = documents().find((j) => j.id === id);
  const note = journal?.flags[SC_NOTES]?.["noteData"] as CalendarNote | undefined;
  const link = journal?.flags[MODULE_ID]?.["calendarSync"] as SyncLink | undefined;
  if (
    !link ||
    !note ||
    (calendar && calendar !== note.calendarId) ||
    note.calendarId !== game!.settings.get(SC_NOTES, "active-calendar")
  )
    return;
  const page = documents()
    .find((j) => j.id === link.journal)
    ?.pages?.contents.find((p) => p.id === link.page);
  const clock = (
    ui as unknown as {
      simpleTimekeeping?: {
        getEventOccurrences(page: SyncDocument, start: number, end: number): Occurrence[];
      };
    }
  )?.simpleTimekeeping;
  if (
    !page ||
    !Number.isFinite(page.flags[ST_EVENTS]?.["eventTime"]) ||
    !clock?.getEventOccurrences
  )
    return;
  return {
    allDay: !!page.flags[ST_EVENTS]?.["allDay"],
    occurrences: (start, end) => clock.getEventOccurrences(page, start, end),
  };
}
function selectedDay(): number {
  const calendar = app!.visibleCalendar;
  const selected = calendar.getMonthAndDayIndex("selected");
  const date = selected.month === undefined ? calendar.getMonthAndDayIndex() : selected;
  return dayStart(
    selected.month === undefined ? calendar.year.numericRepresentation : calendar.year.selectedYear,
    date.month ?? 0,
    date.day ?? 0,
  );
}
function install(): void {
  if (notesInstalled || !enabled()) return;
  // SCR's registered launcher returns its existing MainApp without opening or rendering it.
  const menus = (
    game!.settings as unknown as { menus: Map<string, { type: new () => CalendarApp }> }
  ).menus;
  const Launcher = menus?.get(`${SC_NOTES}.calendar-main-app`)?.type;
  if (!Launcher) return;
  app ??= new Launcher();
  const calendar = app.visibleCalendar;
  // Get a native note stub at its anchor using an isolated calendar clone. No world/view state changes.
  for (const journal of documents()) {
    const note = journal.flags[SC_NOTES]?.["noteData"] as CalendarNote | undefined;
    if (!note || note.calendarId !== calendar.id) continue;
    const clone = calendar.clone();
    clone.year.selectedYear = note.startDate.year;
    clone.getMonthAndDayIndex = () => ({ month: note.startDate.month, day: note.startDate.day });
    const stub = clone.toTemplate().selectedDay.notes[0];
    if (!stub) continue;
    const prototype = Object.getPrototypeOf(stub) as NoteStub;
    if (patchedNotes.has(prototype)) return;
    patchedNotes.add(prototype);
    notesInstalled = true;
    const api = (
      globalThis as unknown as {
        SimpleCalendar: { api: { formatTimestamp(time: number, format: string): string } };
      }
    ).SimpleCalendar.api;
    installNoteOccurrences(prototype, context, selectedDay, (time, allDay) =>
      api.formatTimestamp(time, allDay ? "MMMM DD, YYYY" : "MMMM DD, YYYY HH:mm:ss"),
    );
    const sheet = (journal as unknown as { sheet?: RecurrenceSheet }).sheet;
    if (sheet?.updateNoteRepeatDropdown) installSheet(sheet);
    app.render(false);
    return;
  }
}
function addDaily(sheet: RecurrenceSheet): void {
  const linked = context(sheet.object.id);
  const repeat = sheet.journalData.flags[SC_NOTES]?.noteData.repeats;
  if (!linked && repeat !== 4) return;
  const select = sheet.appWindow?.querySelector<HTMLSelectElement>(
    `#scNoteRepeats_${sheet.object.id}`,
  );
  if (!select) return;
  const labels = linked
    ? ["Never", "Weekly", "Monthly", "Yearly", "Daily"]
    : ["", "", "", "", "Daily"];
  labels.forEach((label, index) => {
    if (label && !select.querySelector(`option[value="${index}"]`))
      select.add(new Option(label, String(index)));
  });
  select.value = String(sheet.journalData.flags[SC_NOTES]!.noteData.repeats);
}
function installSheet(sheet: RecurrenceSheet): void {
  const prototype = Object.getPrototypeOf(sheet) as RecurrenceSheet;
  if (!patchedSheets.has(prototype)) {
    patchedSheets.add(prototype);
    const data = prototype.getData,
      dropdown = prototype.updateNoteRepeatDropdown;
    prototype.getData = async function () {
      const result = await data.call(this);
      if (context(this.object.id) || this.journalData.flags[SC_NOTES]?.noteData.repeats === 4) {
        result.edit.repeatOptions["4"] = "Daily";
        if (this.journalData.flags[SC_NOTES]?.noteData.repeats === 4)
          result.display.repeatsDisplay = "Daily";
      }
      return result;
    };
    prototype.updateNoteRepeatDropdown = function () {
      dropdown.call(this);
      addDaily(this);
    };
    sheet.render(false);
  }
  addDaily(sheet);
}
export function registerCalendarRecurrence(): void {
  Hooks.on("simple-calendar-ready", install);
  Hooks.on("ready", install);
  Hooks.on("renderMainApp", install);
  Hooks.on("createJournalEntry", () => queueMicrotask(install));
  Hooks.on("updateJournalEntry", () => queueMicrotask(install));
  Hooks.on("updateJournalEntryPage", (value: unknown) => {
    const page = value as SyncDocument;
    for (const journal of documents()) {
      const link = journal.flags[MODULE_ID]?.["calendarSync"] as SyncLink | undefined;
      if (link?.journal === page.parent?.id && link?.page === page.id) refreshCalendar(journal);
    }
  });
  Hooks.on("renderNoteSheet", (sheet: unknown) => installSheet(sheet as RecurrenceSheet));
}
