import type { ForgeIntegrationService } from "../../../../types/integrations/fa-nexus/ForgeIntegration";

const patchedServices = new WeakSet<ForgeIntegrationService>();

export function repairForgeOwnerDetection(
  service: ForgeIntegrationService,
  getOwnerId: () => unknown,
): boolean {
  if (patchedServices.has(service)) return false;
  const original = service._detectForgeAccountId;
  service._detectForgeAccountId = async function () {
    const ownerId = getOwnerId();
    if (
      this.isRunningOnForge() &&
      typeof ownerId === "string" &&
      /^[a-zA-Z0-9_-]+$/.test(ownerId) &&
      ownerId !== "bazaar"
    ) {
      this.forgeAccountId = ownerId;
      return true;
    }
    return original.call(this);
  };
  patchedServices.add(service);
  return true;
}
