import type { WfrpTidyHookDocument } from "../../../types/wfrp/Folders";
import { MODULE_ID, MODULE_TITLE } from "../../constants";
import { tidyWfrpContentIfEnabled } from "./tidy";

let timer: ReturnType<typeof setTimeout> | undefined;
let running = false;
let pending = false;

export function scheduleWfrpTidy(): void {
  if (!game?.ready || !game.user?.isActiveGM) return;
  if (running) {
    pending = true;
    return;
  }
  clearTimeout(timer);
  timer = setTimeout(() => {
    void runWfrpTidy();
  }, 1000);
}

async function runWfrpTidy(): Promise<void> {
  if (!game?.ready || !game.user?.isActiveGM || running) return;
  running = true;
  pending = false;
  try {
    await tidyWfrpContentIfEnabled();
  } catch (error) {
    console.error(`${MODULE_TITLE}: WFRP folder cleanup failed.`, error);
    ui?.notifications?.error(
      `${MODULE_TITLE}: WFRP cleanup failed and may be incomplete. See the console for details.`,
      { console: false, permanent: true },
    );
  } finally {
    running = false;
    if (pending) scheduleWfrpTidy();
  }
}

export function registerWfrpTidyHooks(): void {
  for (const type of [
    "Folder",
    "Actor",
    "Item",
    "JournalEntry",
    "Scene",
    "RollTable",
    "Macro",
    "Cards",
    "Playlist",
  ]) {
    for (const event of ["create", "update", "delete"])
      Hooks.on(`${event}${type}`, (document) => {
        const changed = document as WfrpTidyHookDocument;
        // Pack contents and embedded actor items are not world sidebar entries.
        if (!changed.pack && !changed.parent) scheduleWfrpTidy();
      });
  }
  Hooks.on("updateSetting", (document) => {
    const setting = document as WfrpTidyHookDocument;
    if (
      setting.key === "core.compendiumConfiguration" ||
      setting.key?.startsWith(`${MODULE_ID}.keepWfrp`)
    )
      scheduleWfrpTidy();
  });
  Hooks.on("updateUser", scheduleWfrpTidy);
  Hooks.on("userConnected", scheduleWfrpTidy);
  Hooks.once("ready", scheduleWfrpTidy);
}
