import { refreshCalendar } from "./event-refresh";
import { calendarMigrationPending } from "./migration/state";
import type {
  CalendarEvent,
  CalendarNote,
  SyncDocument,
  SyncLink,
} from "../../../../types/integrations/calendars/EventSync";
import { MODULE_ID } from "../../../constants";
import { documentId, SC_NOTES, ST_EVENTS } from "../../../functions/calendars/content";
import { eventOwnership, eventToNote, noteToEvent } from "../../../functions/calendars/event-sync";
import { sameSettingValue } from "../../../functions/settings-presets/values";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { usesImperialCalendar } from "../simple-timekeeping/register-integration";
import { contentTargets } from "./content";

const options = () => ({ calendarSync: true });
const linkOf = (doc: SyncDocument) =>
  doc.flags[MODULE_ID]?.["calendarSync"] as SyncLink | undefined;
const noteOf = (doc: SyncDocument) => doc.flags[SC_NOTES]?.["noteData"] as CalendarNote | undefined;
const eventOf = (doc: SyncDocument) => doc.flags[ST_EVENTS] as CalendarEvent | undefined;
const journals = () => [...game!.journal] as unknown as SyncDocument[];
const pageOf = (link: SyncLink) =>
  journals()
    .find((j) => j.id === link.journal)
    ?.pages?.contents.find((p) => p.id === link.page);
const linkedJournal = (page: SyncDocument) =>
  journals().find((j) => {
    const link = linkOf(j);
    return link?.journal === page.parent?.id && link?.page === page.id;
  });

function target(): string | undefined {
  if (
    !game?.ready ||
    calendarMigrationPending() ||
    !game.user?.isActiveGM ||
    !isOptionalFeatureEnabled("simpleCalendar") ||
    !usesImperialCalendar()
  )
    return;
  try {
    return contentTargets({}).calendarId;
  } catch {
    return undefined;
  }
}
async function update(doc: SyncDocument, data: Record<string, unknown>) {
  const source = doc as unknown as Record<string, unknown>;
  const changes = Object.fromEntries(
    Object.entries(data).filter(([key, value]) => {
      const current = key
        .split(".")
        .reduce<unknown>((v, part) => (v as Record<string, unknown> | undefined)?.[part], source);
      return !sameSettingValue(current, value);
    }),
  );
  if (data["ownership"]) {
    for (const key of Object.keys(doc.ownership)) {
      if (!Object.hasOwn(data["ownership"] as object, key)) changes[`ownership.-=${key}`] = null;
    }
  }
  if (Object.keys(changes).length) await doc.update(changes, options());
}
function link(journal: SyncDocument, page: SyncDocument, mirror: boolean): SyncLink {
  return { journal: page.parent?.id ?? journal.id, page: page.id, mirror };
}
function rootFolder(): string {
  const folder = [...game!.folders].find(
    (f) => f.type === "JournalEntry" && (f.flags?.[SC_NOTES] as { root?: boolean })?.root,
  );
  if (!folder) throw new Error("Simple Calendar notes folder is not ready");
  return folder.id;
}
async function fromPage(page: SyncDocument, calendarId: string) {
  const event = eventOf(page);
  const existing = linkedJournal(page);
  if (!Number.isFinite(event?.eventTime)) {
    if (existing && linkOf(existing)?.mirror) await existing.delete(options());
    else if (existing)
      await existing.update(
        { [`flags.${SC_NOTES}.-=noteData`]: null, [`flags.${MODULE_ID}.-=calendarSync`]: null },
        options(),
      );
    return;
  }
  const note = eventToNote(event!, calendarId);
  if (existing) {
    if (noteOf(existing)?.calendarId !== calendarId) return;
    const changes: Record<string, unknown> = {
      name: page.name,
      ownership: eventOwnership(page.parent!.ownership, page.ownership),
      [`flags.${SC_NOTES}.noteData`]: { ...noteOf(existing), ...note },
    };
    if (linkOf(existing)?.mirror) {
      const content = existing.pages?.contents[0];
      if (content && page.text) await update(content, { name: page.name, text: page.text });
    }
    await update(existing, changes);
    return;
  }
  // Existing dual-format imports already represent one event; adopt that identity only.
  const parent = page.parent!;
  if (
    noteOf(parent)?.calendarId === calendarId &&
    !linkOf(parent) &&
    parent.pages?.contents.filter((p) => Number.isFinite(eventOf(p)?.eventTime)).length === 1
  ) {
    await update(parent, {
      [`flags.${MODULE_ID}.calendarSync`]: link(parent, page, false),
      [`flags.${SC_NOTES}.noteData`]: { ...noteOf(parent), ...note },
    });
    return;
  }
  await CONFIG.JournalEntry.documentClass.create(
    {
      _id: documentId(`${MODULE_ID}:event:${parent.id}:${page.id}`),
      name: page.name,
      folder: rootFolder(),
      ownership: { default: 0, ...eventOwnership(parent.ownership, page.ownership) },
      flags: {
        [MODULE_ID]: { calendarSync: link(parent, page, true) },
        [SC_NOTES]: {
          noteData: {
            order: 0,
            categories: [],
            remindUsers: [],
            macro: "none",
            fromPredefined: false,
            ...note,
          },
        },
        core: { sheetClass: `${SC_NOTES}.NoteSheet` },
      },
      pages: [
        {
          name: page.name,
          type: "text",
          text: { content: "", format: 1, ...page.text },
          ownership: { default: -1 },
          flags: {},
        },
      ],
    },
    { ...options(), keepId: true },
  );
}
async function fromNote(journal: SyncDocument, calendarId: string) {
  const note = noteOf(journal);
  if (!note || note.calendarId !== calendarId) return;
  const event = noteToEvent(note);
  const existing = linkOf(journal);
  let page = existing
    ? pageOf(existing)
    : journal.pages?.contents.find(
        (p) => p.type === "text" && !Number.isFinite(eventOf(p)?.eventTime),
      );
  if (existing && !page) return; // A deleted source must not be resurrected by reconciliation.
  if (!page)
    [page] = await journal.createEmbeddedDocuments(
      "JournalEntryPage",
      [{ name: journal.name, type: "text", text: { content: "", format: 1 } }],
      options(),
    );
  if (!page) throw new Error("Could not create calendar event page");
  const changes: Record<string, unknown> = {
    name: journal.name,
    ownership: journal.ownership,
    [`flags.${ST_EVENTS}`]: { notify: "none", ...eventOf(page), ...event },
  };
  if (existing?.mirror) {
    const content = journal.pages?.contents[0];
    if (content?.text) changes["text"] = content.text;
  }
  await update(page, changes);
  if (!existing)
    await update(journal, { [`flags.${MODULE_ID}.calendarSync`]: link(journal, page, false) });
}

let pending = Promise.resolve();
const warned = new Set<string>();
function schedule(work: (id: string) => Promise<void>) {
  pending = pending
    .then(async () => {
      const id = target();
      if (id) await work(id);
    })
    .catch((error) => {
      console.error(`${MODULE_ID} | Calendar event synchronization`, error);
      const message = error instanceof Error ? error.message : String(error);
      if (!warned.has(message)) {
        warned.add(message);
        ui?.notifications?.warn(
          `Calendar event synchronization: ${message}. The event could not be fully synchronized.`,
        );
      }
    });
}
export function reconcileCalendarEvents(): void {
  schedule(async (id) => {
    const originals = journals();
    for (const journal of originals) {
      if (linkOf(journal)?.mirror) continue;
      for (const page of journal.pages?.contents ?? []) {
        if (Number.isFinite(eventOf(page)?.eventTime)) {
          try {
            await fromPage(page, id);
          } catch (error) {
            schedule(async () => {
              throw error;
            });
          }
        }
      }
      if (
        noteOf(journal) &&
        !linkOf(journal) &&
        !journal.pages?.contents.some((p) => Number.isFinite(eventOf(p)?.eventTime))
      ) {
        try {
          await fromNote(journal, id);
        } catch (error) {
          schedule(async () => {
            throw error;
          });
        }
      }
    }
  });
}
export function registerCalendarEventSync(): void {
  const on = (name: string, callback: (...args: unknown[]) => void) => Hooks.on(name, callback);
  on("ready", reconcileCalendarEvents);
  on("simple-calendar-ready", reconcileCalendarEvents);
  on("updateUser", reconcileCalendarEvents);
  on("updateSetting", (value) => {
    const key = (value as { key?: string }).key ?? "";
    if ([SC_NOTES, ST_EVENTS, MODULE_ID].some((namespace) => key.startsWith(namespace + ".")))
      reconcileCalendarEvents();
  });
  for (const action of ["create", "update"]) {
    on(`${action}JournalEntry`, (...args) => {
      const doc = args[0] as SyncDocument;
      refreshCalendar(doc);
      const opts = args[action === "create" ? 1 : 2] as Record<string, unknown>;
      if (opts?.["calendarSync"]) return;
      schedule(async (id) => {
        const events =
          doc.pages?.contents.filter((p) => Number.isFinite(eventOf(p)?.eventTime)) ?? [];
        if (action === "create" && events.length) {
          for (const page of events) await fromPage(page, id);
        } else if (noteOf(doc)) await fromNote(doc, id);
        else for (const page of doc.pages?.contents ?? []) await fromPage(page, id);
      });
    });
    on(`${action}JournalEntryPage`, (...args) => {
      const page = args[0] as SyncDocument;
      const opts = args[action === "create" ? 1 : 2] as Record<string, unknown>;
      if (opts?.["calendarSync"]) return;
      schedule(async (id) => {
        if (linkOf(page.parent!)?.mirror) await fromNote(page.parent!, id);
        else await fromPage(page, id);
      });
    });
  }
  on("deleteJournalEntryPage", (value, opts) => {
    if ((opts as Record<string, unknown>)?.["calendarSync"]) return;
    const page = value as SyncDocument;
    schedule(async () => {
      const journal = linkedJournal(page);
      if (journal && linkOf(journal)?.mirror) await journal.delete(options());
      else if (journal)
        await journal.update(
          { [`flags.${SC_NOTES}.-=noteData`]: null, [`flags.${MODULE_ID}.-=calendarSync`]: null },
          options(),
        );
    });
  });
  on("deleteJournalEntry", (value, opts) => {
    refreshCalendar(value as SyncDocument);
    if ((opts as Record<string, unknown>)?.["calendarSync"]) return;
    const doc = value as SyncDocument;
    schedule(async () => {
      const own = linkOf(doc);
      if (own?.mirror) await pageOf(own)?.delete(options());
      for (const journal of journals()) {
        const linked = linkOf(journal);
        if (linked?.mirror && linked.journal === doc.id) await journal.delete(options());
      }
    });
  });
}

export async function waitForCalendarEventSync(): Promise<void> {
  let current;
  do {
    current = pending;
    await current;
  } while (current !== pending);
}
