/** WFRP 10.0.0 restored native migration returns; unknown older releases need inspection. */
export function migrationReturnSupport(version: string): "affected" | "fixed" | "unknown" {
  if (["9.6.1", "9.6.2", "9.6.3", "9.6.4"].includes(version)) return "affected";
  const match = /^(\d+)\.\d+\.\d+$/.exec(version);
  return match && Number(match[1]) >= 10 ? "fixed" : "unknown";
}
