import type {
  SettingsInspection,
  SettingsResult,
} from "../../../../types/settings-presets/Protocol";

export function escapePresetHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}
export function inspectionMarkup(result: SettingsInspection): string {
  const escape = escapePresetHtml;
  const changes = result.changes
    .map(
      ({ label, current, value }) =>
        `<li><strong>${escape(label)}</strong><br>Current: <code>${escape(JSON.stringify(current))}</code><br>Preset: <code>${escape(JSON.stringify(value))}</code></li>`,
    )
    .join("");
  const issues = [...result.skipped, ...result.failed, ...result.conflicts]
    .map(({ id, reason }) => `<li>${escape(id)}: ${escape(reason)}</li>`)
    .join("");
  return `<p>${result.changes.length} changes; ${result.unchanged.length} already set; ${result.excluded.length} left to the GM's current settings.</p><div class="scrollable" style="max-height:45vh"><details><summary>Review setting changes</summary><ul>${changes}</ul></details>${issues ? `<p>Resolve these issues before applying:</p><ul>${issues}</ul>` : ""}${result.missingTables.length ? `<p>Import these missing rule tables first: ${escape(result.missingTables.join(", "))}</p>` : ""}</div>${result.requiresReload ? "<p>A reload is required for these changes.</p>" : ""}`;
}
export async function reportSettingsResult(title: string, result: SettingsResult): Promise<void> {
  let message = `${title}: ${result.updated.length} updated, ${result.unchanged.length} already set, ${result.excluded.length} left unchanged by conflict choices.`;
  if (result.blocked) message += " Nothing was applied because preflight found unresolved issues.";
  const issues = [...result.skipped, ...result.failed, ...result.conflicts];
  if (issues.length)
    message += ` ${issues.map(({ id, reason }) => `${id}: ${reason}`).join("; ")}.`;
  if (result.missingTables.length)
    message += ` Missing rule tables: ${result.missingTables.join(", ")}.`;
  if (result.failed.length && result.updated.length)
    message += " Earlier successful changes remain applied; review before retrying.";
  if (result.blocked || result.failed.length)
    ui?.notifications?.error(escapePresetHtml(message), { permanent: true });
  else ui?.notifications?.info(escapePresetHtml(message));
  if (result.requiresReload && !result.automaticReload)
    await foundry.applications.settings.SettingsConfig.reloadConfirm({ world: true });
}
