import { MODULE_ID } from "../../../constants";
import { isModuleActive } from "../is-module-active";
import { showCombatBosses } from "./combat";
import { reportBossBarError } from "./configuration";
import { BOSS_BAR_MODULE_ID, BOSS_BAR_SETTINGS } from "./constants";
import { queueBossBarRefresh, refreshBossBarDisplay } from "./display";
import { getBossBarApplication, type BossBarApplication, type BossCombat } from "./runtime";
import { injectBossBarSetupButton, registerBossBarSettings } from "./settings";

export function registerBossBarIntegration(): void {
  if (game?.system.id !== "wfrp4e" || !isModuleActive(BOSS_BAR_MODULE_ID)) return;

  registerBossBarSettings();
  // Foundry fires combatStart only on the client calling startCombat, before round 1 is saved.
  Hooks.on(
    "combatStart",
    (combat) => void showCombatBosses(combat as BossCombat).catch(reportBossBarError),
  );
  Hooks.on("renderBossBar", (application) =>
    refreshBossBarDisplay(application as BossBarApplication),
  );
  Hooks.on("renderSettingsConfig", (_application, html) => {
    if (html instanceof HTMLElement) injectBossBarSetupButton(html);
  });
  for (const hook of [
    "updateActor",
    "createItem",
    "updateItem",
    "deleteItem",
    "createActiveEffect",
    "updateActiveEffect",
    "deleteActiveEffect",
  ]) {
    Hooks.on(hook, queueBossBarRefresh);
  }
  Hooks.on("updateSetting", (setting) => {
    const key = (setting as { key: string }).key;
    if (
      ["bossbar.currentHpPath", "bossbar.maxHpPath", "bossbar.woundsSystem"].includes(key) &&
      game?.settings.get(MODULE_ID, BOSS_BAR_SETTINGS.stacked) === true
    ) {
      void getBossBarApplication()?.render(true).catch(reportBossBarError);
    }
    if (
      key.startsWith("bossbar.") ||
      key.startsWith("wfrp4e-compatibility-box.bossBar") ||
      key === "wfrp4e.uiaCrits"
    ) {
      queueBossBarRefresh();
    }
  });
}
