import { isModuleActive } from "../is-module-active";
import { recordStartupFix } from "../../diagnostics/startup-report";

interface ImageContextHandler {
  onContextMenu(event: MouseEvent): unknown;
}

// Image Context 4.0.0 exposes a classic-script global, not a module API or window property.
declare const ImageContext: ImageContextHandler | undefined;

const patched = new WeakSet<ImageContextHandler>();
const conditionSelector = [
  "#token-hud .status-effects .effect-control[data-status-id]",
  "#token-hud .condition-effects .effect-control[data-status-id]",
].join(", ");

export function registerImageContextIntegration(): void {
  if (!isModuleActive("image-context")) {
    recordStartupFix("imageContext", "inactive", "Image Context is not active.");
    return;
  }
  if (game?.system.id !== "wfrp4e") {
    recordStartupFix("imageContext", "inactive", "Requires a WFRP4e world.");
    return;
  }
  if (typeof ImageContext === "undefined" || typeof ImageContext.onContextMenu !== "function") {
    recordStartupFix(
      "imageContext",
      "unavailable",
      "Image Context is active but its context-menu API is unavailable at init.",
    );
    return;
  }
  if (patched.has(ImageContext)) {
    recordStartupFix(
      "imageContext",
      "applied",
      "The token HUD condition exclusion is already installed.",
    );
    return;
  }

  const original = ImageContext.onContextMenu;
  ImageContext.onContextMenu = function (event) {
    // Exclude only HUD conditions. Let WFRP handle the original event and its stack/overlay rules.
    if (event.target instanceof Element && event.target.closest(conditionSelector)) return;
    return original.call(this, event);
  };
  patched.add(ImageContext);
  recordStartupFix(
    "imageContext",
    "applied",
    "Image menus are excluded only from WFRP token HUD condition controls.",
  );
}
