const SEGMENT_CLASS = "wfrp-bossbar-segments";
const SVG_NAMESPACE = "http://www.w3.org/2000/svg";
const LAYERS = ["background", "bar", "foreground"] as const;
const ASSETS = ["bg", "bar", "fg"] as const;

export function updateCriticalSegments(primary: HTMLElement, max?: number): void {
  const layers = LAYERS.map((layer) =>
    primary.querySelector<HTMLElement>(`:scope > .bar-${layer}`),
  );
  const images = layers.map((layer) => layer?.querySelector<HTMLImageElement>(":scope > img"));
  // Only adapt Boss Bar's built-in segmented artwork, including themes copied from it.
  const supported = images.every((image, index) =>
    image
      ?.getAttribute("src")
      ?.split(/[?#]/)[0]
      ?.endsWith(`/bossbar/resources/matching-images/segmented/${ASSETS[index]}.png`),
  );
  const count = max !== undefined && supported ? String(max) : undefined;
  if (primary.dataset["wfrpBossbarSegments"] === count) return;

  primary.querySelectorAll(`.${SEGMENT_CLASS}`).forEach((element) => element.remove());
  primary.classList.toggle("wfrp-bossbar-segmented", count !== undefined);
  const row = primary.closest<HTMLElement>(".bar-list-item");
  row?.classList.toggle("wfrp-bossbar-segmented-row", count !== undefined);
  if (count === undefined) {
    row?.style.removeProperty("--wfrp-bossbar-segment-count");
    delete primary.dataset["wfrpBossbarSegments"];
    return;
  }
  row?.style.setProperty("--wfrp-bossbar-segment-count", count);
  primary.dataset["wfrpBossbarSegments"] = count;
  for (const [index, layer] of layers.entries()) {
    const image = images[index];
    if (!layer || !image) continue;
    const grid = primary.ownerDocument.createElement("div");
    grid.className = SEGMENT_CLASS;
    grid.setAttribute("aria-hidden", "true");
    grid.style.gridTemplateColumns = count === "0" ? "none" : `repeat(${count}, minmax(0, 1fr))`;
    for (let segment = 0; segment < Number(count); segment++) {
      grid.append(createSegment(primary.ownerDocument, image.src));
    }
    layer.append(grid);
  }
}

function createSegment(document: Document, source: string): SVGSVGElement {
  const segment = document.createElementNS(SVG_NAMESPACE, "svg");
  // Boss Bar 5.0.1's 7967 × 361 sprite has ten cells. Crop one interior cell,
  // from divider centre to divider centre, so adjacent cells share a full divider.
  segment.setAttribute("viewBox", "829 0 787 361");
  segment.setAttribute("preserveAspectRatio", "xMidYMid meet");
  const image = document.createElementNS(SVG_NAMESPACE, "image");
  image.setAttribute("href", source);
  image.setAttribute("width", "7967");
  image.setAttribute("height", "361");
  segment.append(image);
  return segment;
}
