import type { SettingsPreset } from "../../../../types/settings-presets/SettingsPreset";
import { MODULE_ID } from "../../../constants";
import { notifyError } from "../../notifications/notify-user";
import { reviewPreferences } from "../preset-runtime/review";
import { escapePresetHtml } from "../preset-runtime/presentation";
import { inspectSettingsPreset, isPresetEnabled, presetEntries } from "./engine";
import { reviewCalendarMigration } from "../../integrations/imperial-calendar/migration/menu";
import { SC_NOTES, ST_EVENTS } from "../../../functions/calendars/content";
const isCalendar = (preset: SettingsPreset) => [SC_NOTES, ST_EVENTS].includes(preset.namespace);
let calendarPrompted = false;
export function presetTitle(preset: SettingsPreset): string {
  return preset.title ?? game?.modules.get(preset.namespace)?.title ?? preset.namespace;
}
export function presetIgnoreSetting(preset: SettingsPreset): string {
  return preset.ignoreSetting ?? `ignoreSettingsPreset-${preset.namespace}`;
}
export function reportPresetError(error: unknown): void {
  notifyError(
    escapePresetHtml(
      `Settings preset could not be completed: ${error instanceof Error ? error.message : String(error)}`,
    ),
    error,
  );
}
export async function applyAndReportSettingsPreset(preset: SettingsPreset): Promise<void> {
  if (!isPresetEnabled(preset)) throw new Error("Preset is not active.");
  if (isCalendar(preset)) return reviewCalendarMigration();
  await reviewPreferences({
    owner: MODULE_ID,
    title: presetTitle(preset),
    entries: () => presetEntries(preset),
    ...(preset.description ? { description: preset.description } : {}),
  });
}
export async function promptSettingsPreset(
  preset: SettingsPreset,
  dependencyChanged = false,
): Promise<void> {
  if (
    !isPresetEnabled(preset) ||
    game?.system.id !== "wfrp4e" ||
    (preset.promptOnStartup === false && !dependencyChanged)
  )
    return;
  if (isCalendar(preset)) {
    if (
      calendarPrompted ||
      !game?.user?.isGM ||
      (game.users?.activeGM && game.users.activeGM.id !== game.user.id) ||
      game.settings.get(MODULE_ID, presetIgnoreSetting(preset)) === true ||
      !inspectSettingsPreset(preset).changes.length
    )
      return;
    calendarPrompted = true;
    const action = await foundry.applications.api.DialogV2.wait({
      window: { title: "WFRP Calendar Setup" },
      content:
        "<p>Your calendars differ from the shared Imperial calendar. Review a migration to choose what happens to world time and existing events.</p>",
      buttons: [
        { action: "review", label: "Review Migration" },
        { action: "ignore", label: "Keep My Calendars" },
        { action: "close", label: "Later" },
      ],
      rejectClose: false,
    });
    if (action === "review") await reviewCalendarMigration();
    if (action === "ignore")
      for (const namespace of [SC_NOTES, ST_EVENTS]) {
        const key = presetIgnoreSetting({ ...preset, namespace });
        if (game.settings.settings?.has(`${MODULE_ID}.${key}`))
          await game.settings.set(MODULE_ID, key, true);
      }
    return;
  }
  await reviewPreferences({
    owner: MODULE_ID,
    title: presetTitle(preset),
    entries: () => presetEntries(preset),
    startup: true,
    ignoreKey: presetIgnoreSetting(preset),
    ...(preset.description ? { description: preset.description } : {}),
  });
}
