import type {
  PresetExtension,
  SettingRegistration,
} from "../../../../types/settings-presets/SettingsPreset";
import { configureWfrpEstimations } from "../../../functions/integrations/health-estimate/estimations";
import { isOptionalFeatureEnabled } from "../../settings/is-optional-feature-enabled";
import { settingValueToSource } from "../../settings/preset-runtime/values";

export const HEALTH_ESTIMATE_MODULE_ID = "healthEstimate";
const ESTIMATIONS = "core.estimations";
export const HEALTH_ESTIMATE_PRESET_EXTENSION: PresetExtension = {
  title: "Health Estimate",
  watchSettings: ["wfrp4e.uiaCrits"],
  enabled: () => {
    const version = game?.modules.get(HEALTH_ESTIMATE_MODULE_ID)?.version;
    return (
      isOptionalFeatureEnabled("healthEstimate") &&
      game?.system.id === "wfrp4e" &&
      !!version &&
      !foundry.utils.isNewerVersion("36.1.0", version)
    );
  },
  additionalSettings: () => {
    const registration = game?.settings.settings?.get(
      `${HEALTH_ESTIMATE_MODULE_ID}.${ESTIMATIONS}`,
    ) as SettingRegistration | undefined;
    if (!registration)
      throw new Error(
        "Health Estimate's estimation setting is unavailable. Version 36.1.0 or newer is required.",
      );
    const tables = settingValueToSource(
      registration,
      game?.settings.get(HEALTH_ESTIMATE_MODULE_ID, ESTIMATIONS),
    );
    const upInArms = game?.settings.get("wfrp4e", "uiaCrits") === true;
    return [
      ...(upInArms
        ? [{ namespace: HEALTH_ESTIMATE_MODULE_ID, key: "core.NPCsJustDie", value: false }]
        : []),
      {
        namespace: HEALTH_ESTIMATE_MODULE_ID,
        key: ESTIMATIONS,
        value: configureWfrpEstimations(tables, upInArms),
      },
    ];
  },
};
