import { registerGroupedAction } from "../settings/groups/registry";
import { getStartupReport, publishStartupReport, resetStartupReport } from "./startup-report";

const STATUS_LABELS = {
  "applied": "Applied",
  "not-needed": "Not needed",
  "inactive": "Inactive",
  "unsupported": "Unsupported version",
  "unavailable": "Unavailable API",
  "failed": "Failed",
  "pending": "Pending",
} as const;

export async function showStartupReport(): Promise<void> {
  if (!game?.ready || !game.user?.isGM) {
    ui?.notifications?.warn("Only a GM in a loaded world can open the startup fix report.");
    return;
  }
  const report = getStartupReport();
  const escape = foundry.utils.escapeHTML;
  const rows = report.fixes
    .map(
      (fix) =>
        `<tr><td>${escape(fix.label)}<br><small>${escape(fix.packageId)} ${escape(fix.version)}</small></td><td>${STATUS_LABELS[fix.status]}</td><td>${escape(fix.detail)}</td></tr>`,
    )
    .join("");
  await foundry.applications.api.DialogV2.wait({
    window: { title: "Compatibility Box — Startup Fix Report" },
    position: { width: 850 },
    content: `<p>Foundry ${escape(report.foundryVersion)} · ${escape(report.systemId)} ${escape(report.systemVersion)}</p><p>Applied means the patch or guard was installed on this client. It does not mean an affected document was found or repaired. This report covers automatic bug fixes, including Argon's legacy check; optional feature switches and preset choices are separate.</p><div class="scrollable" style="max-height:55vh"><table><thead><tr><th>Fix / package</th><th>Status</th><th>Reason</th></tr></thead><tbody>${rows}</tbody></table></div>`,
    buttons: [{ action: "close", label: "Close", default: true }],
    rejectClose: false,
  });
}

export function registerStartupDiagnostics(): void {
  resetStartupReport();
  Hooks.once("setup", () => {
    registerGroupedAction("world", "startupFixReport", {
      name: "Startup compatibility fixes",
      label: "Startup Fix Report",
      hint: "Review applied fixes, upstream corrections, unsupported versions, and missing APIs on this client.",
      icon: "fa-solid fa-clipboard-check",
      restricted: true,
      type: class extends foundry.applications.api.ApplicationV2 {
        override async render(): Promise<this> {
          await showStartupReport();
          return this;
        }
      },
    });
  });
  Hooks.once("ready", publishStartupReport);
}
