import type {
  MigrationPlan,
  MigrationRecovery,
} from "../../../../../types/integrations/calendars/Migration";
import { MODULE_ID } from "../../../../constants";
import { planCalendarMigration } from "../../../../functions/calendars/migration";
import { sameSettingValue } from "../../../../functions/settings-presets/values";
import { captureCalendarMigration, migrationJournals, requireMigrationGM } from "./snapshot";
import {
  calendarMigrationPending,
  calendarMigrationRecovery,
  calendarMigrationReference,
  MIGRATION_SETTING,
} from "./state";
import { waitForCalendarEventSync } from "../event-sync";
import { restoreMigrationLinks } from "./restore";

let busy = false;
async function save(recovery: MigrationRecovery, journal = calendarMigrationReference()?.journal) {
  if (!journal) throw new Error("The recovery journal is missing.");
  await game!.settings.set(MODULE_ID, MIGRATION_SETTING, {
    status: recovery.status,
    created: recovery.created,
    journal,
  });
}
async function writePlan(plan: MigrationPlan, restore: boolean): Promise<void> {
  for (const write of plan.writes) {
    requireMigrationGM();
    const journal = migrationJournals().find((j) => j.id === write.journal);
    const doc = write.page ? journal?.pages?.contents.find((p) => p.id === write.page) : journal;
    if (!doc) throw new Error(`Calendar document ${write.journal}/${write.page ?? ""} is missing.`);
    const value = restore ? write.before : write.after;
    const previous = restore ? write.after : write.before;
    const changes: Record<string, unknown> = { [write.key]: value };
    for (const key of Object.keys(previous))
      if (!(key in value)) changes[`${write.key}.-=${key}`] = null;
    await doc.update(changes, { calendarSync: true });
  }
  for (const s of restore ? plan.snapshot.settings : plan.settings) {
    requireMigrationGM();
    await game!.settings.set(s.namespace, s.key, s.value);
  }
  const time = restore ? plan.snapshot.time : plan.time;
  if (time !== game!.time.worldTime)
    await (game!.time as unknown as { set(time: number, options: object): Promise<unknown> }).set(
      time,
      { calendarMigration: true },
    );
}
export async function applyCalendarMigration(plan: MigrationPlan): Promise<void> {
  requireMigrationGM();
  if (busy || calendarMigrationPending())
    throw new Error("A calendar migration needs recovery before another can begin.");
  if (plan.errors.length) throw new Error("Resolve the migration preview errors first.");
  const current = captureCalendarMigration();
  if (
    !sameSettingValue(current, plan.snapshot) ||
    !sameSettingValue(planCalendarMigration(current, plan.choices), plan)
  )
    throw new Error("Calendar data or time changed during review. Preview again before applying.");
  busy = true;
  const previous = calendarMigrationReference();
  const recovery: MigrationRecovery = {
    status: "applying",
    created: new Date().toISOString(),
    plan,
  };
  let journal: string | undefined;
  let started = false;
  try {
    const backup = await CONFIG.JournalEntry.documentClass.create(
      {
        name: `Calendar migration recovery — ${recovery.created}`,
        folder: null,
        ownership: { default: 0 },
        flags: { [MODULE_ID]: { calendarMigrationPlan: plan } },
        pages: [],
      },
      { calendarSync: true },
    );
    if (!backup) throw new Error("Could not create the GM recovery journal.");
    journal = backup.id;
    await save(recovery, journal);
    await waitForCalendarEventSync();
    const latest = captureCalendarMigration();
    latest.journalIds = latest.journalIds.filter((id) => id !== journal);
    if (!sameSettingValue(latest, plan.snapshot))
      throw new Error("Calendar data changed while pausing synchronization. Preview again.");
    if (calendarMigrationReference()?.journal !== journal)
      throw new Error("Another GM started a calendar migration. Reopen the migration menu.");
    started = true;
    await writePlan(plan, false);
    await save({ ...recovery, status: "complete" });
  } catch (error) {
    if (!started) {
      if (journal && calendarMigrationReference()?.journal === journal)
        await game!.settings.set(MODULE_ID, MIGRATION_SETTING, previous);
      throw error;
    }
    if (journal) await save({ ...recovery, status: "failed" }, journal);
    throw new Error(
      `Migration stopped: ${error instanceof Error ? error.message : error}. Event synchronization is paused. Use Restore Previous Calendar in the migration menu, then reload.`,
      { cause: error },
    );
  } finally {
    busy = false;
  }
}
export async function restoreCalendarMigration(): Promise<void> {
  requireMigrationGM();
  const recovery = calendarMigrationRecovery();
  if (!recovery || recovery.status === "restored")
    throw new Error("No migration is available to restore.");
  if (busy) throw new Error("A migration is already running.");
  busy = true;
  try {
    await save({ ...recovery, status: "applying" });
    await waitForCalendarEventSync();
    await writePlan(recovery.plan, true);
    await restoreMigrationLinks(recovery.plan);
    await save({ ...recovery, status: "restored" });
  } catch (error) {
    await save({ ...recovery, status: "failed" });
    throw error;
  } finally {
    busy = false;
  }
}
