import { sameSettingValue } from "../settings-presets/values";
import { imperialDate, IMPERIAL_MONTHS, IMPERIAL_WEEKDAYS, timekeepingCalendar } from "./imperial";
import type { SettingValue } from "../../../types/settings-presets/SettingsPreset";

type JsonObject = { [key: string]: SettingValue };
export function calendarObject(value: unknown): JsonObject {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("Calendar configuration is unavailable or invalid.");
  return structuredClone(value) as JsonObject;
}

/** ST&C 3 stores named custom calendars separately from the selected calendar ID. */
export function configureTimekeeping(value: unknown, registryValue: unknown) {
  const configuration = calendarObject(value);
  const registry = calendarObject(registryValue);
  const definition = timekeepingCalendar();
  const existing = registry[definition.id];
  const previous = existing ? calendarObject(existing) : {};
  const calendar = { ...previous, ...definition };
  // Preserve editor-managed moon/biome data and month daylight preferences.
  const previousMonths = (previous["months"] as JsonObject | undefined)?.["values"];
  if (Array.isArray(previousMonths)) {
    calendar.months.values = definition.months.values.map((month) => ({
      ...(previousMonths.find(
        (v) => v && typeof v === "object" && !Array.isArray(v) && v["name"] === month.name,
      ) as JsonObject | undefined),
      ...month,
    }));
  }
  return {
    configuration: { ...configuration, calendar: definition.id },
    customCalendars: { ...registry, [definition.id]: calendar },
  };
}

/** Replace only the active definition, retaining its identity, notes and other calendars. */
export function configureSimpleCalendar(
  value: unknown,
  activeId: unknown,
  timestamp: number,
  paired: boolean,
): SettingValue[] {
  if (!Array.isArray(value)) throw new Error("Simple Calendar configuration is unavailable.");
  if (!value.some((c) => c?.id === activeId))
    throw new Error("Choose an active Simple Calendar before applying the Imperial preset.");
  return value.map((raw) => {
    const current = calendarObject(raw);
    if (current["id"] !== activeId) return current;
    const existingMonths = Array.isArray(current["months"]) ? current["months"] : [];
    const matching = (entries: SettingValue[], name: string): JsonObject =>
      (entries.find(
        (v) => v && typeof v === "object" && !Array.isArray(v) && v["name"] === name,
      ) as JsonObject) ?? {};
    const months = IMPERIAL_MONTHS.map((m, i) => {
      const previous = matching(existingMonths, m.name);
      return {
        ...previous,
        ...m,
        id: previous["id"] ?? `wfrp-month-${i}`,
        description: previous["description"] ?? "",
        numericRepresentationOffset: 0,
        numberOfLeapYearDays: m.numberOfDays,
        intercalaryInclude: false,
        startingWeekday: null,
      };
    });
    const existingWeekdays = Array.isArray(current["weekdays"]) ? current["weekdays"] : [];
    const weekdays = IMPERIAL_WEEKDAYS.map((d, i) => {
      const previous = matching(existingWeekdays, d.name);
      return {
        ...previous,
        ...d,
        id: previous["id"] ?? `wfrp-weekday-${i}`,
        numericRepresentation: i + 1,
      };
    });
    const year = { ...calendarObject(current["year"]), yearZero: 1, firstWeekday: 0 };
    const leapYear = {
      ...calendarObject(current["leapYear"]),
      rule: "none",
      customMod: 0,
      startingYear: 0,
    };
    const time = {
      ...calendarObject(current["time"]),
      hoursInDay: 24,
      minutesInHour: 60,
      secondsInMinute: 60,
      ...(paired ? { gameTimeRatio: 0 } : {}),
    };
    const general = {
      ...calendarObject(current["general"]),
      gameWorldTimeIntegration: paired ? "third-party" : "mixed",
    };
    const result: JsonObject = {
      ...current,
      name: "WFRP Imperial Calendar",
      months,
      weekdays,
      year,
      leapYear,
      time,
      general,
    };
    // Only a changed definition needs a new date projection. Ordinary preset inspection must not
    // perpetually chase a running clock or rewind a calendar on subsequent applications.
    if (!sameSettingValue(result, current)) {
      const date = imperialDate(timestamp);
      result["currentDate"] = {
        year: date.year,
        month: date.month,
        day: date.day,
        seconds: ((timestamp % 86400) + 86400) % 86400,
      };
    }
    return result;
  });
}
