import { clearGroupedActions, registerGroupedAction } from "../groups/registry";
import { exportSettings } from "../preset-runtime/export";
import { registerPresetConflicts } from "../conflicts/register";
import { MODULE_ID } from "../../../constants";
import { getSettingsPresets } from "./definitions";
import { isPresetEnabled } from "./engine";
import {
  applyAndReportSettingsPreset,
  presetIgnoreSetting,
  presetTitle,
  promptSettingsPreset,
  reportPresetError,
} from "./interface";

/** Native action menus are generated for each bundled JSON namespace. */
export function registerSettingsPresets(): void {
  clearGroupedActions("presets");
  registerPresetConflicts();
  const presets = getSettingsPresets().filter(isPresetEnabled);

  Hooks.once("setup", () => {
    registerGroupedAction("presets", "exportSettingsPreset", {
      name: "Settings presets",
      label: "Export Settings Preset",
      hint: "Choose exact world settings to download as namespace JSON.",
      icon: "fa-solid fa-file-export",
      restricted: true,
      type: class extends foundry.applications.api.ApplicationV2 {
        override async render(): Promise<this> {
          try {
            await exportSettings();
          } catch (error) {
            reportPresetError(error);
          }
          return this;
        }
      },
    });
    for (const preset of presets) {
      const title = presetTitle(preset);
      game?.settings.register(MODULE_ID, presetIgnoreSetting(preset), {
        name: `Ignore ${title} setup prompts`,
        hint: `Do not prompt when ${title} settings differ from the included preset. Uncheck to resume startup checks for all GMs in this world.`,
        config: false,
        default: preset.defaultIgnorePrompt?.() ?? false,
        scope: "world",
        type: Boolean,
      });
      if (["foundryvtt-simple-calendar-reborn", "simple-timekeeping"].includes(preset.namespace))
        continue;
      registerGroupedAction(
        "presets",
        preset.menuKey ?? `configureSettingsPreset-${preset.namespace}`,
        {
          name: `${title} settings preset`,
          settingKey: presetIgnoreSetting(preset),
          label: `Apply ${title} Preset`,
          hint: `Apply only the settings included in Compatibility Box's ${title} preset.`,
          icon: "fa-solid fa-gears",
          restricted: true,
          type: class extends foundry.applications.api.ApplicationV2 {
            override async render(): Promise<this> {
              try {
                await applyAndReportSettingsPreset(preset);
              } catch (error) {
                reportPresetError(error);
              }
              return this;
            }
          },
        },
      );
    }
  });
  Hooks.on("updateSetting", (setting) => {
    const key = (setting as { key: string }).key;
    for (const preset of presets.filter((preset) => preset.watchSettings?.includes(key)))
      void promptSettingsPreset(preset, true).catch(reportPresetError);
  });
  Hooks.once("ready", async () => {
    for (const preset of presets) {
      try {
        await promptSettingsPreset(preset);
      } catch (error) {
        reportPresetError(error);
      }
    }
  });
}
