import type { ChatActorReference, ChatCardSource } from "../../../../types/patches/wfrp4e/ChatCard";

function record(value: unknown): Record<string, unknown> {
  return typeof value === "object" && value !== null ? (value as Record<string, unknown>) : {};
}

function string(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function speakerReference(value: unknown): ChatActorReference {
  const speaker = record(value);
  return {
    kind: "speaker",
    actor: string(speaker["actor"]),
    scene: string(speaker["scene"]),
    token: string(speaker["token"]),
  };
}

function testReference(value: unknown): ChatActorReference {
  return speakerReference(record(record(value)["context"])["speaker"]);
}

// Read stored references only: a test getter can reconstruct a roll and throw before rendering.
export function getChatCardActorReferences(source: ChatCardSource): ChatActorReference[] {
  const system = source.system ?? {};
  switch (source.type) {
    case "test":
      return [testReference(system["testData"])];
    case "opposed": {
      const opposed = record(system["opposedTestData"]);
      return [
        testReference(opposed["attackerTestData"]),
        testReference(opposed["defenderTestData"]),
      ];
    }
    case "magic": {
      const sourceData = record(system["sourceData"]);
      const references: ChatActorReference[] = [
        { kind: "uuid", uuid: string(sourceData["actor"]) },
      ];
      if (sourceData["test"]) {
        // Magic cards support a missing casting message, but a surviving broken test getter
        // still throws when Ratter reads the magic card's source test.
        references.push({ kind: "message", id: string(sourceData["test"]), required: false });
      }
      return references;
    }
    case "handler": {
      const opposed = record(system["opposedData"]);
      const references: ChatActorReference[] = [
        { kind: "message", id: string(opposed["attackerMessageId"]), required: true },
      ];
      // A manual opposed test may be waiting for a defender and have no target yet.
      if (opposed["targetSpeakerData"]) {
        references.push(speakerReference(opposed["targetSpeakerData"]));
      }
      if (opposed["defenderMessageId"]) {
        references.push({
          kind: "message",
          id: string(opposed["defenderMessageId"]),
          required: true,
        });
      }
      return references;
    }
    default:
      return [];
  }
}
