import type { FoundryGame } from "../../../../types/foundry";
import type { WfrpDocumentSource } from "../../../../types/patches/wfrp4e/JournalLinks";
import { isOfficialWfrpModule, officialSource } from "../../../functions/wfrp/folders";

export function officialCompendiums(currentGame: FoundryGame, type: string) {
  return [...currentGame.packs.entries()]
    .flatMap(([key, pack]) => {
      const packageId = pack.metadata?.packageName;
      if (pack.documentName !== type || !pack.visible || !packageId) return [];
      const module = currentGame.modules.get(packageId);
      const official =
        packageId === "wfrp4e" ||
        (module?.active && isOfficialWfrpModule(packageId, module.authors ?? []));
      return official ? [{ key, pack, packageId }] : [];
    })
    .sort((a, b) => a.key.localeCompare(b.key));
}

export function compendiumsByDocumentId(
  currentGame: FoundryGame,
  type: string,
  id: string,
  source: WfrpDocumentSource | null | undefined,
) {
  const candidates = officialCompendiums(currentGame, type).filter(({ pack }) =>
    pack.index.has(id),
  );
  const sourcePackage =
    source?.pack?.split(".")[0] ??
    officialSource(
      source?.flags ?? {},
      source?._stats?.compendiumSource,
      new Set(candidates.map(({ packageId }) => packageId)),
    );
  return candidates.sort(
    (a, b) => Number(b.packageId === sourcePackage) - Number(a.packageId === sourcePackage),
  );
}
