import type {
  BossBarConfiguration,
  BossBarHealth,
} from "../../../../types/integrations/bossbar/BossBar";

export const WFRP_BOSS_BAR_CONFIGURATION: BossBarConfiguration = {
  currentHpPath: "status.wounds.value",
  maxHpPath: "status.wounds.max",
  woundsSystem: false,
};

export function matchesWfrpConfiguration(configuration: BossBarConfiguration): boolean {
  return Object.entries(WFRP_BOSS_BAR_CONFIGURATION).every(
    ([key, value]) => configuration[key as keyof BossBarConfiguration] === value,
  );
}

export function healthPercent(value: number, max: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) return 0;
  return Math.min(100, Math.max(0, (100 * value) / max));
}

export function criticalCapacity(health: BossBarHealth): { remaining: number; max: number } {
  const max = Number.isFinite(health.maxCriticals)
    ? Math.max(0, Math.floor(health.maxCriticals))
    : 0;
  return { max, remaining: Math.max(0, max - Math.max(0, health.criticals)) };
}

// Match WFRP's nonTrivialCriticals sheet filter, including numeric strings and excluding "-".
export function countsAsCritical(wounds: unknown): boolean {
  return (
    (typeof wounds === "number" || (typeof wounds === "string" && wounds.trim() !== "")) &&
    Number.isFinite(Number(wounds))
  );
}
