import type { FoundryFolder } from "../../../types/folders";

export interface ImportedContentEntry {
  id: string;
  folderId: string | null;
  imported: boolean;
}

/** Keep whole branches where possible and move individual imports out of mixed folders. */
export function planImportedContentFolders(
  folders: FoundryFolder[],
  entries: ImportedContentEntry[],
  rootId: string | undefined,
  maxDepth: number,
) {
  const byId = new Map(folders.map((folder) => [folder.id, folder]));
  const paths = new Map<string, FoundryFolder[]>();
  const visiting = new Set<string>();
  function ancestry(id: string | null): FoundryFolder[] {
    if (id === null) return [];
    const cached = paths.get(id);
    if (cached) return cached;
    const folder = byId.get(id);
    if (!folder) return [];
    if (visiting.has(id)) throw new Error(`Cycle in world folder ancestry at ${id}.`);
    visiting.add(id);
    const path = [...ancestry(folder.folder?.id ?? null), folder];
    visiting.delete(id);
    paths.set(id, path);
    return path;
  }

  const occupied = new Set<string>();
  const pinned = new Set<string>();
  for (const entry of entries) {
    for (const folder of ancestry(entry.folderId)) {
      (entry.imported ? occupied : pinned).add(folder.id);
    }
  }
  const deepest = new Map<string, number>();
  for (const folder of folders) {
    const path = ancestry(folder.id);
    for (const ancestor of path) {
      deepest.set(ancestor.id, Math.max(deepest.get(ancestor.id) ?? 0, path.length));
      // Leave unrelated empty branches and ancestors of the managed root in place.
      if (!occupied.has(folder.id) || folder.id === rootId) pinned.add(ancestor.id);
    }
  }

  const branches = new Map<FoundryFolder, FoundryFolder[]>();
  const documents: { id: string; path: FoundryFolder[] }[] = [];
  for (const entry of entries) {
    if (!entry.imported) continue;
    const path = ancestry(entry.folderId);
    if (path.some(({ id }) => id === rootId)) continue;
    const branchIndex = path.findIndex(
      ({ id }) => !pinned.has(id) && (deepest.get(id) ?? 0) < maxDepth,
    );
    if (branchIndex === -1) documents.push({ id: entry.id, path });
    else branches.set(path[branchIndex]!, path.slice(0, branchIndex));
  }
  return { branches, documents };
}
