import { repairWfrpDataModelMigrations } from "./repair-data-model-migrations";
import { repairWfrpRollModes } from "./repair-roll-modes";
import { repairOrphanedChatCards } from "./render-orphaned-chat-cards";
import { repairWfrpActiveEffectSchemas } from "./active-effect-schema";
import { guardActorlessTokenRuler } from "./guard-actorless-token-ruler";
import { installJournalCompendiumLinks } from "./journal-compendium-links";
import { installMapPinCompendiumLinks } from "./map-pin-compendium-links";
import { installRollTableCompendiumLookup } from "./roll-table-compendium-lookup";
import { DUAL_WIELDER_VERSIONS, repairDualWielderCleanup } from "./dual-wielder-cleanup";
import { installStartupFix, recordStartupFix } from "../../diagnostics/startup-report";
import { migrationReturnSupport } from "../../../functions/patches/wfrp4e/migration-return-support";

export function applyWfrp4eCompatibilityPatches(): void {
  if (game?.system.id !== "wfrp4e") {
    for (const id of [
      "rollModes",
      "migrationReturns",
      "effectSchema",
      "orphanedChat",
      "journalCompendiumLinks",
      "mapPinCompendiumLinks",
      "rollTableCompendiumLookup",
      "actorlessRuler",
      "dualWielder",
    ] as const) {
      recordStartupFix(id, "inactive", "Requires a WFRP4e world.");
    }
    return;
  }

  installStartupFix(
    "rollModes",
    repairWfrpRollModes,
    "WFRP received an independent copy of core roll modes.",
    {
      status: "unavailable",
      detail: "WFRP configuration or core Chat Message roll modes are unavailable.",
    },
  );

  const migrationSupport = migrationReturnSupport(game.system.version);
  if (migrationSupport === "fixed") {
    recordStartupFix(
      "migrationReturns",
      "not-needed",
      "WFRP 10.0.0+ returns migrated data natively; no wrapper installed.",
    );
  } else if (migrationSupport === "unknown") {
    recordStartupFix(
      "migrationReturns",
      "unsupported",
      "Migration fallback is verified only for WFRP 9.6.1–9.6.4; inspect this version.",
    );
  } else {
    installStartupFix(
      "migrationReturns",
      repairWfrpDataModelMigrations,
      "Fallback installed for WFRP 9.6.1–9.6.4 Actor/Item migration returns.",
      {
        status: "unavailable",
        detail: "No callable Actor/Item migration methods were available.",
      },
    );
  }

  if (!Object.keys(CONFIG.ActiveEffect?.dataModels ?? {}).length) {
    recordStartupFix(
      "effectSchema",
      "unavailable",
      "Active Effect data-model registry is unavailable or empty.",
    );
  } else
    installStartupFix(
      "effectSchema",
      repairWfrpActiveEffectSchemas,
      "Missing changes fields supplied using Foundry's schema factory.",
      {
        status: "not-needed",
        detail: "All registered effect models already define changes.",
      },
    );
  installStartupFix(
    "orphanedChat",
    repairOrphanedChatCards,
    "Text fallback installed for chat cards with missing actor/token references.",
    {
      status: "unavailable",
      detail: "The chat document renderer is unavailable.",
    },
  );
  installStartupFix(
    "journalCompendiumLinks",
    installJournalCompendiumLinks,
    "Compendium fallback installed for missing journal links and embeds.",
    {
      status: "unavailable",
      detail: "Foundry's text enrichment or UUID resolution API is unavailable.",
    },
  );
  installStartupFix(
    "mapPinCompendiumLinks",
    installMapPinCompendiumLinks,
    "Compendium fallback installed for map pins with missing world journals.",
    { status: "unavailable", detail: "Foundry's map note or UUID resolution API is unavailable." },
  );
  installStartupFix(
    "rollTableCompendiumLookup",
    installRollTableCompendiumLookup,
    "Compendium fallback installed for WFRP chat table rolls.",
    {
      status: "unavailable",
      detail: "WFRP's chat table or Foundry's UUID resolution API is unavailable.",
    },
  );
  const usesCoreRuler =
    CONFIG.Token?.rulerClass?.prototype ===
    foundry.canvas?.placeables?.tokens?.TokenRuler?.prototype;
  installStartupFix(
    "actorlessRuler",
    guardActorlessTokenRuler,
    "Core-style fallback installed for tokens without actors.",
    {
      status: usesCoreRuler && !!CONFIG.Token?.rulerClass ? "not-needed" : "unavailable",
      detail:
        usesCoreRuler && !!CONFIG.Token?.rulerClass
          ? "The world uses Foundry's core ruler."
          : "The expected WFRP/core ruler methods are unavailable.",
    },
  );
  if (!DUAL_WIELDER_VERSIONS.includes(game.system.version)) {
    recordStartupFix(
      "dualWielder",
      "unsupported",
      "Cleanup is verified for WFRP 10.0.3 and 10.1.2; inspect this version before enabling.",
    );
  } else {
    installStartupFix(
      "dualWielder",
      repairDualWielderCleanup,
      "Duplicate status deletion filtered; the unique GM retains turn-start cleanup.",
      {
        status: "unavailable",
        detail: "Actor script collection is unavailable.",
      },
    );
  }
}
