import type { WfrpPackFolder } from "../../../types/wfrp/Folders";

/** The enclosing Warhammer Fantasy Roleplay root already identifies the game. */
export function wfrpFolderName(name: string): string {
  return name.replace(/^(?:WFRP(?:4e|5e)?|Warhammer Fantasy Roleplay)\s*[-–—:]\s*/i, "");
}

/** Read publisher defaults rather than maintaining a second palette or book list. */
export function wfrpFolderDefaults(packages: Iterable<[string, Iterable<WfrpPackFolder>]>) {
  const colors = new Map<string, string>();
  const packPaths = new Map<string, string[]>();
  for (const [id, folders] of packages) {
    const visit = (folder: WfrpPackFolder, parent: string[]) => {
      const name = wfrpFolderName(folder.name);
      const path = [...parent, name];
      if (folder.color != null) colors.set(name, folder.color.toString());
      for (const pack of folder.packs ?? []) packPaths.set(`${id}.${pack}`, path);
      for (const child of folder.folders ?? []) visit(child, path);
    };
    for (const folder of folders) visit(folder, []);
  }
  return { colors, packPaths };
}
